function retrackersTestReadCapability($capability)
{
	$descriptors = array(
		0 => array('pipe', 'r'),
		1 => array('pipe', 'w'),
		2 => array('pipe', 'w'),
	);
	$process = @proc_open(array('/bin/cat', $capability), $descriptors, $pipes);
	if (!is_resource($process)) {
		return(false);
	}
	fclose($pipes[0]);
	$bytes = stream_get_contents($pipes[1]);
	fclose($pipes[1]);
	$error = stream_get_contents($pipes[2]);
	fclose($pipes[2]);
	$status = proc_close($process);
	return($status === 0 && $error === '' ? $bytes : false);
}

function retrackersTestCapabilityIdentityClosed(array $proof)
{
	if (!isset($proof['capability'], $proof['dev'], $proof['ino']) ||
		!is_string($proof['capability'])) {
		return(false);
	}
	clearstatcache(true, $proof['capability']);
	$stat = @stat($proof['capability']);
	return(!is_array($stat) || (string)$stat['dev'] !== (string)$proof['dev'] ||
		(string)$stat['ino'] !== (string)$proof['ino']);
}

