	private function requireCodecApi()
	{
		$functions = array(
			'retrackersDecodeRestrictedRawResponse',
			'retrackersRestrictedPlanDirectScalar',
			'retrackersRestrictedPlanLedgerHas',
			'retrackersRestrictedPlanDownloadRows',
			'retrackersRestrictedPlanTrackerRows',
			'retrackersRestrictedPlanGenericMap',
			'retrackersRestrictedPlanScalarBatch',
			'retrackersRestrictedPlanLedger',
			'retrackersRestrictedPlanHistoricalBindingV2',
			'retrackersHistoricalEmptyDigestVectors',
			'retrackersBuildHistoricalBindingRequestV2',
		);
		foreach ($functions as $function) {
			if (!function_exists($function)) {
				$this->assertTrue(false, 'update.php declares the restricted RAW codec API: ' . $function);
				return(false);
			}
		}
		if (!class_exists('RetrackersDirectRpcAdapter', false)) {
			$this->assertTrue(false, 'update.php declares the final RAW transport adapter');
			return(false);
		}
		return(true);
	}

