	private function sourceQueueAdapter($scalars, $maps, $trackers)
	{
		return(new class($scalars, $maps, $trackers) extends RetrackersDirectRpcAdapter {
			public $calls = array();
			private $scalars;
			private $maps;
			private $trackers;

			public function __construct($scalars, $maps, $trackers)
			{
				$this->scalars = $scalars;
				$this->maps = $maps;
				$this->trackers = $trackers;
			}

			private function next(&$queue, $kind, $hash, &$failure)
			{
				$this->calls[] = $kind . ':' . $hash;
				if (count($queue) === 0) {
					$failure = 'unexpected-read';
					return(false);
				}
				$value = array_shift($queue);
				if (isset($value['failure'])) {
					$failure = $value['failure'];
					return(false);
				}
				$failure = null;
				return($value);
			}

			public function sourceScalarSnapshot($hash, &$failure = null)
			{
				return($this->next($this->scalars, 'scalar', $hash, $failure));
			}

			public function sourceGenericMapSnapshot($hash, &$failure = null)
			{
				return($this->next($this->maps, 'map', $hash, $failure));
			}

			public function sourceTrackerSnapshot($hash, &$failure = null)
			{
				return($this->next($this->trackers, 'tracker', $hash, $failure));
			}
		});
	}

	private function replaceRawBodyOnce($raw, $before, $after)
	{
		$delimiter = strpos($raw, "\r\n\r\n");
		$body = substr($raw, $delimiter + 4);
		$this->assertTrue(substr_count($body, $before) === 1,
			'the adversarial mutation target occurs exactly once');
		$body = str_replace($before, $after, $body);
		return('Status: 200 OK' . "\r\n" . 'Content-Type: text/xml' . "\r\n" .
			'Content-Length: ' . strlen($body) . "\r\n\r\n" . $body);
	}

	private function tinyRawResponse($resultNode)
	{
		$body = '<?xml version="1.0"?><methodResponse><params><param><value>' . $resultNode .
			'</value></param></params></methodResponse>';
		return('Status: 200 OK' . "\r\n" . 'Content-Type: text/xml' . "\r\n" .
			'Content-Length: ' . strlen($body) . "\r\n\r\n" . $body);
	}

