	private function capturedDuplicateLedgerFault($family)
	{
		$captures = array(
			1 => array(
				'',
				292, 'd8734faed2790c96060fa1d5898702bc4e3db38bf11f0d921ac0d9d40d678384'),
			2 => array(
				'',
				253, '2a6e465a6460590fb9c66efde2608365708f47b3e6a3275b5015e8f94cc23fde'),
		);
		$body = base64_decode($captures[$family][0], true);
		$this->assertTrue(is_string($body) && strlen($body) === $captures[$family][1] &&
			hash('sha256', $body) === $captures[$family][2],
			'family ' . $family . ' duplicate-ledger fixture retains its literal measured BODY');
		return('Status: 200 OK' . "\r\n" . 'Content-Type: text/xml' . "\r\n" .
			'Content-Length: ' . strlen($body) . "\r\n\r\n" . $body);
	}

	private function tinyHistoricalResponseWithFault($nodes, $faultSlot)
	{
		$slots = '';
		foreach ($nodes as $slot => $node) {
			if ($slot === $faultSlot) {
				$slots .= '<value><struct><member><name>faultCode</name><value><i8>-506</i8></value>' .
					'</member><member><name>faultString</name><value><string>method not found</string>' .
					'</value></member></struct></value>';
			} else {
				$slots .= '<value><array><data><value>' . $node . '</value></data></array></value>';
			}
		}
		return($this->tinyRawResponse('<array><data>' . $slots . '</data></array>'));
	}

