	private function packedRecoveryRows4($rows)
	{
		$packed = "RR4\0" . pack('N', count($rows));
		foreach ($rows as $row) {
			foreach ($row as $cell) {
				$packed .= pack('N', strlen($cell)) . $cell;
			}
		}
		return($packed);
	}

	private function packedRecoveryRows4Range($count)
	{
		$packed = "RR4\0" . pack('N', $count);
		for ($index = 1; $index <= $count; $index++) {
			$hash = str_pad(strtoupper(dechex($index)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index)), 39, '0', STR_PAD_LEFT);
			foreach (array($hash, $localId, '', '') as $cell) {
				$packed .= pack('N', strlen($cell)) . $cell;
			}
		}
		return($packed);
	}

	private function recoveryDecisionClasses($packed)
	{
		if (substr($packed, 0, 4) !== "RD4\0") {
			return(false);
		}
		$count = unpack('Ncount', substr($packed, 4, 4))['count'];
		$offset = 8;
		$classes = '';
		for ($index = 0; $index < $count; $index++) {
			$offset += 80;
			$classes .= $packed[$offset++];
			$offset++;
			$payloadLength = unpack('Nlength', substr($packed, $offset, 4))['length'];
			$offset += 4 + $payloadLength + 4 + 32 + 4 + 32;
		}
		return($offset === strlen($packed) ? $classes : false);
	}

	private function tinyRecoveryRowsNode($count)
	{
		if ($count === 0) {
			return('<array><data/></array>');
		}
		$rows = '';
		for ($index = 1; $index <= $count; $index++) {
			$hash = str_pad(strtoupper(dechex($index)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index)), 39, '0', STR_PAD_LEFT);
			$rows .= '<value><array><data><value><string>' . $hash . '</string></value>' .
				'<value><string>' . $localId . '</string></value>' .
				'<value><string></string></value><value><string></string></value>' .
				'</data></array></value>';
		}
		return('<array><data>' . $rows . '</data></array>');
	}

