	private function tinyOpaqueTextAction($extraBytes)
	{
		$full = str_repeat('x', 1048576);
		$children = '';
		for ($index = 0; $index < 8; $index++) {
			$children .= '<value><string>' . $full . '</string></value>';
		}
		if ($extraBytes > 0) {
			$children .= '<value><string>' . str_repeat('x', $extraBytes) . '</string></value>';
		}
		return('<array><data>' . $children . '</data></array>');
	}

	private function tinyGenericNamesResponse($extraNameBytes)
	{
		$members = '';
		for ($index = 0; $index < 512; $index++) {
			$name = str_pad(strtoupper(dechex($index)), 8, '0', STR_PAD_LEFT) . str_repeat('n', 4088);
			$members .= '<member><name>' . $name .
				'</name><value><string></string></value></member>';
		}
		if ($extraNameBytes > 0) {
			$members .= '<member><name>' . str_repeat('x', $extraNameBytes) .
				'</name><value><string></string></value></member>';
		}
		return($this->tinyRawResponse('<struct>' . $members . '</struct>'));
	}

	private function tinyProjectedRecoveryResponse($lastMarkerBytes)
	{
		$rows = '';
		for ($index = 1; $index <= 8; $index++) {
			$hash = str_pad(strtoupper(dechex($index)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index)), 39, '0', STR_PAD_LEFT);
			$markerBytes = $index <= 7 ? 1048576 : $lastMarkerBytes;
			$rows .= '<value><array><data><value><string>' . $hash . '</string></value>' .
				'<value><string>' . $localId . '</string></value>' .
				'<value><string>' . str_repeat('m', $markerBytes) . '</string></value>' .
				'<value><string></string></value></data></array></value>';
		}
		return($this->tinyHistoricalResponse(array(
			'<array><data/></array>',
			'<struct/>',
			'<array><data>' . $rows . '</data></array>',
			'<array><data/></array>',
			'<struct/>',
		)));
	}

	private function installRawTransportDouble()
	{
		if (class_exists('rSCGITransport', false)) {
			if (property_exists('rSCGITransport', 'calls')) {
				return(true);
			}
			$this->assertTrue(false, 'the adapter test process owns an isolated RAW transport double');
			return(false);
		}
		eval(<<<'PHP'
class rSCGITransport
{
	const RESPONSE_RAW = 'raw';
	const MISSING_RESPONSE_MODE = 'missing-response-mode';
	public static $calls = array();
	public static $raw = null;
	public static $returnNull = false;
	public static $delayMicros = 0;
	public static $failureWrite = 'transport-reference-written';
	public static $rawResponder = null;

	public static function send($host, $port, $payload, $trusted = true, $connectTimeout = 30,
		&$failure = null, $transferTimeout = null, $maxResponseBytes = null,
		$responseMode = self::MISSING_RESPONSE_MODE)
	{
		$failureBefore = $failure;
		$failure = self::$failureWrite;
		self::$calls[] = array(
			'argument_count' => func_num_args(),
			'arguments' => array($host, $port, $payload, $trusted, $connectTimeout,
				$failureBefore, $transferTimeout, $maxResponseBytes, $responseMode),
			'failure_after' => $failure,
		);
		if (self::$delayMicros > 0) {
			usleep(self::$delayMicros);
		}
		if (self::$returnNull) {
			$failure = 'transport-failed';
			return(null);
		}
		if (is_callable(self::$rawResponder)) {
			return(call_user_func(self::$rawResponder, $payload));
		}
		return(self::$raw);
	}
}
PHP
		);
		return(true);
	}

