	private function historicalProjectionFixture($actions, $ledgerKeys, $rows = null,
		$digest = null, $family = 2)
	{
		ksort($actions, SORT_STRING);
		sort($ledgerKeys, SORT_STRING);
		$entries = array();
		foreach ($actions as $name => $action) {
			if (is_array($action)) {
				$entries[] = array('name' => $name, 'type' => $action['type'],
					'digest' => str_repeat("\x7f", 32));
			} else {
				$entries[] = array('name' => $name, 'type' => 'string',
					'digest' => retrackersRestrictedHashString($action), 'value' => $action);
			}
		}
		if ($rows === null) {
			$rows = $this->packedRecoveryRows4(array());
		}
		$rowCount = unpack('Ncount', substr($rows, 4, 4))['count'];
		if ($digest === null) {
			$digest = hash('sha256', serialize(array($family, $actions, $ledgerKeys, $rows)));
		}
		$component = hash('sha256', 'component:' . $digest);
		return(array('ok' => true, 'family' => $family, 'value' => array(
			'digest' => $digest,
			'event_key_digest' => $component,
			'event_map_digest' => $component,
			'recovery_rows_digest' => $component,
			'ledger_key_digest' => $component,
			'ledger_map_digest' => $component,
			'ledger_digest' => $component,
			'event_keys' => array_keys($actions),
			'actions' => $entries,
			'recovery_rows' => $rows,
			'ledger_keys' => $ledgerKeys,
			'counts' => array('event_keys' => count($actions), 'actions' => count($actions),
				'recovery_rows' => $rowCount, 'ledger_keys' => count($ledgerKeys)),
			'production_accepted' => false,
		)));
	}

	private function historicalStateFixture($observation, $digest = null)
	{
		$alice = 'alice';
		$bob = 'bob';
		$aliceHash = hash('sha256', $alice);
		$bobHash = hash('sha256', $bob);
		$aliceF = 'functional-alice-exact-bytes';
		$bobF = 'functional-bob-exact-bytes';
		$epoch = 'pv:' . str_repeat('1', 32);
		$token = str_repeat('2', 32);
		$safety = $this->historicalSafetyActionFixture();
		$defer = $this->historicalDeferActionFixture();
		$actions = array();
		$ledger = array();
		$caller = $alice;
		$expected = $aliceF;
		$phase = $observation;
		if ($observation === 'BOOTSTRAP') {
			$phase = 'BOOTSTRAP';
		} elseif ($observation === 'IDLE_EMPTY_CURRENT') {
			$ledger[] = $epoch;
			$phase = 'IDLE_CURRENT';
		} elseif ($observation === 'IDLE_CURRENT') {
			$actions = array('tadd_trackers1alice' => $aliceF,
				'tadd_trackers2alice' => $safety);
			$ledger = array($epoch, 'pf:' . $aliceHash . ':' . hash('sha256', $aliceF));
			$phase = 'IDLE_CURRENT';
		} elseif ($observation === 'FIRST_INIT_OWNER') {
			$actions = array('tadd_trackers1alice' => $defer,
				'tadd_trackers2alice' => $defer);
			$ledger = array($epoch, 'ta:1', 'to:' . $token . ':i:' . $aliceHash,
				'pf:' . $aliceHash . ':' . hash('sha256', $aliceF));
			$phase = 'INIT_OWNER';
		} elseif ($observation === 'SECOND_INIT_OWNER') {
			$actions = array('tadd_trackers1alice' => $aliceF,
				'tadd_trackers2alice' => $safety,
				'tadd_trackers1bob' => $defer, 'tadd_trackers2bob' => $defer);
			$ledger = array($epoch, 'ta:1', 'to:' . $token . ':i:' . $bobHash,
				'pf:' . $aliceHash . ':' . hash('sha256', $aliceF),
				'pf:' . $bobHash . ':' . hash('sha256', $bobF));
			$caller = $bob;
			$expected = $bobF;
			$phase = 'INIT_OWNER';
		} elseif ($observation === 'DONE_OWNER') {
			$actions = array('tadd_trackers1alice' => $safety,
				'tadd_trackers2alice' => $safety);
			$ledger = array($epoch, 'ta:1', 'to:' . $token . ':d:' . $aliceHash,
				'pf:' . $aliceHash . ':' . hash('sha256', $aliceF));
			$phase = 'DONE_OWNER';
		} elseif ($observation === 'CONTAIN_OWNER') {
			$actions = array('tadd_trackers1alice' => $safety,
				'tadd_trackers2alice' => $safety,
				'tadd_trackers1bob' => $safety, 'tadd_trackers2bob' => $safety);
			$ledger = array($epoch, 'ma:1', 'ta:1', 'to:' . $token . ':c:' . $aliceHash);
			$phase = 'CONTAIN_OWNER';
		} elseif ($observation === 'CONTAINED') {
			$actions = array('tadd_trackers1alice' => $safety,
				'tadd_trackers2alice' => $safety,
				'tadd_trackers1bob' => $safety, 'tadd_trackers2bob' => $safety);
			$ledger = array($epoch, 'ma:1');
			$phase = 'CONTAINED';
		}
		return(array('sample' => $this->historicalProjectionFixture($actions, $ledger, null, $digest),
			'caller' => $caller, 'expected_functional' => $expected,
			'phase' => $phase, 'observation' => $observation));
	}

	private function historicalQueueAdapter($queue)
	{
		if (!class_exists('RetrackersHistoricalQueueAdapter', false)) {
			eval(<<<'PHP'
class RetrackersHistoricalQueueAdapter extends RetrackersDirectRpcAdapter
{
	public $queue;
	public $calls = 0;

	public function __construct($queue)
	{
		$this->queue = $queue;
	}

	public function historicalBindingSample(&$failure = null)
	{
		$this->calls++;
		if (count($this->queue) === 0) {
			$failure = 'unexpected-third-read';
			return(false);
		}
		$result = array_shift($this->queue);
		if (isset($result['failure'])) {
			$failure = $result['failure'];
			return(false);
