	private function lifecycleQueueAdapter($queue)
	{
		if (!class_exists('RetrackersLifecycleQueueAdapter', false)) {
			eval(<<<'PHP'
class RetrackersLifecycleQueueAdapter extends RetrackersLifecycleRpcAdapter
{
	public $queue;
	public $ensureCalled = false;
	public $attestCalled = false;
	public $callbackHistory = array();
	public $callbackReturnHistory = array();
	public $callbackResults = array();
	public $mutationFamilies = array();
	public $ledgerKeys = array();
	public $readbackQueue = array();
	public $readbackCalls = 0;
	public $readbackFailAt = null;
	public $downloadRowsQueue = array();
	public $downloadRowReads = 0;
	public $sourceScalarQueue = array();
	public $nativeFinalized = null;
	public $nativeIncarnation = null;
	public $nativeMethodsPresent = true;
	public $beforeCallbackActionChanges = array();
	public $beforeCallbackLedgerAdds = array();
	public $beforeCallbackLedgerRemoves = array();
	public $afterCallbackLedgerAdds = array();
	public $modelWriteCount = 0;
	private $initialSample;
	private $modelActions = null;
	private $modelLedger = null;
	private $modelDownloads = array();
	private $postBootstrapAcquireLedger = array();

	public function __construct($queue)
	{
		$this->queue = $queue;
		$this->initialSample = isset($queue[0]) ? $queue[0] : null;
		$this->family = isset($queue[0]['family']) ? $queue[0]['family'] : 2;
	}

	public function historicalBindingSample(&$failure = null)
	{
		if (count($this->queue) === 0) {
			$failure = 'queue-empty';
			return(false);
		}
		$failure = null;
		return(array_shift($this->queue));
	}

	public function nativeOriginalCapability(&$failure = null)
	{
		$failure = $this->nativeMethodsPresent ? null :
			'native-original-capability-unconfirmed';
		return($this->nativeMethodsPresent);
	}

	public function ensureLedgerExists(&$failure = null)
	{
		$this->ensureCalled = true;
		$failure = null;
		return(true);
	}

	public function attestLedger(&$failure = null)
	{
		$this->attestCalled = true;
		$failure = null;
		return(new RetrackersHistoricalLedgerAttestation(true, true, true, true));
	}

	private function initializeModel()
	{
		if ($this->modelActions !== null) {
			return;
		}
		$this->modelActions = array();
		$this->modelLedger = array();
		if (isset($this->initialSample['value']['actions'])) {
			foreach ($this->initialSample['value']['actions'] as $action) {
				if (isset($action['name'], $action['type'], $action['value']) &&
					$action['type'] === 'string') {
					$this->modelActions[$action['name']] = $action['value'];
				}
			}
		}
		if (isset($this->initialSample['value']['ledger_keys'])) {
			foreach ($this->initialSample['value']['ledger_keys'] as $key) {
				$this->modelLedger[$key] = true;
			}
		}
		if (count($this->modelLedger) === 0) {
			$this->postBootstrapAcquireLedger = $this->ledgerKeys;
		} else {
			foreach ($this->ledgerKeys as $key) {
				$this->modelLedger[$key] = true;
			}
		}
		$this->syncLedgerKeys();
	}

	private function syncLedgerKeys()
	{
		$this->ledgerKeys = array_keys($this->modelLedger);
		sort($this->ledgerKeys, SORT_STRING);
	}

	private function unquote($value)
	{
		$length = strlen($value);
		if ($length < 2 || $value[0] !== '"' || $value[$length - 1] !== '"') {
			return($value);
		}
		$output = '';
		for ($index = 1; $index < $length - 1; $index++) {
			if ($value[$index] === '\\' && $index + 1 < $length - 1) {
				$index++;
			}
			$output .= $value[$index];
		}
		return($output);
	}

	private function splitArguments($value)
	{
		$parts = array();
		$part = '';
		$quoted = false;
		$escaped = false;
		for ($index = 0; $index < strlen($value); $index++) {
			$byte = $value[$index];
			if ($escaped) {
				$part .= $byte;
				$escaped = false;
				continue;
			}
			if ($byte === '\\' && $quoted) {
				$part .= $byte;
				$escaped = true;
				continue;
			}
			if ($byte === '"') {
				$quoted = !$quoted;
				$part .= $byte;
				continue;
			}
			if ($byte === ',' && !$quoted) {
				$parts[] = $part;
				$part = '';
				continue;
			}
			$part .= $byte;
		}
		$parts[] = $part;
		return($parts);
	}

	private function actionKeyPresent($map, $key)
	{
		if ($map === 'rr.receipts.v1') {
			return(isset($this->modelLedger[$key]));
		}
		if ($map === 'event.download.inserted_new') {
			return(array_key_exists($key, $this->modelActions));
		}
		return(false);
	}

	private function expressionValue($expression, $target)
	{
		if ($expression === 'd.incarnation=') return($this->nativeIncarnation);
		if (strncmp($expression, 'system.retrackers.finalized=', strlen('system.retrackers.finalized=')) === 0)
			return($this->nativeFinalized === null ? 'none' :
				'finalized:' . $this->nativeFinalized['tx'] . ':' .
				$this->nativeFinalized['incarnation']);
		if ($expression === 'method.list_keys=rr.receipts.v1') {
			return(array_keys($this->modelLedger));
		}
		if (strncmp($expression, 'value=', 6) === 0) {
			return((int)substr($expression, 6));
		}
		if (strncmp($expression, 'cat=', 4) === 0) {
			$parts = $this->splitArguments(substr($expression, 4));
			$value = '';
			foreach ($parts as $part) {
				$value .= $this->unquote($part);
			}
			return($value);
		}
		$getters = array(
			'd.local_id=' => 'local_id',
			'd.state=' => 'state',
			'd.custom=retrackers-recovery' => 'recovery_marker',
			'd.custom=retrackers-recovery-ack' => 'recovery_ack',
			'd.custom=chk-meta-old' => 'chk_meta_old',
			'd.custom3=' => 'custom3',
		);
		if (isset($getters[$expression], $this->modelDownloads[$target])) {
			$key = $getters[$expression];
			$value = isset($this->modelDownloads[$target][$key]) ?
				$this->modelDownloads[$target][$key] : '';
			return($expression === 'd.state=' ? (int)$value : $value);
		}
		return(null);
	}

	private function evaluatePredicate($expression, $target)
	{
		if ($expression === 'not=(method.list_keys,rr.receipts.v1)') {
			return(count($this->modelLedger) === 0);
		}
		if (strncmp($expression, 'and=', 4) === 0) {
			$parts = $this->splitArguments(substr($expression, 4));
			return(count($parts) === 2 &&
				$this->evaluatePredicate($this->unquote($parts[0]), $target) &&
				$this->evaluatePredicate($this->unquote($parts[1]), $target));
		}
		if (strncmp($expression, 'not=', 4) === 0) {
			$operand = substr($expression, 4);
			// Captured on 0.9.8 and 0.16.21: not treats a quoted command as a string,
			// unlike and/branch. A parenthesized command object is evaluated first.
			if (substr($operand, 0, 1) === '(' && substr($operand, -1) === ')') {
				$command = substr($operand, 1, -1);
				$comma = strpos($command, ',');
				$command = substr($command, 0, $comma) . '=' . substr($command, $comma + 1);
				return(!$this->evaluatePredicate($command, $target));
			}
			return($this->unquote($operand) === '');
		}
		if (strncmp($expression, 'method.has_key=', 15) === 0) {
			$parts = $this->splitArguments(substr($expression, 15));
			return(count($parts) === 2 && $this->actionKeyPresent($parts[0], $parts[1]));
		}
		if (strncmp($expression, 'equal=', 6) === 0) {
			$parts = $this->splitArguments(substr($expression, 6));
			return(count($parts) === 2 &&
				$this->expressionValue($this->unquote($parts[0]), $target) ===
				$this->expressionValue($this->unquote($parts[1]), $target));
		}
		if ($expression === 'd.custom=chk-meta-old') {
			$value = $this->expressionValue($expression, $target);
			return(is_string($value) && $value !== '' && $value !== '0');
		}
		return(false);
	}

	private function setModelKey($map, $key, $valuePresent, $value = null)
	{
		if ($map === 'rr.receipts.v1') {
			if ($valuePresent) {
				$this->modelLedger[$key] = true;
			} else {
				unset($this->modelLedger[$key]);
			}
			$this->syncLedgerKeys();
			return;
		}
		if ($map === 'event.download.inserted_new') {
			if ($valuePresent) {
				$this->modelActions[$key] = $value;
			} else {
				unset($this->modelActions[$key]);
			}
		}
	}

	private function executeCommand($command, $target)
	{
		if (strncmp($command, '$branch=', 8) === 0) {
			$parts = $this->splitArguments(substr($command, 8));
			if (count($parts) === 3 &&
				strncmp($this->unquote($parts[0]), '$execute.throw.bg=', 18) === 0 &&
				$this->unquote($parts[1]) === 'cat=' &&
				$this->unquote($parts[2]) === 'cat=') {
				$this->executeCommand($this->unquote($parts[0]), $target);
			}
			return;
		}
		if (strncmp($command, '$method.set_key=', 16) === 0) {
			$parts = $this->splitArguments(substr($command, 16));
			if (count($parts) >= 2) {
				$this->setModelKey($parts[0], $parts[1], count($parts) >= 3,
					count($parts) >= 3 ? $this->unquote($parts[2]) : null);
				$this->modelWriteCount++;
			}
			return;
		}
		if (strncmp($command, '$d.custom.set=', 14) === 0 && isset($this->modelDownloads[$target])) {
			$parts = $this->splitArguments(substr($command, 14));
			$keys = array('retrackers-recovery' => 'recovery_marker',
				'retrackers-recovery-ack' => 'recovery_ack');
			if (isset($parts[0], $keys[$parts[0]])) {
				$this->modelDownloads[$target][$keys[$parts[0]]] = isset($parts[1]) ?
					$this->unquote($parts[1]) : '';
				$this->modelWriteCount++;
			}
			return;
		}
		if (strncmp($command, '$execute.throw.bg=', 18) === 0 &&
			isset($this->modelDownloads[$target]['local_id'])) {
			$localId = $this->modelDownloads[$target]['local_id'];
			unset($this->modelLedger['wp:' . $localId]);
			$this->modelDownloads[$target]['recovery_marker'] = '';
			$this->modelDownloads[$target]['recovery_ack'] = '';
			$this->syncLedgerKeys();
		}
	}

	private function executeBody($body, $target)
	{
		if (strncmp($body, 'cat=', 4) !== 0) {
			return(false);
		}
		$parts = $this->splitArguments(substr($body, 4));
		if (count($parts) === 0 || array_pop($parts) !== 'ACQUIRED') {
			return(false);
		}
		foreach ($parts as $part) {
			$this->executeCommand($this->unquote($part), $target);
		}
		return(true);
	}

	private function applyBeforeCallbackMutation()
	{
		foreach ($this->beforeCallbackLedgerRemoves as $key) {
			unset($this->modelLedger[$key]);
		}
		foreach ($this->beforeCallbackLedgerAdds as $key) {
			$this->modelLedger[$key] = true;
		}
		foreach ($this->beforeCallbackActionChanges as $key => $value) {
			if ($value === null) {
				unset($this->modelActions[$key]);
			} else {
				$this->modelActions[$key] = $value;
			}
		}
		$this->beforeCallbackLedgerRemoves = array();
		$this->beforeCallbackLedgerAdds = array();
		$this->beforeCallbackActionChanges = array();
		$this->syncLedgerKeys();
	}

	private function modelSample()
	{
		$actions = $this->modelActions;
		ksort($actions, SORT_STRING);
		$entries = array();
		foreach ($actions as $name => $action) {
			$entries[] = array('name' => $name, 'type' => 'string',
				'digest' => retrackersRestrictedHashString($action), 'value' => $action);
		}
		$this->syncLedgerKeys();
		$digest = hash('sha256', serialize(array($this->family, $actions, $this->ledgerKeys)));
		$component = hash('sha256', 'component:' . $digest);
		return(array('ok' => true, 'family' => $this->family, 'value' => array(
			'digest' => $digest, 'event_key_digest' => $component,
			'event_map_digest' => $component, 'recovery_rows_digest' => $component,
			'ledger_key_digest' => $component, 'ledger_map_digest' => $component,
			'ledger_digest' => $component, 'event_keys' => array_keys($actions),
			'actions' => $entries, 'recovery_rows' => "RR4\0" . pack('N', 0),
			'ledger_keys' => $this->ledgerKeys,
			'counts' => array('event_keys' => count($actions), 'actions' => count($actions),
				'recovery_rows' => 0, 'ledger_keys' => count($this->ledgerKeys)),
			'production_accepted' => false,
		)));
	}

	public function executeLifecycleCallback(RetrackersLifecycleCallbacks $callback, &$failure = null)
	{
		$this->initializeModel();
		$this->callbackHistory[] = $callback;
		$this->mutationFamilies[] = $this->getFamily();
		$this->applyBeforeCallbackMutation();
		$matches = $this->evaluatePredicate($callback->params()[1], $callback->params()[0]);
		$result = count($this->callbackResults) > 0 ? array_shift($this->callbackResults) :
			($matches ? 'ACQUIRED' : 'CHANGED');
		if ($matches && ($result === 'ACQUIRED' || $result === false)) {
			$this->executeBody($callback->params()[2], $callback->params()[0]);
		}
		if ($callback->name() === 'bootstrap-acquire') {
			foreach ($this->postBootstrapAcquireLedger as $key) {
				$this->modelLedger[$key] = true;
			}
