	private function assertTextOrder($text, array $needles, $message)
	{
		$offset = -1;
		foreach ($needles as $needle) {
			$next = strpos($text, $needle, $offset + 1);
			if ($next === false) {
				$this->assertTrue(false, $message . ': missing ' . $needle);
				return;
			}
			if ($next <= $offset) {
				$this->assertTrue(false, $message . ': out of order ' . $needle);
				return;
			}
			$offset = $next;
		}
		$this->assertTrue(true, $message);
	}

