	{
		self::$root = $root;
		self::$options = $options;
		return(parent::create($candidate, $original, $failure));
	}

	protected function temporaryRoot()
	{
		return(self::$root . '/');
	}

	protected function writeFile($handle, $bytes)
	{
		$this->writeRequests[] = strlen($bytes);
		$mode = isset(self::$options['write']) ? self::$options['write'] : 'normal';
		if ($mode === 'false') {
			return(false);
		}
		if ($mode === 'zero') {
			return(0);
		}
		if ($mode === 'over-count') {
			return(strlen($bytes) + 1);
		}
		if ($mode === 'short' && strlen($bytes) > 7) {
			$bytes = substr($bytes, 0, 7);
		}
		return(parent::writeFile($handle, $bytes));
	}

	protected function flushFile($handle)
	{
		return(isset(self::$options['flush-failure']) ? false : parent::flushFile($handle));
	}

	protected function lstatPath($path)
	{
		$stat = parent::lstatPath($path);
		if (!is_array($stat)) {
			return($stat);
		}
		$this->pathStatCalls[$path] = isset($this->pathStatCalls[$path]) ?
			$this->pathStatCalls[$path] + 1 : 1;
		$type = $stat['mode'] & 0170000;
		if ($type === 0100000 && isset(self::$options['file-drift'])) {
			switch (self::$options['file-drift']) {
			case 'inode': $stat['ino']++; break;
			case 'mode': $stat['mode'] = ($stat['mode'] & ~07777) | 0640; break;
			case 'owner': $stat['uid']++; break;
			case 'link': $stat['nlink']++; break;
			}
		}
		if ($type === 0040000 && isset(self::$options['directory-drift']) &&
			$this->pathStatCalls[$path] > 1) {
			$stat['ino']++;
		}
		return($stat);
	}

	protected function unlinkFile($path)
	{
		$result = parent::unlinkFile($path);
		if ($result) {
			$this->unlinked = true;
		}
		return($result);
	}

	protected function statHandle($handle)
	{
		$stat = parent::statHandle($handle);
		if (is_array($stat) && $this->unlinked && isset(self::$options['post-unlink-link'])) {
			$stat['nlink'] = 1;
