	private function scriptedFileReader()
	{
		if (!class_exists('RetrackersBoundedFileReader', false)) {
			return(null);
		}
		if (!class_exists('RetrackersScriptedFileReader', false)) {
			eval(<<<'PHP'
class RetrackersScriptedFileReader extends RetrackersBoundedFileReader
{
	public $openCount = 0;
	public $closeCount = 0;
	public $readRequests = array();
	public $readScript = array();
	public $eofScript = array();
	public $metadataOverride = null;
	public $statOverrideSet = false;
	public $statOverride = null;

	protected function openPath($path)
	{
		$this->openCount++;
		return(parent::openPath($path));
	}

	protected function openedMetadata($handle)
	{
		return(is_array($this->metadataOverride) ? $this->metadataOverride :
			parent::openedMetadata($handle));
	}

	protected function openedStat($handle)
	{
		return($this->statOverrideSet ? $this->statOverride : parent::openedStat($handle));
	}

	protected function readOpened($handle, $length)
	{
		$this->readRequests[] = $length;
		return(count($this->readScript) ? array_shift($this->readScript) :
			parent::readOpened($handle, $length));
	}

	protected function openedEof($handle)
	{
		return(count($this->eofScript) ? array_shift($this->eofScript) :
			parent::openedEof($handle));
	}

	protected function closeOpened($handle)
	{
		$this->closeCount++;
		return(parent::closeOpened($handle));
	}
}
PHP
			);
		}
		return(new RetrackersScriptedFileReader());
	}

	private function boundedReaderEnvelopeProbe($size)
	{
		$script = <<<'PHP'
define('RETRACKERS_IMPORT_ONLY', true);
require $argv[1];
class RetrackersEnvelopeProbeReader extends RetrackersBoundedFileReader
{
	public $maxRequest = 0;
	public $lastRequest = 0;
	public $closeCount = 0;
	protected function readOpened($handle, $length)
	{
		$this->maxRequest = max($this->maxRequest, $length);
		$this->lastRequest = $length;
		return(parent::readOpened($handle, $length));
	}
	protected function closeOpened($handle)
	{
		$this->closeCount++;
		return(parent::closeOpened($handle));
	}
}
$size = (int)$argv[2];
$path = tempnam(sys_get_temp_dir(), 'retrackers-envelope-');
register_shutdown_function(function() use ($path) { @unlink($path); });
$handle = fopen($path, 'wb');
if (!is_resource($handle) || !ftruncate($handle, $size) || !fclose($handle)) {
	exit(20);
}
$reader = new RetrackersEnvelopeProbeReader();
$result = $reader->capture($path);
$verdict = $result['ok'] === true ? 'ok' : $result['reason'];
$bytes = $result['ok'] === true ? strlen($result['bytes']) : -1;
echo implode("\t", array(ini_get('memory_limit'), $verdict, $bytes,
	$reader->maxRequest, $reader->lastRequest, $reader->closeCount,
	memory_get_peak_usage(true)));
PHP;
		$descriptors = array(
			0 => array('pipe', 'r'),
			1 => array('pipe', 'w'),
			2 => array('pipe', 'w'),
		);
		$process = proc_open(array(PHP_BINARY, '-c', __DIR__ . '/../../php-test.ini',
			'-d', 'memory_limit=128M', '-r', $script, '--',
			realpath(__DIR__ . '/../../../plugins/retrackers/update.php'), (string)$size),
			$descriptors, $pipes);
		if (!is_resource($process)) {
			return(false);
		}
		fclose($pipes[0]);
		$output = stream_get_contents($pipes[1]);
		fclose($pipes[1]);
		$error = stream_get_contents($pipes[2]);
		fclose($pipes[2]);
		$status = proc_close($process);
		$fields = explode("\t", $output);
		if ($status !== 0 || $error !== '' || count($fields) !== 7) {
			return(false);
		}
		return(array(
			'memory_limit' => $fields[0],
			'verdict' => $fields[1],
			'bytes' => (int)$fields[2],
			'max_request' => (int)$fields[3],
			'last_request' => (int)$fields[4],
			'close_count' => (int)$fields[5],
			'peak_bytes' => (int)$fields[6],
		));
	}

