	private function recordingTorrentProjector()
	{
		if (!class_exists('RetrackersTorrentProjector', false) || !$this->loadTorrentRuntime()) {
			return(null);
		}
		if (!class_exists('RetrackersRecordingTorrentProjector', false)) {
			eval(<<<'PHP'
class RetrackersRecordingTorrentProjector extends RetrackersTorrentProjector
{
	public $constructionCount = 0;
	public $constructionInputs = array();

	protected function constructTorrent($capture)
	{
		$this->constructionCount++;
		$this->constructionInputs[] = $capture;
		return(parent::constructTorrent($capture));
	}
}
PHP
			);
		}
		return(new RetrackersRecordingTorrentProjector());
	}

	private function replacingFileReader($replacementPath)
	{
		if (!class_exists('RetrackersBoundedFileReader', false)) {
			return(null);
		}
		if (!class_exists('RetrackersReplacingFileReader', false)) {
			eval(<<<'PHP'
class RetrackersReplacingFileReader extends RetrackersBoundedFileReader
{
	public $replacementPath;

	public function capture($path)
	{
		$result = parent::capture($path);
		if (is_string($this->replacementPath)) {
			rename($this->replacementPath, $path);
		}
		return($result);
	}
}
PHP
			);
		}
		$reader = new RetrackersReplacingFileReader();
		$reader->replacementPath = $replacementPath;
		return($reader);
	}

