	public function testBoundedReaderOpensOnePlainRegularTargetAndAcceptsItsSymlink()
	{
		if (!class_exists('RetrackersBoundedFileReader', false)) {
			$this->assertTrue(false, 'update.php declares the one-open bounded plain-file reader');
			return;
		}
		$target = $this->metainfoFixturePath('reader-target.torrent');
		$link = $this->metainfoFixturePath('reader-link.torrent');
		file_put_contents($target, 'raw-source-bytes');
		symlink($target, $link);
		$reader = $this->scriptedFileReader();
		$result = $reader->capture($link);
		$this->assertTrue($result === array('ok' => true, 'bytes' => 'raw-source-bytes') &&
			$reader->openCount === 1 && $reader->closeCount === 1 &&
			count($reader->readRequests) === 1 && max($reader->readRequests) <= 65536,
			'a symlink is opened once and accepted only through its regular plainfile target');
	}

	public function testBoundedReaderRejectsOpenWrapperStatAndNonRegularModesBeforeRead()
	{
		if (!class_exists('RetrackersBoundedFileReader', false)) {
			$this->assertTrue(false, 'update.php declares reader descriptor refusal before fread');
			return;
		}
		$missing = $this->scriptedFileReader();
		$missingResult = $missing->capture($this->metainfoFixturePath('absent.torrent'));
		$this->assertTrue($missingResult === array('ok' => false, 'reason' => 'source-unreadable') &&
			$missing->openCount === 1 && $missing->closeCount === 0 && count($missing->readRequests) === 0,
			'an open failure is source-unreadable with no read or close of a nonexistent handle');

		$path = $this->metainfoFixturePath('descriptor-source.torrent');
		file_put_contents($path, 'x');
		$unknown = $this->scriptedFileReader();
		$unknown->metadataOverride = array('wrapper_type' => 'unknown-wrapper');
		$unknownResult = $unknown->capture($path);
		$this->assertTrue($unknownResult === array('ok' => false, 'reason' => 'source-not-regular') &&
			$unknown->closeCount === 1 && count($unknown->readRequests) === 0,
			'an opened non-plainfile wrapper is rejected before its first read');

		$failedStat = $this->scriptedFileReader();
		$failedStat->statOverrideSet = true;
		$failedStat->statOverride = false;
		$failedStatResult = $failedStat->capture($path);
		$this->assertTrue($failedStatResult === array('ok' => false, 'reason' => 'source-not-regular') &&
			$failedStat->closeCount === 1 && count($failedStat->readRequests) === 0,
			'an fstat failure is rejected and the opened handle is still closed without reading');

		$modes = array(0010000, 0020000, 0040000, 0060000, 0140000);
		foreach ($modes as $mode) {
			$reader = $this->scriptedFileReader();
			$reader->statOverrideSet = true;
			$reader->statOverride = array('mode' => $mode);
			$result = $reader->capture($path);
			$this->assertTrue($result === array('ok' => false, 'reason' => 'source-not-regular') &&
				$reader->closeCount === 1 && count($reader->readRequests) === 0,
				'a FIFO/device/directory/socket descriptor mode is rejected with zero reads: ' . decoct($mode));
		}
	}

	public function testBoundedReaderRejectsFalseEmptyAndPositiveShortNonEofReads()
	{
		if (!class_exists('RetrackersBoundedFileReader', false)) {
			$this->assertTrue(false, 'update.php declares strict false and short-read handling');
			return;
		}
		$path = $this->metainfoFixturePath('short-source.torrent');
		file_put_contents($path, 'unused');
		$cases = array(
			array(false, array(), 'source-read-error'),
			array('', array(false), 'source-short-read'),
			array('x', array(false), 'source-short-read'),
		);
		foreach ($cases as $case) {
			$reader = $this->scriptedFileReader();
			$reader->readScript = array($case[0]);
			$reader->eofScript = $case[1];
			$result = $reader->capture($path);
			$this->assertTrue($result === array('ok' => false, 'reason' => $case[2]) &&
				count($reader->readRequests) === 1 && $reader->closeCount === 1,
				$case[2] . ' closes immediately without retrying the failed read state');
		}

		$normal = $this->scriptedFileReader();
		$normal->readScript = array('short-at-eof');
		$normal->eofScript = array(true);
		$this->assertEquals(array('ok' => true, 'bytes' => 'short-at-eof'), $normal->capture($path),
			'a positive short read is accepted only when EOF is already true');
	}

	public function testBoundedReaderAcceptsEmptyCapMinusOneAndExactCapButRejectsCapPlusOne()
	{
		if (!class_exists('RetrackersBoundedFileReader', false) ||
			!defined('RETRACKERS_METAINFO_CAP')) {
			$this->assertTrue(false, 'update.php declares the exact 64 MiB reader boundary');
			return;
		}
		$emptyPath = $this->metainfoFixturePath('empty-source.torrent');
		file_put_contents($emptyPath, '');
		$emptyReader = $this->scriptedFileReader();
		$this->assertEquals(array('ok' => true, 'bytes' => ''), $emptyReader->capture($emptyPath),
			'a zero-length regular source reaches the bencode layer as an empty capture');

		foreach (array(RETRACKERS_METAINFO_CAP - 1, RETRACKERS_METAINFO_CAP,
			RETRACKERS_METAINFO_CAP + 1) as $size) {
			$result = $this->boundedReaderEnvelopeProbe($size);
			$this->assertTrue(is_array($result) && $result['memory_limit'] === '128M' &&
				$result['peak_bytes'] <= 128 * 1024 * 1024,
				'the size-' . $size . ' reader probe preserves the literal 128M acceptance limit');
			if (!is_array($result)) {
				continue;
			}
			if ($size <= RETRACKERS_METAINFO_CAP) {
				$this->assertTrue($result['verdict'] === 'ok' && $result['bytes'] === $size &&
					$result['max_request'] <= 65536 && $result['close_count'] === 1,
					'a regular source at size ' . $size . ' is accepted with bounded reads');
				if ($size === RETRACKERS_METAINFO_CAP) {
					$this->assertTrue($result['last_request'] === 1,
						'an exact-CAP source performs the mandatory final one-byte EOF probe');
				}
			} else {
				$this->assertTrue($result['verdict'] === 'source-too-large' && $result['bytes'] === -1 &&
					$result['last_request'] === 1 && $result['close_count'] === 1,
					'a CAP+1 source is rejected immediately after the bounded one-byte probe');
			}
		}
	}

	public function testBencodeScannerAcceptsUnsortedSourceAndRetainsOffsetDescriptors()
	{
		if (!class_exists('RetrackersBencodeScanner', false)) {
			$this->assertTrue(false, 'update.php declares the iterative immutable bencode scanner');
			return;
		}
		$info = $this->rawInfoFixture();
		$source = $this->metainfoWithRawInfo($info,
			'7:unknown3:raw' . '1:zi999999999999999999999999999e');
		$scanner = new RetrackersBencodeScanner();
		$scan = $scanner->scan($source, strtoupper(sha1($info)));
		$this->assertTrue($scan['ok'] === true &&
			$scan['root'] === array('offset' => 0, 'length' => strlen($source), 'type' => 'dictionary') &&
			$scan['info']['offset'] === strpos($source, $info) &&
			$scan['info']['length'] === strlen($info) && count($scan['top']) === 3,
			'an unsorted source and arbitrary canonical integer retain exact root, info, and top descriptors');
		$names = array();
		foreach ($scan['top'] as $entry) {
			$names[] = substr($source, $entry['key']['offset'], $entry['key']['length']);
			$this->assertTrue($entry['pair']['offset'] === $entry['key']['encoded_offset'] &&
				$entry['pair']['length'] === $entry['value']['offset'] + $entry['value']['length'] -
					$entry['key']['encoded_offset'],
				'top-level raw key/value spans remain capture-relative descriptors');
		}
		$this->assertEquals(array('unknown', 'z', 'info'), $names,
			'the scanner accepts source dictionary order without sorting or copying its values');
		$this->assertEquals(strtoupper(sha1($info)), $scan['info_hash'],
			'the scanner hashes the exact raw info value bytes');
	}

	public function testBencodeScannerRejectsMalformedTrailingNoncanonicalAndDuplicateKeys()
	{
		if (!class_exists('RetrackersBencodeScanner', false)) {
			$this->assertTrue(false, 'update.php declares strict canonical bencode grammar');
			return;
		}
		$info = $this->rawInfoFixture();
		$valid = $this->metainfoWithRawInfo($info);
		$hash = strtoupper(sha1($info));
		$invalid = array(
			'',
			'0:',
			$valid . '0:',
			'd4:infoi01ee',
			'd4:infoi-0ee',
			'd4:infoi+1ee',
			'd4:infoi00ee',
			'd4:infoiee',
			'd4:infoi1.0ee',
			'd4:info01:xe',
			'd4:info999999999999999999999999:x',
			'di1e0:e',
		);
		$scanner = new RetrackersBencodeScanner();
		foreach ($invalid as $index => $source) {
			$this->assertEquals(array('ok' => false, 'reason' => 'source-bencode-invalid'),
				$scanner->scan($source, $hash),
				'malformed, trailing, or noncanonical bencode is rejected at case ' . $index);
		}
		$duplicates = array(
			'd4:infod1:a0:1:a0:ee',
			'd4:info' . $info . '4:info' . $info . 'e',
		);
		foreach ($duplicates as $index => $source) {
			$this->assertEquals(array('ok' => false, 'reason' => 'source-duplicate-key'),
				$scanner->scan($source, $hash),
				'duplicate byte-string keys are rejected independently in every dictionary: ' . $index);
		}
	}

	public function testBencodeScannerRequiresOneRawInfoValueWithTheExpectedSha1()
	{
		if (!class_exists('RetrackersBencodeScanner', false)) {
			$this->assertTrue(false, 'update.php declares exact raw info hash authority');
			return;
		}
		$info = $this->rawInfoFixture();
		$scanner = new RetrackersBencodeScanner();
		$this->assertEquals(array('ok' => false, 'reason' => 'source-bencode-invalid'),
			$scanner->scan('d1:a0:e', strtoupper(sha1($info))),
			'a valid dictionary with no info value is not metainfo authority');
		$this->assertEquals(array('ok' => false, 'reason' => 'source-hash-mismatch'),
			$scanner->scan($this->metainfoWithRawInfo($info), str_repeat('0', 40)),
			'a raw info SHA-1 mismatch is classified before semantic Torrent construction');
		$this->assertEquals(array('ok' => false, 'reason' => 'source-hash-mismatch'),
			$scanner->scan($this->metainfoWithRawInfo($info), strtolower(sha1($info))),
			'the expected authority hash must be uppercase canonical 40-hex');
	}

	public function testBencodeScannerAcceptsExactDepthAndComplexityThenRejectsNext()
	{
		if (!class_exists('RetrackersBencodeScanner', false)) {
			$this->assertTrue(false, 'update.php declares bounded iterative depth and complexity');
			return;
		}
		$scanner = new RetrackersBencodeScanner();
		$depthInfo = str_repeat('l', 127) . '0:' . str_repeat('e', 127);
		$depthSource = $this->metainfoWithRawInfo($depthInfo);
		$this->assertTrue($scanner->scan($depthSource, strtoupper(sha1($depthInfo)))['ok'] === true,
			'exactly 128 containers are accepted without PHP recursion');
		$tooDeepInfo = 'l' . $depthInfo . 'e';
		$this->assertEquals(array('ok' => false, 'reason' => 'source-too-deep'),
			$scanner->scan($this->metainfoWithRawInfo($tooDeepInfo), strtoupper(sha1($tooDeepInfo))),
			'container depth 129 is rejected before opening another frame');

		$exactInfo = 'l' . str_repeat('0:', 999997) . 'e';
		$this->assertTrue($scanner->scan($this->metainfoWithRawInfo($exactInfo),
			strtoupper(sha1($exactInfo)))['ok'] === true,
			'exactly 1000000 combined values and keys are accepted');
		$overflowInfo = 'l' . str_repeat('0:', 999998) . 'e';
		$this->assertEquals(array('ok' => false, 'reason' => 'source-too-complex'),
			$scanner->scan($this->metainfoWithRawInfo($overflowInfo), strtoupper(sha1($overflowInfo))),
			'value or key 1000001 is rejected before retaining it');
	}

	public function testMetainfoAuthorityUsesOneCapturedBytesTorrentAfterHashGateAndNeverRereadsPath()
	{
		if (!class_exists('RetrackersMetainfoAuthority', false) ||
			!class_exists('RetrackersTorrentProjector', false)) {
			$this->assertTrue(false, 'update.php declares captured-bytes semantic metainfo authority');
			return;
		}
		$info = $this->rawInfoFixture();
		$initial = $this->metainfoWithRawInfo($info, '8:rtorrent0:');
		$otherInfo = 'd4:name5:othere';
		$replacement = $this->metainfoWithRawInfo($otherInfo);
		$path = $this->metainfoFixturePath('one-open-source.torrent');
		$replacementPath = $this->metainfoFixturePath('one-open-replacement.torrent');
		file_put_contents($path, $initial);
		file_put_contents($replacementPath, $replacement);
		$projector = $this->recordingTorrentProjector();
		$authority = new RetrackersMetainfoAuthority(
			$this->replacingFileReader($replacementPath), null, $projector);
		$result = $authority->prepare($path, strtoupper(sha1($info)),
			array(array('http://new')), array(), false);
		$this->assertTrue($result['ok'] === true && $result['changed'] === true &&
			$result['original'] === $initial && file_get_contents($path) === $replacement &&
			$projector->constructionCount === 1 &&
			$projector->constructionInputs === array($initial) &&
			strpos($result['candidate'], '4:info' . $info) !== false,
			'one Torrent receives captured bytes only after the raw hash gate despite pathname replacement');

		$badPath = $this->metainfoFixturePath('hash-mismatch-source.torrent');
		file_put_contents($badPath, $initial);
		$badProjector = $this->recordingTorrentProjector();
		$bad = (new RetrackersMetainfoAuthority(null, null, $badProjector))->prepare(
			$badPath, str_repeat('0', 40), array(array('http://new')), array(), false);
		$this->assertTrue($bad['ok'] === false && $bad['reason'] === 'source-hash-mismatch' &&
			$badProjector->constructionCount === 0 && !array_key_exists('original', $bad),
			'a scanner/hash failure constructs no Torrent and exposes no unaccepted rollback authority');
	}

