	public function testCandidateBuilderAcceptsExactCapAndRejectsRawSpanPlusNarrowCapPlusOne()
	{
		// The contract bounds each string, not allocator RSS for two simultaneous 64 MiB strings.
		// Measure the exact boundary without materializing it; exercise real output separately.
		foreach (array(67108863, 67108864, 67108865, 33554432) as $size) {
			$body = '$size = ' . $size . ';' . "\n" . <<<'PHP'
$info = 'd4:name1:xe';
$hash = strtoupper(sha1($info));
$small = 'd4:info' . $info . 'e';
$builder = new RetrackersCandidateBuilder();
if ($size <= 67108864 && $size !== 33554432) {
$measure = new ReflectionMethod($builder, 'measure');
if (PHP_VERSION_ID < 80100) {
	$measure->setAccessible(true);
}
	$length = $measure->invoke($builder, array(array('kind' => 'raw',
		'source' => array('pair' => array('length' => $size - 2)))));
	$outcome = $length === $size ? 'preflight-accepted' : 'invalid';
} else {
	$scan = (new RetrackersBencodeScanner())->scan($small, $hash);
	$url = str_repeat('u', $size - 38);
	$projection = array('ok' => true, 'changed' => true,
		'announce' => $url, 'announce_list' => null);
	$result = $builder->build($small, $scan, $projection, $hash);
	$outcome = $result['ok'] ? 'materialized' : $result['reason'];
	$length = $result['ok'] ? strlen($result['candidate']) : 0;
}
echo PHP_VERSION, "\t", ini_get('memory_limit'), "\t", $size, "\t", $outcome,
	"\t", $length, "\t", memory_get_peak_usage(true), "\n";
PHP;
			$proof = $this->runBoundedMemoryChild($body);
			$expected = $size === 67108865 ? 'candidate-too-large' :
				($size === 33554432 ? 'materialized' : 'preflight-accepted');
			$this->assertTrue($proof !== false && $proof[2] === (string)$size &&
				$proof[3] === $expected && $proof[4] === (string)($size === 67108865 ? 0 : $size),
				'128M candidate boundary ' . $size . ' is ' . $expected . '; proof=' . json_encode($proof));
		}
	}

	private function runBoundedMemoryChild($body)
	{
		$script = $this->metainfoFixturePath('bounded-child.php');
		$stdout = $this->metainfoFixturePath('bounded-child.stdout');
		$stderr = $this->metainfoFixturePath('bounded-child.stderr');
		$update = realpath(__DIR__ . '/../../../plugins/retrackers/update.php');
		file_put_contents($script, "<?php\n" . 'define("RETRACKERS_IMPORT_ONLY", true);' . "\n" .
			'require ' . var_export($update, true) . ";\n" . $body);
		$process = proc_open(array(PHP_BINARY, '-d', 'memory_limit=128M',
			'-d', 'display_errors=stderr', '-d', 'error_reporting=32767', $script),
			array(0 => array('pipe', 'r'), 1 => array('file', $stdout, 'w'),
				2 => array('file', $stderr, 'w')), $pipes);
		if (!is_resource($process)) {
			return(false);
		}
		fclose($pipes[0]);
		$deadline = microtime(true) + 60;
		do {
			$status = proc_get_status($process);
			if (!$status['running']) {
				break;
			}
			usleep(20000);
		} while (microtime(true) < $deadline);
		if ($status['running']) {
			proc_terminate($process, 9);
		}
		proc_close($process);
		$output = file_get_contents($stdout);
		$error = file_get_contents($stderr);
		if ($status['running'] || $status['exitcode'] !== 0 || $error !== '' ||
			preg_match('/\A([0-9]+\.[0-9]+\.[0-9]+[^\t\n]*)\t128M\t[0-9]+\t[a-z-]+\t[0-9]+\t[0-9]+\n\z/D',
				$output) !== 1) {
			echo 'Child diagnostic: ' . json_encode(array($status['exitcode'], $output, $error)) . "\n";
			return(false);
		}
		$fields = explode("\t", rtrim($output, "\n"));
		echo 'MEMORY_PROBE ' . $output;
		return($fields[0] === PHP_VERSION && (int)$fields[5] < 134217728 ? $fields : false);
	}

	public function testMaximumHistoricalProjectionUsesTwoLazyReadsUnder128M()
	{
		$body = <<<'PHP'
class rTorrent
{
	public static function quoteCommandArg($value)
	{
		return('"' . str_replace(array('\\', '"'), array('\\\\', '\\"'), $value) . '"');
	}
}
class MaximumHistoricalAdapter extends RetrackersDirectRpcAdapter
{
	public $calls = 0;
	public function historicalBindingSample(&$failure = null)
	{
		$this->calls++;
		$names = array('foreign-0', 'foreign-1', 'foreign-2', 'foreign-3',
			'foreign-4', 'foreign-5', 'foreign-6', 'foreign-7');
		// Charge: names in list and map + 32-byte action digests + RR4 header + final digests.
		$remaining = 8388608 - 2 * 72 - 8 * 32 - 456;
		$list = '';
		$map = '';
		foreach ($names as $index => $name) {
			$length = min(1048576, $remaining);
			$remaining -= $length;
			$list .= '<value><string>' . $name . '</string></value>';
			$map .= '<member><name>' . $name . '</name><value><string>' .
				str_repeat('x', $length) . '</string></value></member>';
		}
		$slots = '';
		foreach (array('<array><data>' . $list . '</data></array>', '<struct>' . $map . '</struct>',
			'<array><data/></array>', '<array><data/></array>', '<struct/>') as $node) {
			$slots .= '<value><array><data><value>' . $node . '</value></data></array></value>';
		}
		unset($list, $map, $node);
		$body = '<?xml version="1.0"?><methodResponse><params><param><value><array><data>' .
			$slots . '</data></array></value></param></params></methodResponse>';
		unset($slots);
		$raw = 'Status: 200 OK' . "\r\n" . 'Content-Type: text/xml' . "\r\n" .
			'Content-Length: ' . strlen($body) . "\r\n\r\n" . $body;
		unset($body);
		$sample = retrackersDecodeRestrictedRawResponse($raw, retrackersRestrictedPlanHistoricalBindingV2());
		unset($raw);
		return($sample);
	}
}
$adapter = new MaximumHistoricalAdapter();
$calls = 0;
$attestation = new RetrackersHistoricalLedgerAttestation(true, true, true, true);
$result = (new RetrackersStableHistoricalBinding($adapter))->consume('alice', null,
	$attestation, function ($decision) use (&$calls) {
		$calls++;
		return $decision['phase'] === 'BOOTSTRAP' && $decision['production_accepted'] === true;
	});
$ok = $result === array('ok' => true, 'consumer_result' => true) &&
	$adapter->calls === 2 && $calls === 1;
echo PHP_VERSION, "\t", ini_get('memory_limit'), "\t8388608\t",
	$ok ? 'accepted' : 'invalid', "\t", $calls, "\t", memory_get_peak_usage(true), "\n";
PHP;
		$proof = $this->runBoundedMemoryChild($body);
		$this->assertTrue($proof !== false && $proof[2] === '8388608' &&
			$proof[3] === 'accepted' && $proof[4] === '1',
			'two lazy maximum-projected raw samples reach exactly one production consumer under 128M; proof=' .
			json_encode($proof));
	}

	public function testCandidateAppenderBoundsRawAndGeneratedSlicesAndRejectsCrossing()
	{
		if (!class_exists('RetrackersBoundedAppender', false)) {
			$this->assertTrue(false, 'update.php declares the second bounded candidate append gate');
			return;
		}
		$generated = str_repeat('g', 65537);
		$appender = new RetrackersBoundedAppender(strlen($generated));
		$this->assertTrue($appender->appendBytes($generated) && $appender->finish() === $generated &&
			$appender->maxChunkLength() === 65536,
			'generated payload is appended only through slices no larger than 64 KiB');

		$raw = 'prefix' . str_repeat('r', 131073) . 'suffix';
		$rawAppender = new RetrackersBoundedAppender(131073);
		$this->assertTrue($rawAppender->appendSpan($raw, 6, 131073) &&
			$rawAppender->finish() === str_repeat('r', 131073) &&
			$rawAppender->maxChunkLength() === 65536,
			'raw capture spans are copied only through bounded offset slices');

		$crossing = new RetrackersBoundedAppender(3);
		$crossing->appendBytes('ab');
		$before = $crossing->bytes();
		$this->assertTrue(!$crossing->appendBytes('cd') && $crossing->bytes() === $before &&
			$crossing->finish() === false,
			'an inconsistent post-preflight append crossing rejects before changing prior output');
		$span = new RetrackersBoundedAppender(1);
		$this->assertTrue(!$span->appendSpan('x', 1, 1) && $span->bytes() === '',
			'an out-of-range raw descriptor cannot append or mutate output');
	}

	public function testFinalCandidateRescanRejectsInfoTrackerAndProtectedSpanMutations()
	{
		if (!class_exists('RetrackersCandidateBuilder', false) || !$this->loadTorrentRuntime()) {
			$this->assertTrue(false, 'update.php declares final candidate rescan and protected-span proof');
			return;
		}
		$info = $this->rawInfoFixture();
		$unknown = '3:raw';
		$source = $this->metainfoWithRawInfo($info, '7:unknown' . $unknown);
		$scanner = new RetrackersBencodeScanner();
		$sourceScan = $scanner->scan($source, strtoupper(sha1($info)));
		$projection = array(
			'ok' => true,
			'changed' => true,
			'announce' => 'http://new',
			'announce_list' => array(array('http://new')),
		);
		$builder = new RetrackersCandidateBuilder();
		$built = $builder->build($source, $sourceScan, $projection, strtoupper(sha1($info)));
		$this->assertTrue($built['ok'] === true,
			'a valid logical tracker plan survives the final strict candidate scan');
		$tamperedScan = $sourceScan;
		foreach ($tamperedScan['top'] as &$entry) {
			if (substr($source, $entry['key']['offset'], $entry['key']['length']) === 'unknown') {
				$entry['pair']['offset'] += $entry['key']['encoded_length'];
				$entry['pair']['length'] -= $entry['key']['encoded_length'];
			}
		}
		unset($entry);
		$this->assertEquals(array('ok' => false, 'reason' => 'candidate-hash-mismatch'),
			$builder->build($source, $tamperedScan, $projection, strtoupper(sha1($info))),
			'a candidate built from an inconsistent protected descriptor is rescanned before exposure');
		$protected = str_replace('3:raw', '3:saw', $built['candidate']);
		$this->assertEquals(array('ok' => false, 'reason' => 'candidate-hash-mismatch'),
			$builder->validateCandidate($source, $sourceScan, $protected, $projection,
				strtoupper(sha1($info))),
			'a byte-valid protected unknown-span mutation is rejected by final descriptor comparison');
		$infoMutation = str_replace('1:x', '1:y', $built['candidate']);
		$this->assertEquals(array('ok' => false, 'reason' => 'candidate-hash-mismatch'),
			$builder->validateCandidate($source, $sourceScan, $infoMutation, $projection,
				strtoupper(sha1($info))),
			'a raw info mutation is rejected by the final expected SHA-1 proof');
		$trackerMutation = str_replace('http://new', 'http://bad', $built['candidate']);
		$this->assertEquals(array('ok' => false, 'reason' => 'candidate-tracker-projection-failed'),
			$builder->validateCandidate($source, $sourceScan, $trackerMutation, $projection,
				strtoupper(sha1($info))),
			'a byte-valid tracker projection mutation is rejected before candidate exposure');
	}

