		), $parsed, 'a dense canonical CLI handoff is accepted without runtime work');
		$this->assertTrue(retrackersParseCliArgv(array('update.php', strtolower($hash), $user, $handoff)) === false,
			'a lowercase torrent hash is rejected');
		$this->assertTrue(retrackersParseCliArgv(array('update.php', $hash, 'User', $handoff)) === false,
			'a non-canonical user is rejected');
		$this->assertTrue(retrackersParseCliArgv(array('update.php', $hash, $user,
			'v1:original:1:' . $localId . ':' . hash('sha256', 'other-user'))) === false,
			'a handoff token for another user is rejected');
		$this->assertTrue(retrackersParseCliArgv(array('update.php', $hash, $user,
			'v1:original:2:' . $localId . ':' . hash('sha256', $user))) === false,
			'an invalid captured state is rejected');
		$this->assertTrue(retrackersParseCliArgv(array(0 => 'update.php', 2 => $hash, 3 => $user, 4 => $handoff)) === false,
			'sparse argv keys are rejected before they can be reindexed');
		$this->assertTrue(retrackersParseCliArgv(array('update.php', $hash, '',
			'v1:original:0:' . $localId . ':' . hash('sha256', ''))) !== false,
			'an empty canonical user is accepted');
	}

	private function parseWithoutFatal($argv, &$error)
	{
		$error = null;
		try {
			return(retrackersParseCliArgv($argv));
		} catch (Throwable $caught) {
			$error = $caught;
			return(null);
		}
	}

	public function testCliValidationRejectsNonStringsAndTrailingNewlines()
	{
		$hash = '0123456789ABCDEF0123456789ABCDEF01234567';
		$user = 'user_42-name';
		$localId = '89ABCDEF0123456789ABCDEF0123456789ABCDEF';
		$handoff = 'v1:original:1:' . $localId . ':' . hash('sha256', $user);
		$values = array('update.php', $hash, $user, $handoff);
		foreach (array(0, 1, 2, 3) as $slot) {
			foreach (array(array('not-a-string'), new stdClass()) as $invalid) {
				$argv = $values;
				$argv[$slot] = $invalid;
				$result = $this->parseWithoutFatal($argv, $error);
				$this->assertTrue($error === null && $result === false,
					'non-string argv slot ' . $slot . ' is rejected without a warning or TypeError');
			}
		}

		$result = $this->parseWithoutFatal(array('update.php', $hash . "\n", $user, $handoff), $error);
		$this->assertTrue($error === null && $result === false, 'a torrent-hash trailing newline is rejected');
		$newlineUser = $user . "\n";
		$result = $this->parseWithoutFatal(array('update.php', $hash, $newlineUser,
			'v1:original:1:' . $localId . ':' . hash('sha256', $newlineUser)), $error);
		$this->assertTrue($error === null && $result === false, 'a user trailing newline is rejected');
		$result = $this->parseWithoutFatal(array('update.php', $hash, $user, $handoff . "\n"), $error);
		$this->assertTrue($error === null && $result === false, 'a handoff trailing newline is rejected');
	}

	public function testInvalidCliArgvExitsBeforeLoadingOrWritingRuntimeDependencies()
	{
		if (!function_exists('exec') || PHP_BINARY === '') {
			$this->assertTrue(false, 'a PHP subprocess is required to test the CLI exit boundary');
			return;
		}

		$root = sys_get_temp_dir() . '/rutorrent-retrackers-invalid-cli-' . getmypid();
		$this->removeTree($root);
		mkdir($root, 0700);
		$profile = $root . '/profile';
		mkdir($profile, 0700);
		$report = $root . '/report.json';
		$errorLog = $root . '/error.log';
		$script = $root . '/entry.php';
		$update = realpath(__DIR__ . '/../../../plugins/retrackers/update.php');
		file_put_contents($script, '<?php' . "\n"
			. 'putenv(' . var_export('RU_PROFILE_PATH=' . $profile, true) . ');' . "\n"
			. 'ini_set(' . var_export('log_errors', true) . ', ' . var_export('1', true) . ');' . "\n"
			. 'ini_set(' . var_export('error_log', true) . ', ' . var_export($errorLog, true) . ');' . "\n"
			. 'unset($_SERVER[' . var_export('REMOTE_USER', true) . ']);' . "\n"
			. 'register_shutdown_function(function () {' . "\n"
			. '    $profile = ' . var_export($profile, true) . ';' . "\n"
			. '    file_put_contents(' . var_export($report, true) . ', json_encode(array(' . "\n"
			. '        "included" => get_included_files(),' . "\n"
			. '        "profile" => array_values(array_diff(scandir($profile), array(".", ".."))),' . "\n"
			. '        "remote_user" => array_key_exists("REMOTE_USER", $_SERVER),' . "\n"
			. '        "error_log" => is_file(' . var_export($errorLog, true) . '),' . "\n"
			. '    )));' . "\n"
			. '});' . "\n"
			. 'require ' . var_export($update, true) . ';' . "\n");

		$output = array();
		$status = 0;
		exec(escapeshellarg(PHP_BINARY) . ' -d display_errors=0 ' . escapeshellarg($script)
			. ' not-a-hash user v1:original:0:0123456789ABCDEF0123456789ABCDEF01234567:'
			. hash('sha256', 'user') . ' 2>&1', $output, $status);
		$observed = json_decode(file_get_contents($report), true);

		$this->assertTrue($status !== 0, 'invalid CLI argv exits with a failure status');
		$this->assertEquals(array(), $output, 'invalid CLI argv writes no diagnostic output');
		$this->assertEquals(array(realpath($script), $update), $observed['included'],
			'invalid CLI argv includes no configuration, filesystem, or RPC dependency');
		$this->assertEquals(array(), $observed['profile'], 'invalid CLI argv creates no profile files');
		$this->assertTrue($observed['remote_user'] === false, 'invalid CLI argv does not set a runtime user');
		$this->assertTrue($observed['error_log'] === false, 'invalid CLI argv does not log');
		$this->removeTree($root);
	}

	public function testValidCliLoadsRuntimeDependenciesBeforeTheFirstRpc()
	{
		if (!function_exists('exec') || PHP_BINARY === '') {
			$this->assertTrue(false, 'a PHP subprocess is required to test the valid CLI boundary');
			return;
		}

		$root = sys_get_temp_dir() . '/rutorrent-retrackers-valid-cli-' . getmypid();
		$this->removeTree($root);
		mkdir($root, 0700);
		$profile = $root . '/profile';
		$temp = $root . '/tmp';
		mkdir($profile, 0700);
		mkdir($temp, 0700);
		$report = $root . '/report.json';
		$errorLog = $root . '/error.log';
		$socket = 'unix://' . $root . '/unreachable.sock';
		$script = $root . '/entry.php';
		$update = realpath(__DIR__ . '/../../../plugins/retrackers/update.php');
		$hash = str_repeat('A', 40);
		$user = 'alice';
		$localId = str_repeat('B', 40);
		$handoff = 'v1:original:0:' . $localId . ':' . hash('sha256', $user);
		$environment = array(
			'RU_PROFILE_PATH' => $profile,
			'RU_TEMP_DIRECTORY' => $temp,
			'RU_LOG_FILE' => $errorLog,
			'RU_SCGI_HOST' => $socket,
			'RU_SCGI_PORT' => '0',
		);
		file_put_contents($script, '<?php' . "\n"
			. 'define(' . var_export('RETRACKERS_IMPORT_ONLY', true) . ', true);' . "\n"
			. '$environment = ' . var_export($environment, true) . ';' . "\n"
			. 'foreach ($environment as $name => $value) {' . "\n"
			. '    putenv($name . "=" . $value);' . "\n"
			. '    $_ENV[$name] = $value;' . "\n"
			. '}' . "\n"
			. '$profilePath = $environment["RU_PROFILE_PATH"];' . "\n"
			. '$tempDirectory = $environment["RU_TEMP_DIRECTORY"];' . "\n"
			. '$log_file = $environment["RU_LOG_FILE"];' . "\n"
			. '$scgi_host = $environment["RU_SCGI_HOST"];' . "\n"
			. '$scgi_port = $environment["RU_SCGI_PORT"];' . "\n"
			. 'require ' . var_export($update, true) . ';' . "\n"
			. '$status = retrackersCliMain($argv);' . "\n"
			. 'file_put_contents(' . var_export($report, true) . ', json_encode(array(' . "\n"
			. '    "status" => $status,' . "\n"
			. '    "profile_path" => $profilePath,' . "\n"
			. '    "temp_directory" => $tempDirectory,' . "\n"
			. '    "log_file" => $log_file,' . "\n"
			. '    "scgi_host" => $scgi_host,' . "\n"
			. '    "scgi_port" => (string) $scgi_port,' . "\n"
			. '    "transport_loaded" => class_exists("rSCGITransport", false),' . "\n"
			. ')));' . "\n"
			. 'exit($status);' . "\n");
		$output = array();
		$status = 0;
		exec(escapeshellarg(PHP_BINARY) . ' -d display_errors=1 ' . escapeshellarg($script) .
			' ' . escapeshellarg($hash) . ' ' . escapeshellarg($user) .
			' ' . escapeshellarg($handoff) . ' 2>&1', $output, $status);
		$transcript = implode("\n", $output);
		$observed = is_file($report) ? json_decode(file_get_contents($report), true) : array();

		$this->assertTrue($status === 1 && isset($observed['status']) && $observed['status'] === 1,
			'a valid standalone worker reaches a classified runtime refusal instead of a PHP fatal');
		$this->assertTrue(isset($observed['transport_loaded']) && $observed['transport_loaded'] === true &&
			strpos($transcript, 'Class "rSCGITransport" not found') === false,
			'the standalone worker loads its SCGI dependency before the first RPC');
		$runtime = array();
		foreach (array('profile_path', 'temp_directory', 'log_file', 'scgi_host', 'scgi_port') as $key) {
			$runtime[$key] = isset($observed[$key]) ? $observed[$key] : null;
		}
		$this->assertEquals(array(
			'profile_path' => $profile,
			'temp_directory' => $temp,
			'log_file' => $errorLog,
			'scgi_host' => $socket,
			'scgi_port' => '0',
		), $runtime, 'the child records only private-root write targets and an unreachable Unix SCGI endpoint');
		$this->assertTrue(is_string($runtime['profile_path']) &&
			strpos($runtime['profile_path'], $root . '/') === 0 &&
			is_string($runtime['temp_directory']) &&
			strpos($runtime['temp_directory'], $root . '/') === 0 &&
			is_string($runtime['log_file']) && strpos($runtime['log_file'], $root . '/') === 0 &&
			is_string($runtime['scgi_host']) && strpos($runtime['scgi_host'], 'unix://') === 0 &&
			!file_exists(substr($runtime['scgi_host'], strlen('unix://'))),
			'the valid CLI probe cannot inherit a configured daemon or an external side-effect path');
		$log = is_file($errorLog) ? file_get_contents($errorLog) : '';
		$matches = array();
		preg_match_all('/^\[[^\r\n]+\] retrackers-recovery: ([0-9A-F]{40}) ([a-z0-9-]+)$/m',
			$log, $matches);
		$this->assertTrue(isset($matches[1], $matches[2]) && count($matches[1]) === 1 &&
			$matches[1][0] === $hash && $matches[2][0] === 'rpc-family-unconfirmed',
			'a valid CLI worker persistently records its hash and one bounded failure class');
		$this->assertTrue(strpos($matches[0][0] ?? '', $socket) === false &&
			strpos($matches[0][0] ?? '', $root) === false &&
			strpos($matches[0][0] ?? '', $handoff) === false,
			'the CLI worker diagnostic contains no transport path, handoff, or remote payload');
		$this->removeTree($root);
	}

	public function testWorkerFailureRecorderPersistsOnlyCanonicalHashAndClosedReason()
	{
		if (!function_exists('exec') || PHP_BINARY === '') {
			$this->assertTrue(false,
				'a PHP subprocess is required to isolate the persistent diagnostic sink');
			return;
		}
		$root = sys_get_temp_dir() . '/rutorrent-retrackers-recorder-' . getmypid();
		$this->removeTree($root);
		mkdir($root, 0700);
		$script = $root . '/record.php';
		$update = realpath(__DIR__ . '/../../../plugins/retrackers/update.php');
		$hash1 = str_repeat('A', 40);
		$hash2 = str_repeat('B', 40);
		$raw = "<?xml fault>\npassword=secret https://tracker.invalid/passkey /private/session";
		file_put_contents($script, '<?php' . "\n"
			. 'define("RETRACKERS_IMPORT_ONLY", true);' . "\n"
			. 'class FileUtil { public static $records = array(); public static function toLog($value) {' . "\n"
			. '    self::$records[] = $value;' . "\n"
			. '} }' . "\n"
			. 'require ' . var_export($update, true) . ';' . "\n"
			. '$first = new RetrackersWorkerRpcAdapter(' . var_export($hash1, true) . ');' . "\n"
			. '$first->recordRecoveryFailure(' . var_export($raw, true) . ');' . "\n"
			. '$second = new RetrackersWorkerRpcAdapter(' . var_export($hash2, true) . ');' . "\n"
			. '$second->recordRecoveryFailure("load-fence-pending");' . "\n"
			. 'echo json_encode(FileUtil::$records);' . "\n");
		$output = array();
		$status = 0;
		exec(escapeshellarg(PHP_BINARY) . ' -d display_errors=1 ' . escapeshellarg($script) .
			' 2>&1', $output, $status);
		$records = json_decode(implode("\n", $output), true);
		$this->assertEquals(array(
			'retrackers-recovery: ' . $hash1 . ' lifecycle-unsupported',
			'retrackers-recovery: ' . $hash2 . ' load-fence-pending',
		), $records,
			'the persistent recorder accepts only a canonical hash and closed local classification');
		$this->assertTrue($status === 0 && strpos(implode("\n", $output), 'password=secret') === false &&
			strpos(implode("\n", $output), 'tracker.invalid') === false &&
			strpos(implode("\n", $output), '/private/session') === false,
			'adversarial fault text never reaches the persistent diagnostic record');
		$this->removeTree($root);
	}

