		} catch (RetrackersRestrictedCodecError $error) {
			$memberExact = false;
		}
		$memberOverflow = false;
		try {
			$memberCursor->beginMember();
		} catch (RetrackersRestrictedCodecError $error) {
			$memberOverflow = true;
		}
		$this->assertTrue($memberExact && $memberOverflow,
			'the global member counter accepts exactly 12288 members and rejects member 12289');
	}

