	public function testDirectAdapterUsesOneNineArgumentRawCallAcrossOptionalLimits()
	{
		if (!$this->requireCodecApi() || !$this->installRawTransportDouble()) {
			return;
		}
		global $scgi_host, $scgi_port;
		$scgi_host = '/tmp/retrackers-test.sock';
		$scgi_port = 0;
		rSCGITransport::$raw = $this->capturedRaw('rt1621-b5-synthetic-ledger');
		$adapter = new RetrackersDirectRpcAdapter();
		$configurations = array(array(7, 8192), array(7, null), array(null, 8192), array(null, null));
		set_error_handler(function ($severity, $message, $file, $line) {
			if (strpos($message, 'assert():') === 0) {
				return(false);
			}
			throw new ErrorException($message, 0, $severity, $file, $line);
		});
		try {
			foreach ($configurations as $configuration) {
				if ($configuration[0] === null) {
					unset($GLOBALS['rpcTransferTimeOut']);
				} else {
					$GLOBALS['rpcTransferTimeOut'] = $configuration[0];
				}
				if ($configuration[1] === null) {
					unset($GLOBALS['rpcMaxResponseBytes']);
				} else {
					$GLOBALS['rpcMaxResponseBytes'] = $configuration[1];
				}
				rSCGITransport::$calls = array();
				$failure = 'stale';
				$decoded = $adapter->historicalBindingSample($failure);
				$this->assertTrue(is_array($decoded) &&
					$decoded['value']['counts']['recovery_rows'] === 2 &&
					$failure === rSCGITransport::$failureWrite &&
					count(rSCGITransport::$calls) === 1,
					'the optional timeout/cap configuration makes exactly one successful transport call');
				$this->assertEquals(array(
					'argument_count' => 9,
					'arguments' => array($scgi_host, $scgi_port, $this->capturedRaw('b5-request'),
						true, 0.25, null, $configuration[0], $configuration[1],
						rSCGITransport::RESPONSE_RAW),
					'failure_after' => rSCGITransport::$failureWrite,
				),
					rSCGITransport::$calls[0], 'the adapter supplies the exact nine-argument RAW boundary');
			}
		} finally {
			restore_error_handler();
		}
	}

