			if (strpos($message, 'assert():') === 0) {
				return(false);
			}
			throw new ErrorException($message, 0, $severity, $file, $line);
		});
		try {
			rSCGITransport::$calls = array();
			rSCGITransport::$returnNull = true;
			$failure = null;
			$this->assertTrue($adapter->historicalBindingSample($failure) === false &&
				$failure === 'transport-failed' && count(rSCGITransport::$calls) === 1,
				'a null transport reply fails after exactly one send');

