			rSCGITransport::$calls = array();
			rSCGITransport::$raw = 'not a framed reply';
			$failure = null;
			$this->assertTrue($adapter->historicalBindingSample($failure) === false &&
				$failure === 'malformed-response' && count(rSCGITransport::$calls) === 1,
				'a malformed RAW reply fails after exactly one send');

