				$failure === 'receipt-ledger-corrupt' && count(rSCGITransport::$calls) === 1,
				'a ledger member-fault sample retains its typed refusal after exactly one send');

			rSCGITransport::$calls = array();
			rSCGITransport::$raw = $this->capturedRaw('rt1621-b5-synthetic-ledger');
			rSCGITransport::$delayMicros = 300000;
			$failure = null;
			$delayed = $adapter->historicalBindingSample($failure);
			$this->assertTrue(is_array($delayed) &&
				$delayed['value']['counts']['recovery_rows'] === 2 &&
				count(rSCGITransport::$calls) === 1 &&
				rSCGITransport::$calls[0]['arguments'][6] === null &&
				rSCGITransport::$calls[0]['argument_count'] === 9 &&
				rSCGITransport::$calls[0]['arguments'][8] === rSCGITransport::RESPONSE_RAW,
				'a delayed read remains governed by the unset transfer budget, not the 0.25 connect timeout');
		} finally {
			rSCGITransport::$delayMicros = 0;
			restore_error_handler();
		}
	}

