		$invoke = function ($method, ...$arguments) use ($reflect, $model) {
			$method = $reflect->getMethod($method);
			if (PHP_VERSION_ID < 80100) { $method->setAccessible(true); }
			return($method->invokeArgs($model, $arguments));
		};
		$ledger = $reflect->getProperty('modelLedger');
		if (PHP_VERSION_ID < 80100) { $ledger->setAccessible(true); }
		$callback = RetrackersWorkerAdoptCallback::build($tx, str_repeat('A', 40), 'handoff', $local);
		$outer = $invoke('splitArguments', substr($callback->params()[2], 7));
		$already = $invoke('unquote', $outer[0]);
		$inner = $invoke('splitArguments', substr($invoke('unquote', $outer[2]), 7));
		$adopt = $invoke('unquote', $inner[0]);
		foreach (array(
			array(array('wp:' . $local), false, true),
			array(array('wa:' . $tx), true, false),
			array(array('wp:' . $local, 'ma:1'), false, false),
		) as $case) {
			$ledger->setValue($model, array_fill_keys($case[0], true));
			$this->assertTrue($invoke('evaluatePredicate', $already, '') === $case[1] &&
				$invoke('evaluatePredicate', $adopt, '') === $case[2],
				'the real adoption predicate distinguishes pending adopted and contained receipts with captured not semantics');
		}
	}

