	public function testSchedulerResolverCanonicalizesBothSupportedFamiliesWithoutStarTwo()
	{
		$this->installRtorrentQuoteDouble();
		global $retrackersUpdateTestCommands;
		$old = $retrackersUpdateTestCommands;
		$tx = str_repeat('2', 32);
		try {
			$wires = array();
			foreach (array(
				array('schedule', 'schedule_remove'),
				array('schedule2', 'schedule_remove2'),
				array('schedule', 'schedule.remove'),
			) as $pair) {
				$retrackersUpdateTestCommands = array(
					'schedule' => $pair[0], 'schedule_remove' => $pair[1]);
				$current = array();
				foreach (array('la', 'ra') as $phase) {
					$failure = null;
					$callback = RetrackersLoadDispatchCallback::build($tx, $phase,
						'/proc/123/fd/4', 'load.normal',
						array('d.custom.set=x,y', 'd.custom.set=z,w'), 16777216, $failure);
					$this->assertTrue($callback instanceof RetrackersLoadDispatchCallback &&
						$failure === null, 'a coherent scheduler family seals the ' . $phase . ' load');
					$current[] = $callback ? $callback->wire() : '';
				}
				$cleanup = RetrackersTerminalCleanupCallback::build($tx);
				$current[] = $cleanup ? retrackersBuildDirectRequest(
					$cleanup->method(), $cleanup->params()) : '';
				$this->assertTrue($current[2] !== '' &&
					strpos(implode('', $current), 'schedule2') === false &&
					strpos(implode('', $current), 'schedule_remove2') === false,
					'all complete serialized callbacks omit deprecated star-two scheduler names');
				$wires[] = $current;
			}
			$this->assertTrue($wires[0] === $wires[1],
				'old aliases and canonical old commands seal byte-identical complete callback wires');
			$this->assertTrue($wires[0][0] === $wires[2][0] && $wires[0][1] === $wires[2][1] &&
				str_replace('$schedule_remove=', '$schedule.remove=', $wires[0][2]) === $wires[2][2],
				'modern complete wires differ only in the canonical terminal removal command');
			foreach (array(array('schedule2', 'schedule.remove'), array('', 'schedule.remove'),
				array('schedule', ''), array('schedule', 'd.erase'),
				array('schedule;d.erase=', 'schedule_remove')) as $pair) {
				$retrackersUpdateTestCommands = array(
					'schedule' => $pair[0], 'schedule_remove' => $pair[1]);
				foreach (array('la', 'ra') as $phase) {
					$failure = null;
					$callback = RetrackersLoadDispatchCallback::build($tx, $phase,
						'/proc/123/fd/4', 'load.normal',
						array('d.custom.set=x,y', 'd.custom.set=z,w'), 16777216, $failure);
					$this->assertTrue($callback === false && $failure === 'scheduler-command-unsupported',
						'a mixed or invalid family refuses the ' . $phase . ' obligation before a load exists');
				}
				$this->assertTrue(RetrackersTerminalCleanupCallback::build($tx) === false,
					'a mixed or invalid family cannot seal terminal cleanup either');
			}
		} finally {
			$retrackersUpdateTestCommands = $old;
		}
	}

