	public function testRestrictedCodecRejectsNamedRawXmlAndSchemaMutations()
	{
		if (!$this->requireCodecApi()) {
			return;
		}
		$scalar = $this->capturedRaw('rt1621-client-version');
		$plan = retrackersRestrictedPlanDirectScalar('string');
		$mutations = array(
			'leading-zero-content-length' => preg_replace('/Content-Length: 125/', 'Content-Length: 0125', $scalar),
			'body-prefix-bom' => $this->replaceRawBodyOnce($scalar, '<?xml', "\xEF\xBB\xBF<?xml"),
			'tinyxml-structural-crlf' => $this->replaceRawBodyOnce($scalar, '<?xml version="1.0"?>',
				'<?xml version="1.0"?>' . "\r\n"),
			'attribute' => $this->replaceRawBodyOnce($scalar, '<string>', '<string x="1">'),
			'comment' => $this->replaceRawBodyOnce($scalar, '<methodResponse>',
				'<methodResponse><!-- foreign -->'),
			'dtd' => $this->replaceRawBodyOnce($scalar, '<methodResponse>',
				'<!DOCTYPE methodResponse><methodResponse>'),
			'cdata' => $this->replaceRawBodyOnce($scalar, '0.16.21', '<![CDATA[0.16.21]]>'),
			'implicit-string' => $this->replaceRawBodyOnce($scalar, '<string>0.16.21</string>', '0.16.21'),
			'unknown-type' => $this->replaceRawBodyOnce($scalar, '<string>0.16.21</string>',
				'<base64>MC4xNi4yMQ==</base64>'),
			'referenced-cr' => $this->replaceRawBodyOnce($scalar, '0.16.21', '0.16.21&#13;'),
			'uppercase-numeric-x' => $this->replaceRawBodyOnce($scalar, '0.16.21', '0.16.2&#X31;'),
			'literal-nul' => $this->replaceRawBodyOnce($scalar, '0.16.21', "0.16\0.21"),
			'malformed-utf8' => $this->replaceRawBodyOnce($scalar, '0.16.21', "0.16.\xC3\x28"),
			'second-root' => $this->replaceRawBodyOnce($scalar, '</methodResponse>',
				'</methodResponse><methodResponse/>'),
			'second-scgi-delimiter' => $this->replaceRawBodyOnce($scalar, '</methodResponse>',
				'</methodResponse>' . "\r\n\r\n"),
		);
		foreach ($mutations as $name => $raw) {
			$this->assertTrue(retrackersDecodeRestrictedRawResponse($raw, $plan) === false,
				$name . ' is rejected by the bounded cursor codec');
		}
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($this->capturedRaw('rt1621-partial-download-row'),
			retrackersRestrictedPlanDownloadRows()) === false,
			'the captured 0.16.21 partial row is rejected instead of treated as empty');
		$leadingZero = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-trackers-populated'),
			'<string>http://127.0.0.1:9/announce</string></value><value><i8>0</i8>',
			'<string>http://127.0.0.1:9/announce</string></value><value><i8>00</i8>');
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($leadingZero,
			retrackersRestrictedPlanTrackerRows()) === false,
			'a noncanonical leading-zero i8 tracker cell is rejected');
		$ledgerTwo = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-has-present'),
			'<i8>1</i8>', '<i8>2</i8>');
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($ledgerTwo,
			retrackersRestrictedPlanLedgerHas()) === false,
			'a targeted ledger result accepts only exact explicit i8 zero or one');
		$duplicateMap = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-custom-map'), '<struct>',
			'<struct><member><name>pkg5-empty</name><value><string></string></value></member>');
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($duplicateMap,
			retrackersRestrictedPlanGenericMap()) === false,
			'a duplicate once-decoded struct name is rejected');
		$expandedEmptyArray = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-download-empty'),
			'<array><data/></array>', '<array><data></data></array>');
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($expandedEmptyArray,
			retrackersRestrictedPlanDownloadRows()) === false,
			'a TinyXML2 empty array must keep its measured self-closing data layout');
		$expandedEmptyStruct = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-ledger-empty'),
			'<struct/>', '<struct></struct>');
		$this->assertTrue(retrackersDecodeRestrictedRawResponse($expandedEmptyStruct,
			retrackersRestrictedPlanLedger(array('ma:1', 'ta:1'))) === false,
			'a TinyXML2 empty struct must keep its measured self-closing layout');
	}

	public function testCanonicalHistoricalSafetyAndDeferActionsShareTheFrozenGrammar()
	{
		$this->installRtorrentQuoteDouble();
		$this->assertTrue(function_exists('retrackersBuildSafetyOnlyInsertAction'),
			'update.php declares the canonical safety-only action builder');
		$this->assertTrue(function_exists('retrackersBuildDeferOnlyInsertAction'),
			'update.php declares the canonical defer-only action builder');
		$this->assertTrue(class_exists('RetrackersHistoricalLedgerAttestation', false),
			'update.php declares the typed historical ledger attestation');
		if (!function_exists('retrackersBuildSafetyOnlyInsertAction') ||
			!function_exists('retrackersBuildDeferOnlyInsertAction') ||
			!class_exists('RetrackersHistoricalLedgerAttestation', false)) {
			return;
		}
		$safety = base64_decode('', true);
		$defer = base64_decode('', true);
		$this->assertTrue(retrackersBuildSafetyOnlyInsertAction() === $safety,
			'the safety-only builder returns the independently frozen exact action bytes');
		$this->assertTrue(retrackersBuildDeferOnlyInsertAction() === $defer,
			'the defer-only builder returns the independently frozen exact action bytes');
		$this->assertTrue(hash('sha256', $safety) ===
			'c1ec79a6767399434309847606d9dda5f5d5eaf5d3d849e42c72b32a9dae83bb' &&
			hash('sha256', $defer) ===
			'db46e1e6ec1e6857edddc610f5ef40e632390a2a7792901d185ea015ef9f404f',
			'the two canonical identities retain their independent frozen hashes');
		$trusted = new RetrackersHistoricalLedgerAttestation(true, true, true, true);
		$public = new RetrackersHistoricalLedgerAttestation(false, true, true, true);
		$untrustedWriter = new RetrackersHistoricalLedgerAttestation(true, true, true, false);
		$this->assertTrue($trusted->failure() === null && $trusted->writerTrusted(),
			'the typed attestation accepts all four explicit assurances');
		$this->assertTrue($public->failure() === 'receipt-ledger-corrupt',
			'a failed privacy assurance is classified as ledger corruption');
		$this->assertTrue($untrustedWriter->failure() === 'profile-binding-writer-untrusted',
			'absent exclusive-writer assurance has its own typed refusal');
	}

	/**
