	/**
	 * Safety comes from the hook never being able to stop a download: the launch
	 * return is not an acknowledgement, so nothing here may leave a download
	 * stopped if the worker never runs. The shipped tadd_trackers2 hook this
	 * package replaces did carry d.stop.
	 */
	public function testTheFunctionalInsertActionNeverStopsClosesOrErasesADownload()
	{
		$this->installRtorrentQuoteDouble();
		if (!function_exists('retrackersBuildInsertAction')) {
			$this->assertTrue(false, 'the functional insert action builder exists');
			return;
		}
		$action = retrackersBuildInsertAction(
			'/opt/rutorrent/plugins/retrackers/run.sh', '/usr/bin/php', 'tester');
		foreach (array('d.stop', 'd.close', 'd.erase') as $forbidden) {
			$this->assertTrue(strpos($action, $forbidden) === false,
				"the functional insert action carries no {$forbidden} in any branch");
		}
	}

	/**
	 * The ordinary path writes in one frozen order: hook-active receipt, pending
	 * lease, ack, marker, launch, and only then the two-argument delete of the
	 * receipt. A launch that threw therefore leaves the receipt behind, which is
	 * what stops a later teardown from erasing a hook that may still be running.
	 */
	public function testTheFunctionalInsertActionOrdersItsReceiptsAroundTheLaunch()
	{
		$this->installRtorrentQuoteDouble();
		if (!function_exists('retrackersBuildInsertAction')) {
			$this->assertTrue(false, 'the functional insert action builder exists');
			return;
		}
		$action = retrackersBuildInsertAction(
			'/opt/rutorrent/plugins/retrackers/run.sh', '/usr/bin/php', 'tester');
		$this->assertTrue(strpos($action, 'd.custom=chk-meta-old') !== false &&
			strpos($action, 'd.custom1=,cat=.chk-meta') === false,
			'the insert path uses the checker marker without capturing a user label');
		// The marker/ack head this action shares with the other two variants also
		// mentions the ack key, so ordering is measured inside the ordinary path
		// alone -- it begins at the hook-active receipt, the first thing written.
		$setActive = strpos($action, 'cat=wh:');
		$this->assertTrue($setActive !== false, 'the ordinary path writes a hook-active receipt');
		$ordinary = substr($action, $setActive);
		$setPending = strpos($ordinary, 'cat=wp:');
		$ack = strpos($ordinary, 'd.custom.set=retrackers-recovery-ack,');
		$marker = strpos($ordinary, 'd.custom.set=retrackers-recovery,');
		$launch = strpos($ordinary, 'execute.throw.bg={sh,');
		$clearActive = strrpos($ordinary, 'cat=wh:');
		$this->assertTrue($setPending !== false && $ack !== false && $marker !== false &&
			$launch !== false, 'the ordinary path carries every frozen step');
		$this->assertTrue($setPending < $ack && $ack < $marker && $marker < $launch,
			'the pending lease, the ack and the marker are all written before the launch');
		$this->assertTrue($clearActive > $launch,
			'the hook-active receipt is cleared only after the launch returns');
		$this->assertTrue(substr_count($ordinary, 'cat=wh:') === 2,
			'the hook-active receipt is written once and cleared once');
	}

	/**
	 * execute.throw.bg takes an argv list, not a shell string. A configured PHP
	 * or script path holding a space, comma, quote or backslash must therefore
	 * reach the worker as one argument, and must not be able to add another.
	 */
	public function testAnAwkwardScriptOrPhpPathCannotChangeTheLaunchArgvShape()
	{
		$this->installRtorrentQuoteDouble();
		if (!function_exists('retrackersBuildInsertAction')) {
			$this->assertTrue(false, 'the functional insert action builder exists');
			return;
		}
		$script = '/opt/ru torrent/a,b/"q"/back\\slash/run.sh';
		$php = '/usr/bin/php 8.5,rc';
		$user = 'te,st "er"';
		$action = retrackersBuildInsertAction($script, $php, $user);
		// Depth is the measurement. Every nesting layer escapes a backslash and a
		// quote once more, so a value that reached the launch through its own
		// quote sits exactly one layer deeper than one interpolated raw. Asserting
		// only that the raw value is absent proves nothing here: the outer layers
		// escape it either way.
		$escape = function ($value, $times) {
			for ($i = 0; $i < $times; $i++) {
				$value = str_replace(array('\\', '"'), array('\\\\', '\\"'), $value);
			}
			return($value);
		};
		$this->assertTrue(strpos($action, $escape($script, 7)) !== false,
			'the script path is carried escaped through every nesting layer');
		$this->assertTrue(strpos($action, $escape($script, 6)) === false,
			'the script path is not one layer short, which is what losing its own quote looks like');
		$this->assertTrue(strpos($action, $escape($user, 7)) !== false,
			'the canonical user is carried escaped through every nesting layer');
		$this->assertTrue(strpos($action, $escape($user, 6)) === false,
			'the canonical user is not one layer short');
		// The launch is bracketed by two literals the builder never quotes. If an
		// awkward value had escaped its argument and added structure of its own,
		// their count would move; the argv shape is fixed by them staying at one.
		$this->assertTrue(substr_count($action, ',$d.hash=,') === 1,
			'the launch carries exactly one unquoted hash argument');
		$this->assertTrue(substr_count($action, ',$d.custom=retrackers-recovery}') === 1,
			'the launch closes on exactly one unquoted marker argument');
		$this->assertTrue(strpos($action, 'execute.throw.bg={sh,') !== false,
			'the launch keeps its argv-list form for an awkward path');
		// The handoff binds to the user by token, and never carries the name.
		$this->assertTrue(strpos($action, hash('sha256', $user)) !== false,
			'the handoff carries the exact SHA-256 of the canonical user');
		$this->assertTrue(hash('sha256', $action) !==
			hash('sha256', retrackersBuildInsertAction($script, $php, 'tester')),
			'the canonical user is bound into the action rather than ignored');
	}

	/**
	 * All three variants share one marker/ack head, so an ongoing transaction is
	 * acknowledged identically whichever variant a profile happens to carry.
	 */
	public function testAllThreeInsertVariantsShareTheMarkerAndAckHead()
	{
		$this->installRtorrentQuoteDouble();
		if (!function_exists('retrackersBuildInsertAction')) {
			$this->assertTrue(false, 'the functional insert action builder exists');
			return;
		}
		$functional = retrackersBuildInsertAction(
			'/opt/rutorrent/plugins/retrackers/run.sh', '/usr/bin/php', 'tester');
		$safety = retrackersBuildSafetyOnlyInsertAction();
		$defer = retrackersBuildDeferOnlyInsertAction();
		$head = substr($safety, 0, 456);
		$this->assertTrue(strlen($head) === 456 && substr($functional, 0, 456) === $head &&
			substr($defer, 0, 456) === $head,
			'the functional, safety-only and defer-only actions share the frozen marker/ack head');
		$this->assertTrue($functional !== $safety && $functional !== $defer,
			'the functional action is distinct from both non-launching variants');
	}

	public function testHistoricalTypedFailureSeparatesLedgerFaultsFromMalformedRaw()
	{
