		foreach (array(3, 4) as $ledgerFaultSlot) {
			$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
				$this->tinyHistoricalResponseWithFault($eventMismatch, $ledgerFaultSlot)) ===
				array('ok' => false, 'failure' => 'malformed-response'),
				'an event list/map mismatch outranks ledger member fault slot ' .
					($ledgerFaultSlot + 1));
		}
		$ledgerMismatch = $nodes;
		$ledgerMismatch[3] = '<array><data><value><string>ma:1</string></value></data></array>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($ledgerMismatch)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a ledger list/map mismatch is classified as corrupt');
		$foreignLedger = $nodes;
		$foreignLedger[3] = '<array><data><value><string>foreign:key</string></value></data></array>';
		$foreignLedger[4] = '<struct><member><name>foreign:key</name><value><string>1</string>' .
			'</value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($foreignLedger)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a foreign ledger key is classified without exposing its value');
		$eventAndForeignLedger = $foreignLedger;
		$eventAndForeignLedger[0] = $eventMismatch[0];
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($eventAndForeignLedger)) ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'an event list/map mismatch outranks decoded-ledger corruption');
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponseWithFault($foreignLedger, 0)) ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'a malformed event fault outranks later decoded-ledger corruption');
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponseWithFault($foreignLedger, 3)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a ledger fault combined with decoded-ledger corruption stays in the ledger bucket');
		$lateMalformed = $foreignLedger;
		$lateMalformed[4] = '<i8>0</i8>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($lateMalformed)) ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'a later ledger-slot schema failure outranks earlier decoded-ledger corruption');
		$duplicateList = $nodes;
		$duplicateList[3] = '<array><data><value><string>ma:1</string></value>' .
			'<value><string>ma:1</string></value></data></array>';
		$duplicateList[4] = '<struct><member><name>ma:1</name><value><string>1</string>' .
			'</value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($duplicateList)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a duplicate decoded ledger-list key is ledger corruption rather than a generic bound failure');
		$duplicateMap = $nodes;
		$duplicateMap[3] = '<array><data><value><string>ma:1</string></value></data></array>';
		$duplicateMap[4] = '<struct><member><name>ma:1</name><value><string>1</string></value>' .
			'</member><member><name>ma:1</name><value><string>1</string></value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($duplicateMap)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a duplicate decoded ledger-map key is classified as ledger corruption');
		$duplicateWithMalformedValue = $nodes;
		$duplicateWithMalformedValue[3] =
			'<array><data><value><string>ma:1</string></value></data></array>';
		$duplicateWithMalformedValue[4] = '<struct><member><name>ma:1</name>' .
			'<value><string>1</string></value></member><member><name>ma:1</name>' .
			'<value><i8>01</i8></value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($duplicateWithMalformedValue)) ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'a malformed duplicate-member value outranks the earlier duplicate-name semantic');
		$wrongType = $nodes;
		$wrongType[3] = '<array><data><value><string>ma:1</string></value></data></array>';
		$wrongType[4] = '<struct><member><name>ma:1</name><value><i8>1</i8></value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($wrongType)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'a well-formed non-string ledger scalar is classified as ledger corruption');
		foreach (array('<array><data/></array>', '<struct/>') as $container) {
			$wrongContainer = $nodes;
			$wrongContainer[3] =
				'<array><data><value><string>ma:1</string></value></data></array>';
			$wrongContainer[4] = '<struct><member><name>ma:1</name><value>' . $container .
				'</value></member></struct>';
			$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
				$this->tinyHistoricalResponse($wrongContainer)) ===
				array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
				'a bounded well-formed non-string ledger container is ledger corruption');
		}
		$wrongValue = $nodes;
		$wrongValue[3] = '<array><data><value><string>ma:1</string></value></data></array>';
		$wrongValue[4] = '<struct><member><name>ma:1</name><value><string>2</string>' .
			'</value></member></struct>';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($wrongValue)) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'an explicit non-one ledger value is classified as ledger corruption');
		$overBoundWithForeign = $this->tinyHistoricalClaimNames(2049);
		$overBoundWithForeign[] = 'foreign:key';
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2(
			$this->tinyHistoricalResponse($this->tinyHistoricalLedgerNodes($overBoundWithForeign))) ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'the profile-claim application bound outranks decoded-ledger corruption');
		$this->assertTrue(retrackersDecodeHistoricalBindingResponseV2('not framed') ===
			array('ok' => false, 'failure' => 'malformed-response'),
			'non-SCGI input remains a malformed historical response');
	}

