	public function testRecoveryRows4ProjectsTheFrozenMarkerAckDecisionTableCompactly()
	{
		$this->assertTrue(class_exists('RetrackersRecoveryRows4Decisions', false),
			'update.php declares the compact one-pass RecoveryRows4 decision projector');
		if (!class_exists('RetrackersRecoveryRows4Decisions', false)) {
			return;
		}
		$userHash = str_repeat('a', 64);
		$tx = str_repeat('b', 32);
		$rows = array();
		$markers = array(
			array('', '', 'C'),
			array('original-equal', null, 'O'),
			array('original-empty', '', 'P'),
			array('v1:candidate-claim:' . $tx, '', 'A'),
			array('v1:rollback-claim:' . $tx, '', 'B'),
			array('v1:candidate-ready:' . $tx, null, 'R'),
			array('v1:rollback-ready:' . $tx, null, 'S'),
			array('v1:candidate-ready:' . $tx, '', 'I'),
			array('v1:rollback-ready:' . $tx, '', 'J'),
			array('', 'foreign-ack-secret', 'Q'),
			array('original-wrong', 'wrong-original-ack-secret', 'Q'),
			array('original-mismatched-local', '', 'Q'),
			array('v1:candidate-claim:' . $tx, 'claim-ack-secret', 'Q'),
			array('v1:candidate-ready:' . $tx, 'ready-wrong-ack-secret', 'Q'),
			array('unknown-marker-secret', '', 'Q'),
		);
		foreach ($markers as $index => $markerCase) {
			$hash = str_pad(strtoupper(dechex($index + 1)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index + 1)), 39, '0', STR_PAD_LEFT);
			if (strncmp($markerCase[0], 'original-', 9) === 0) {
				$markerLocal = $markerCase[0] === 'original-mismatched-local' ? str_repeat('E', 40) : $localId;
				$marker = 'v1:original:1:' . $markerLocal . ':' . $userHash;
			} else {
				$marker = $markerCase[0];
			}
			$ack = $markerCase[1] === null ? $marker : $markerCase[1];
			$rows[] = array($hash, $localId, $marker, $ack);
		}
		$result = RetrackersRecoveryRows4Decisions::project($this->packedRecoveryRows4($rows), 15);
		$this->assertTrue(is_array($result) && $result['ok'] && $result['count'] === 15 &&
			$result['quarantine_count'] === 6 &&
			$this->recoveryDecisionClasses($result['packed']) === 'COPABRSIJQQQQQQ',
			'the frozen clean/owned/prefix/partial/ready/incomplete/quarantine table is exact');
		$this->assertTrue(strpos($result['packed'], 'foreign-ack-secret') === false &&
			strpos($result['packed'], 'wrong-original-ack-secret') === false &&
			strpos($result['packed'], 'unknown-marker-secret') === false,
			'quarantine retains only bounded length/digest evidence, never arbitrary marker or ack bytes');
		$this->assertTrue(strpos($result['packed'], $tx) !== false &&
			strpos($result['packed'], $userHash) !== false,
			'canonical transaction and original ownership fields remain reusable compact authority');
	}

	public function testRecoveryRows4RejectsTruncatedExtraDuplicateAndUnorderedPackedRecords()
	{
		$this->assertTrue(class_exists('RetrackersRecoveryRows4Decisions', false),
			'update.php declares the RecoveryRows4 structural revalidation boundary');
		if (!class_exists('RetrackersRecoveryRows4Decisions', false)) {
			return;
		}
		$row1 = array(str_repeat('0', 39) . '1', str_repeat('A', 40), '', '');
		$row2 = array(str_repeat('0', 39) . '2', str_repeat('B', 40), '', '');
		$valid = $this->packedRecoveryRows4(array($row1, $row2));
		$cases = array(
			'truncated-header' => substr($valid, 0, 7),
			'count-mismatch' => substr_replace($valid, pack('N', 3), 4, 4),
			'truncated-cell' => substr($valid, 0, -1),
			'extra-byte' => $valid . 'x',
			'duplicate-hash' => $this->packedRecoveryRows4(array($row1,
				array($row1[0], $row2[1], '', ''))),
			'duplicate-local-id' => $this->packedRecoveryRows4(array($row1,
				array($row2[0], $row1[1], '', ''))),
			'unordered' => $this->packedRecoveryRows4(array($row2, $row1)),
			'invalid-identity' => $this->packedRecoveryRows4(array(array('lowercase', $row1[1], '', ''))),
		);
		foreach ($cases as $name => $packed) {
			$this->assertTrue(RetrackersRecoveryRows4Decisions::project($packed,
				$name === 'invalid-identity' ? 1 : 2) === false,
				$name . ' fails before any recovery decision is exposed');
		}
	}

	public function testHistoricalClassifierMapsEightObservationsToExactlySixPhases()
	{
