		$cases = array(
			'legacy single hook' => array('tadd_trackers1alice' => 'legacy-insert-action'),
			'legacy hook pair' => array('tadd_trackers1alice' => 'legacy-insert-action',
				'tadd_trackers2alice' => 'legacy-recovery-action'),
			'current pair with lost claim' => array('tadd_trackers1alice' =>
				'functional-alice-exact-bytes', 'tadd_trackers2alice' =>
				$this->historicalSafetyActionFixture()),
		);
		foreach ($cases as $name => $actions) {
			$sample = $this->historicalProjectionFixture($actions, array());
			$this->assertTrue($classifier->classify($sample, 'alice', null)['status'] ===
				'hook-ledger-mismatch', $name . ' reports only the observed hook and empty ledger');
			$adapter = $this->historicalQueueAdapter(array($sample, $sample));
			$called = false;
			$outcome = (new RetrackersStableHistoricalBinding($adapter))->consume('alice', null,
				new RetrackersHistoricalLedgerAttestation(true, true, true, true),
				function () use (&$called) { $called = true; });
			$this->assertTrue($outcome === array('ok' => false,
				'failure' => 'hook-ledger-mismatch-restart-required') &&
				$adapter->calls === 2 && !$called,
				$name . ' remains a two-read refusal before any consumer mutation');
			$readback = new class($sample) extends RetrackersLifecycleRpcAdapter {
				private $samples;
				public function __construct($sample) { $this->samples = array($sample, $sample); }
				public function historicalBindingSample(&$failure = null) {
					$failure = null;
					return(array_shift($this->samples));
				}
			};
			$readback->setFamily(2);
			$readbackFailure = null;
			$this->assertTrue($readback->coherentLifecycleReadback('alice', null,
				$readbackFailure) === false &&
				$readbackFailure === 'hook-ledger-mismatch-restart-required',
				$name . ' keeps the same closed reason at direct lifecycle readback');
			foreach (array('init', 'done') as $door) {
				$entryAdapter = $this->lifecycleQueueAdapter(array($sample, $sample));
				$jResult = '';
				$failure = null;
				$ok = $door === 'init' ? retrackersRunLifecycleInit('alice', '/plugin/run.sh',
					'/usr/bin/php', $jResult, $failure, $entryAdapter) :
					retrackersRunLifecycleDone('alice', $jResult, $failure, $entryAdapter);
				$this->assertTrue($ok === false &&
					$failure === 'hook-ledger-mismatch-restart-required' &&
					strpos($jResult, 'restart rTorrent and recheck') !== false &&
					$entryAdapter->callbackHistory === array(),
					$name . ' gives the closed reason at the ' . $door . ' entrypoint');
			}
		}
		$legacy = $this->historicalProjectionFixture($cases['legacy hook pair'], array());
		$current = $this->historicalProjectionFixture($cases['current pair with lost claim'], array());
		$unstable = (new RetrackersStableHistoricalBinding(
			$this->historicalQueueAdapter(array($legacy, $current))))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(true, true, true, true),
			function () { throw new Exception('unstable hook reached consumer'); });
		$this->assertTrue($unstable === array('ok' => false,
			'failure' => 'profile-binding-unstable'),
			'a changing hook still gets the unstable readback classification');
		$untrusted = (new RetrackersStableHistoricalBinding(
			$this->historicalQueueAdapter(array($legacy, $legacy))))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(false, true, true, true),
			function () { throw new Exception('untrusted ledger reached consumer'); });
		$this->assertTrue($untrusted === array('ok' => false,
			'failure' => 'receipt-ledger-corrupt'),
			'ledger attestation corruption outranks the neutral hook diagnosis');
		$markedRow = array(str_repeat('A', 40), str_repeat('B', 40),
			'v1:original:1:' . str_repeat('B', 40) . ':' . str_repeat('c', 64), '');
		$marked = $this->historicalProjectionFixture($cases['legacy hook pair'], array(),
			$this->packedRecoveryRows4(array($markedRow)));
		$this->assertTrue($classifier->classify($marked, 'alice', null)['status'] ===
			'ledger-corrupt', 'a persisted recovery marker still means structural corruption');
		$markedOutcome = (new RetrackersStableHistoricalBinding(
			$this->historicalQueueAdapter(array($marked, $marked))))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(true, true, true, true),
			function () { throw new Exception('marked recovery reached consumer'); });
		$this->assertTrue($markedOutcome === array('ok' => false,
			'failure' => 'receipt-ledger-corrupt'),
			'a real persisted marker remains visible as receipt-ledger-corrupt');
		$this->assertTrue(strpos(retrackersLifecycleDiagnosticJavascript('init',
			'receipt-ledger-corrupt'), 'restart rTorrent and recheck') === false,
			'the ledger corruption message does not claim a restart will repair a persisted marker');
	}

	/**
	 * An ordinary download is not an outstanding recovery.
	 *
	 * The rows this classifier reads come from an unfiltered d.multicall2 over
	 * the whole 'main' view (retrackersBuildHistoricalBindingRequestV2), so
	 * their COUNT is the number of downloads on the installation. Reading that
	 * count as "a recovery is in flight" made a first init answer
	 * 'receipt-ledger-corrupt' on any daemon holding a single torrent, and kept
	 * answering it: the ledger lives in the daemon's memory and comes back empty
	 * after every restart, while the torrents come back with the session.
	 * Measured on a live container -- zero torrents initialised, one torrent
	 * carrying no marker at all did not.
	 *
	 * The rule this pins: an empty ledger plus rows that carry NO marker is
	 * BOOTSTRAP, whatever the row count; the guard belongs to markers, which
	 * outlive the ledger, and the case above holds it there.
	 */
	public function testCleanDownloadsAreNotAnOutstandingRecoveryHoweverManyThereAre()
	{
		$this->installRtorrentQuoteDouble();
		$classifier = new RetrackersHistoricalBindingClassifier();

		foreach (array(1, 2, 400) as $downloads) {
			$sample = $this->historicalProjectionFixture(array(), array(),
				$this->packedRecoveryRows4Range($downloads));
			$verdict = $classifier->classify($sample, 'alice', null);
			$this->assertTrue($verdict['status'] === 'valid' && $verdict['phase'] === 'BOOTSTRAP',
				$downloads . ' marker-free downloads and an empty ledger are still BOOTSTRAP');
		}

		// The mirror image, so this case cannot pass by disabling the guard: one
		// marker among the same clean rows and the sample is corrupt again.
		$rows = array();
		for ($index = 1; $index <= 3; $index++) {
			$hash = str_pad(strtoupper(dechex($index)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index)), 39, '0', STR_PAD_LEFT);
			$rows[] = $index === 2
				? array($hash, $localId,
					'v1:original:0:' . $localId . ':' . str_repeat('d', 64), '')
				: array($hash, $localId, '', '');
		}
		$withMarker = $this->historicalProjectionFixture(array(), array(),
			$this->packedRecoveryRows4($rows));
		$this->assertTrue($classifier->classify($withMarker, 'alice', null)['status'] ===
			'ledger-corrupt',
			'one marker among clean rows still makes an empty ledger corruption');

		// And a marker this code cannot parse counts too. Absence is a known
		// state; present-but-unreadable is not, and must not read as absent.
		$unreadable = array();
		for ($index = 1; $index <= 3; $index++) {
			$hash = str_pad(strtoupper(dechex($index)), 40, '0', STR_PAD_LEFT);
			$localId = 'F' . str_pad(strtoupper(dechex($index)), 39, '0', STR_PAD_LEFT);
			$unreadable[] = $index === 2
				? array($hash, $localId, 'v1:original:0:' . $localId, '')
				: array($hash, $localId, '', '');
		}
		$withUnreadable = $this->historicalProjectionFixture(array(), array(),
			$this->packedRecoveryRows4($unreadable));
		$this->assertTrue($classifier->classify($withUnreadable, 'alice', null)['status'] ===
			'ledger-corrupt',
			'a marker in a shape this code cannot read is not the same as no marker');
	}

	public function testStableHistoricalBindingReadsExactlyTwiceAndExposesOnlySampleTwoDecision()
	{
		$this->installRtorrentQuoteDouble();
		$this->assertTrue(class_exists('RetrackersStableHistoricalBinding', false),
			'update.php declares the closed two-read historical binding authority');
		if (!class_exists('RetrackersStableHistoricalBinding', false)) {
			return;
		}
		$fixture = $this->historicalStateFixture('IDLE_CURRENT');
		$adapter = $this->historicalQueueAdapter(array($fixture['sample'], $fixture['sample']));
		$authority = new RetrackersStableHistoricalBinding($adapter);
		$consumed = array();
		$outcome = $authority->consume('alice', 'functional-alice-exact-bytes',
			new RetrackersHistoricalLedgerAttestation(true, true, true, true),
			function ($decision) use (&$consumed, $adapter) {
				$consumed[] = array('calls' => $adapter->calls, 'decision' => $decision);
				return('consumer-result');
			});
		$this->assertTrue($outcome === array('ok' => true, 'consumer_result' => 'consumer-result') &&
			$adapter->calls === 2 && count($consumed) === 1 && $consumed[0]['calls'] === 2,
			'the consumer runs once only after two complete named adapter reads');
		$decision = $consumed[0]['decision'];
		$this->assertTrue($decision['production_accepted'] === true &&
			$decision['phase'] === 'IDLE_CURRENT' &&
			$decision['observation'] === 'IDLE_CURRENT' &&
			$decision['persistent_epoch'] === str_repeat('1', 32) &&
			$decision['caller']['membership'] === 'profile',
			'the bounded sample-two decision carries exact phase, epoch and caller membership');
		$serialized = serialize($decision);
		$this->assertTrue(strpos($serialized, 'functional-alice-exact-bytes') === false &&
			strpos($serialized, $this->historicalSafetyActionFixture()) === false &&
			strpos($serialized, '<methodResponse>') === false,
			'the lifecycle decision exposes no functional/safety action bytes or raw XML');
		$consume = new ReflectionMethod('RetrackersStableHistoricalBinding', 'consume');
		$this->assertTrue($consume->getNumberOfParameters() === 4,
			'the closed consumer accepts one caller functional action and no action allow-map');
	}

	public function testStableHistoricalBindingSuppressesConsumerOnFailuresAndRetainedFieldDrift()
	{
		$this->installRtorrentQuoteDouble();
		$this->assertTrue(class_exists('RetrackersStableHistoricalBinding', false),
			'update.php declares stable failure and drift handling');
		if (!class_exists('RetrackersStableHistoricalBinding', false)) {
			return;
		}
		$fixture = $this->historicalStateFixture('IDLE_EMPTY_CURRENT', str_repeat('a', 64));
		$attestation = new RetrackersHistoricalLedgerAttestation(true, true, true, true);
		$consumerCalls = 0;
		$consumer = function () use (&$consumerCalls) {
			$consumerCalls++;
		};
		$firstFailure = $this->historicalQueueAdapter(array(array('failure' => 'transport-failed')));
		$outcome = (new RetrackersStableHistoricalBinding($firstFailure))->consume(
			'alice', null, $attestation, $consumer);
		$this->assertTrue($outcome === array('ok' => false, 'failure' => 'transport-failed') &&
			$firstFailure->calls === 1 && $consumerCalls === 0,
			'a first read failure stops without retry, third read or consumer');
		$secondFailure = $this->historicalQueueAdapter(array($fixture['sample'],
			array('failure' => 'receipt-ledger-corrupt')));
		$outcome = (new RetrackersStableHistoricalBinding($secondFailure))->consume(
			'alice', null, $attestation, $consumer);
		$this->assertTrue($outcome === array('ok' => false, 'failure' => 'receipt-ledger-corrupt') &&
			$secondFailure->calls === 2 && $consumerCalls === 0,
			'a second read failure exposes neither the first projection nor a lifecycle decision');

		$epochDrift = $fixture['sample'];
		$epochDrift['value']['ledger_keys'] = array('pv:' . str_repeat('3', 32));
		$drifts = array(
			'family' => array($fixture['sample'], array_replace($fixture['sample'], array('family' => 1))),
			'raw digest' => array($fixture['sample'], $this->historicalStateFixture(
				'IDLE_EMPTY_CURRENT', str_repeat('b', 64))['sample']),
			'epoch with equal digest' => array($fixture['sample'], $epochDrift),
		);
		$changedFunctional = 'functional-alice-new-exact-bytes';
		$drifts['action and claim with equal digest/count/phase'] = array(
			$this->historicalStateFixture('IDLE_CURRENT', str_repeat('e', 64))['sample'],
			$this->historicalProjectionFixture(array(
				'tadd_trackers1alice' => $changedFunctional,
				'tadd_trackers2alice' => $this->historicalSafetyActionFixture()), array(
				'pv:' . str_repeat('1', 32), 'pf:' . hash('sha256', 'alice') . ':' .
					hash('sha256', $changedFunctional)), null, str_repeat('e', 64)),
		);
		$drifts['receipt key with equal digest/count/phase'] = array(
			$this->historicalProjectionFixture(array(), array('pv:' . str_repeat('1', 32), 'dq:1'),
				null, str_repeat('f', 64)),
			$this->historicalProjectionFixture(array(), array('pv:' . str_repeat('1', 32),
				'wa:' . str_repeat('4', 32)), null, str_repeat('f', 64)),
		);
		$drifts['caller membership with equal digest/count/phase'] = array(
			$this->historicalStateFixture('IDLE_CURRENT', str_repeat('6', 64))['sample'],
			$this->historicalProjectionFixture(array(
				'tadd_trackers1bob' => 'functional-bob-exact-bytes',
				'tadd_trackers2bob' => $this->historicalSafetyActionFixture()), array(
				'pv:' . str_repeat('1', 32), 'pf:' . hash('sha256', 'bob') . ':' .
					hash('sha256', 'functional-bob-exact-bytes')), null, str_repeat('6', 64)),
		);
		$rowHash = str_repeat('0', 39) . '1';
		$rowLocal = str_repeat('A', 40);
		$firstRows = $this->packedRecoveryRows4(array(array($rowHash, $rowLocal, '', '')));
		$marker = 'v1:original:1:' . $rowLocal . ':' . str_repeat('c', 64);
		$secondRows = $this->packedRecoveryRows4(array(array($rowHash, $rowLocal, $marker, '')));
		$drifts['recovery decision with equal digest/count'] = array(
			$this->historicalProjectionFixture(array(), array('pv:' . str_repeat('1', 32)),
				$firstRows, str_repeat('d', 64)),
			$this->historicalProjectionFixture(array(), array('pv:' . str_repeat('1', 32)),
				$secondRows, str_repeat('d', 64)),
		);
		foreach ($drifts as $name => $pair) {
			$adapter = $this->historicalQueueAdapter($pair);
			$outcome = (new RetrackersStableHistoricalBinding($adapter))->consume(
				'alice', null, $attestation, $consumer);
			$expected = $name === 'recovery decision with equal digest/count' ?
				'marked-recovery-pending' : 'profile-binding-unstable';
			$this->assertTrue($outcome === array('ok' => false, 'failure' => $expected) &&
				$adapter->calls === 2 && $consumerCalls === 0,
				$name . ' drift refuses without digest-only acceptance or consumer exposure');
		}
	}

