	public function testHistoricalRecoveryDecisionProjectionAcceptsExactMaxUnderBoundedMemory()
	{
		$this->installRtorrentQuoteDouble();
		$exactPacked = $this->packedRecoveryRows4Range(16384);
		$beforePeak = memory_get_peak_usage(true);
		$exact = RetrackersRecoveryRows4Decisions::project($exactPacked, 16384);
		$peakDelta = memory_get_peak_usage(true) - $beforePeak;
		$this->assertTrue(is_array($exact) && $exact['count'] === 16384 &&
			$exact['quarantine_count'] === 0 && strlen($exact['packed']) < 4194304,
			'the exact 16384-row boundary retains one compact decision buffer');
		$maxPlusOne = $this->packedRecoveryRows4Range(16385);
		$this->assertTrue(RetrackersRecoveryRows4Decisions::project($maxPlusOne, 16385) === false,
			'the 16385th packed recovery row is rejected before decision exposure');
		$this->assertTrue($peakDelta < 64 * 1024 * 1024,
			'the exact-row projector uses bounded transient memory below 64 MiB in-process');
		unset($exact, $maxPlusOne);
		$sample = $this->historicalProjectionFixture(array(),
			array('pv:' . str_repeat('1', 32)), $exactPacked);
		$adapter = $this->historicalQueueAdapter(array($sample, $sample));
		$seen = null;
		$outcome = (new RetrackersStableHistoricalBinding($adapter))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(true, true, true, true),
			function ($decision) use (&$seen) {
				$seen = $decision;
				return('accepted-max');
			});
		$this->assertTrue($outcome === array('ok' => true, 'consumer_result' => 'accepted-max') &&
			$adapter->calls === 2 && $seen['binding']['counts']['recovery_rows'] === 16384 &&
			strlen($seen['recovery_decisions']) < 4194304,
			'the exact-max stable pair retains bounded sample-2 recovery decisions across exactly two reads');
	}

