	public function testHistoricalRefusalPrecedenceKeepsBusyBehindTrustDriftAndSemantics()
	{
		$this->installRtorrentQuoteDouble();
		$this->assertTrue(class_exists('RetrackersStableHistoricalBinding', false),
			'update.php declares the exact historical refusal precedence authority');
		if (!class_exists('RetrackersStableHistoricalBinding', false)) {
			return;
		}
		$trusted = new RetrackersHistoricalLedgerAttestation(true, true, true, true);
		$never = function () {
			throw new Exception('refusal reached lifecycle consumer');
		};
		$idle = $this->historicalStateFixture('IDLE_EMPTY_CURRENT');
		$transport = $this->historicalQueueAdapter(array(array('failure' => 'transport-failed')));
		$this->assertTrue((new RetrackersStableHistoricalBinding($transport))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(false, false, false, false), $never) ===
			array('ok' => false, 'failure' => 'transport-failed') && $transport->calls === 1,
			'transport failure precedes an independently corrupt attestation');
		$adapter = $this->historicalQueueAdapter(array($idle['sample'], $idle['sample']));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(false, true, true, true), $never) ===
			array('ok' => false, 'failure' => 'receipt-ledger-corrupt'),
			'privacy/type/modifiability failure precedes stable lifecycle classification');
		$adapter = $this->historicalQueueAdapter(array($idle['sample'], $idle['sample']));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume('alice', null,
			new RetrackersHistoricalLedgerAttestation(true, true, true, false), $never) ===
			array('ok' => false, 'failure' => 'profile-binding-writer-untrusted'),
			'absent exclusive-writer assurance is visible before acceptance');

		$secondOwner = $this->historicalStateFixture('SECOND_INIT_OWNER');
		$busyDrift = $secondOwner['sample'];
		foreach ($busyDrift['value']['ledger_keys'] as &$key) {
			if (strncmp($key, 'pv:', 3) === 0) {
				$key = 'pv:' . str_repeat('7', 32);
			}
		}
		unset($key);
		sort($busyDrift['value']['ledger_keys'], SORT_STRING);
		$adapter = $this->historicalQueueAdapter(array($secondOwner['sample'], $busyDrift));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume(
			'alice', 'functional-alice-exact-bytes', $trusted, $never) ===
			array('ok' => false, 'failure' => 'profile-binding-unstable'),
			'pair drift precedes an otherwise valid foreign-owner BUSY result');
		$adapter = $this->historicalQueueAdapter(array($secondOwner['sample'], $secondOwner['sample']));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume(
			'alice', 'functional-alice-exact-bytes', $trusted, $never) ===
			array('ok' => false, 'failure' => 'lifecycle-busy'),
			'a stable valid foreign owner yields BUSY after trust and stability checks');
		$invalidOwner = $secondOwner['sample'];
		foreach ($invalidOwner['value']['actions'] as &$entry) {
			if ($entry['name'] === 'tadd_trackers1bob') {
				$entry['value'] = 'invalid-owner-action';
				$entry['digest'] = retrackersRestrictedHashString($entry['value']);
			}
		}
		unset($entry);
		$adapter = $this->historicalQueueAdapter(array($invalidOwner, $invalidOwner));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume(
			'alice', 'functional-alice-exact-bytes', $trusted, $never) ===
			array('ok' => false, 'failure' => 'historical-hook-restart-required'),
			'an invalid foreign-owner action cannot be masked by BUSY');
		$contained = $this->historicalStateFixture('CONTAINED');
		$adapter = $this->historicalQueueAdapter(array($contained['sample'], $contained['sample']));
		$this->assertTrue((new RetrackersStableHistoricalBinding($adapter))->consume(
			'alice', null, $trusted, $never) ===
			array('ok' => false, 'failure' => 'shared-daemon-contained'),
			'valid contained state remains a distinct visible restart-required refusal');
	}

	public function testSourceScalarBatchUsesTheCapturedTwentyThreeMemberWireContract()
	{
		$required = array('retrackersBuildSourceScalarRequest',
			'retrackersDecodeSourceScalarResponse', 'retrackersBuildSourceGenericMapRequest',
			'retrackersBuildSourceTrackerRequest');
		foreach ($required as $function) {
			if (!function_exists($function)) {
				$this->assertTrue(false,
					'update.php declares the closed source snapshot request and decode operations');
				return;
			}
		}
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		$scalarRequest = retrackersBuildSourceScalarRequest($hash);
		$this->assertTrue(strlen($scalarRequest) === 6326 && hash('sha256', $scalarRequest) ===
			'4311065f69e432a96cca199ff0cf0eae63b953b816675bf39bb90bd34530a357',
			'the scalar request is the exact captured 23-member order and spelling');
		$mapRequest = retrackersBuildSourceGenericMapRequest($hash);
		$this->assertTrue(strlen($mapRequest) === 214 && hash('sha256', $mapRequest) ===
			'4f2277156aa479f974ee271bfbd8143e7b51a26babe7ebd387e7772ff88e2931',
			'the map request is the captured direct d.custom.items operation');
		$trackerRequest = retrackersBuildSourceTrackerRequest($hash);
		$this->assertTrue(strlen($trackerRequest) === 570 && hash('sha256', $trackerRequest) ===
			'3dc0c79cdce5f9ca6826dc1439ee227521f629c0edafe1c526d06efd62f8774f',
			'the tracker request is the captured direct five-column t.multicall operation');

		$old = retrackersDecodeSourceScalarResponse($this->capturedRaw('rt098-source-scalar23'));
		$new = retrackersDecodeSourceScalarResponse($this->capturedRaw('rt1621-source-scalar23'));
		$this->assertTrue(is_array($old) && $old['family'] === 1 &&
			count($old['values']) === 23 && $old['values']['session_path'] === '/session/' &&
			$old['values']['priority'] === '2' && $old['values']['trackers_use_udp'] === '0',
			'the literal rTorrent 0.9.8 capture decodes as 15 strings and 8 i8 values');
		$this->assertTrue(is_array($new) && $new['family'] === 2 &&
			count($new['values']) === 23 && $new['values']['session_path'] === '/data/.session/' &&
			$new['values']['priority'] === '2' && $new['values']['trackers_use_udp'] === '1',
			'the literal rTorrent 0.16.21 capture decodes as 15 strings and 8 i8 values');
		$wrongTag = $this->replaceRawBodyOnce($this->capturedRaw('rt1621-source-scalar23'),
			'<i8>2</i8>', '<i4>2</i4>');
		$this->assertTrue(retrackersDecodeSourceScalarResponse($wrongTag) === false,
			'the source scalar decoder rejects a wrong integer tag before projection');
	}

	public function testSourceAdapterExposesOnlyThreeClosedReadsThroughTheRawBoundary()
	{
		if (!$this->installRawTransportDouble()) {
			return;
		}
		$adapter = new RetrackersDirectRpcAdapter();
		$public = get_class_methods($adapter);
		sort($public, SORT_STRING);
		$this->assertEquals(array('historicalBindingSample', 'sourceGenericMapSnapshot',
			'sourceScalarSnapshot', 'sourceTrackerSnapshot'), $public,
			'the adapter exposes only the frozen historical and three named source reads');
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		global $scgi_host, $scgi_port;
		$scgi_host = '/tmp/retrackers-source-test.sock';
		$scgi_port = 0;
		$cases = array(
			array('sourceScalarSnapshot', 'rt1621-source-scalar23',
				retrackersBuildSourceScalarRequest($hash), 'values'),
			array('sourceGenericMapSnapshot', 'rt1621-custom-map',
				retrackersBuildSourceGenericMapRequest($hash), 'pairs'),
			array('sourceTrackerSnapshot', 'rt1621-trackers-populated',
				retrackersBuildSourceTrackerRequest($hash), 'rows'),
		);
		foreach ($cases as $case) {
			rSCGITransport::$calls = array();
			rSCGITransport::$raw = $this->capturedRaw($case[1]);
			$failure = 'stale';
			$result = $adapter->{$case[0]}($hash, $failure);
			$this->assertTrue(is_array($result) && isset($result[$case[3]]) &&
				$failure === null && count(rSCGITransport::$calls) === 1 &&
				rSCGITransport::$calls[0]['argument_count'] === 9 &&
				rSCGITransport::$calls[0]['arguments'][2] === $case[2],
				$case[0] . ' binds one exact request and plan to the shared nine-argument RAW send');
		}
		$memberFault = $this->replaceRawBodyOnce(
			$this->capturedRaw('rt1621-source-scalar23'),
			'<value><array><data><value><string>/data/.session/</string></value></data></array></value>',
			'<value><struct><member><name>faultCode</name><value><i8>-500</i8></value></member>' .
			'<member><name>faultString</name><value><string>hash missing</string></value></member>' .
			'</struct></value>');
		rSCGITransport::$calls = array();
		rSCGITransport::$raw = $memberFault;
		$failure = null;
		$this->assertTrue($adapter->sourceScalarSnapshot($hash, $failure) === false &&
			$failure === 'rpc-fault' && count(rSCGITransport::$calls) === 1,
			'a scalar member fault stays distinct from malformed XML after one RAW send');
	}

