	public function testSourceMissingTargetHasADedicatedTerminalClassification()
	{
		if (!$this->installRawTransportDouble()) {
			return;
		}
		$adapter = new RetrackersDirectRpcAdapter();
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		global $scgi_host, $scgi_port;
		$scgi_host = '/tmp/retrackers-source-test.sock';
		$scgi_port = 0;
		foreach (array('rt098-source-scalar23-missing',
			'rt1621-source-scalar23-missing') as $capture) {
			rSCGITransport::$calls = array();
			rSCGITransport::$raw = $this->capturedRaw($capture);
			$failure = null;
			$this->assertTrue($adapter->sourceScalarSnapshot($hash, $failure) === false &&
				$failure === 'target-absent' && count(rSCGITransport::$calls) === 1,
				$capture . ' is classified as target-absent without another read');
		}
		$scalarWrongFault = preg_replace('/info-hash not found/', 'info/hash not found',
			$this->capturedRaw('rt1621-source-scalar23-missing'), 1, $replacementCount);
		rSCGITransport::$calls = array();
		rSCGITransport::$raw = $scalarWrongFault;
		$failure = null;
		$this->assertTrue($replacementCount === 1 &&
			$adapter->sourceScalarSnapshot($hash, $failure) === false &&
			$failure === 'rpc-fault' && count(rSCGITransport::$calls) === 1,
			'one non-missing target fault prevents scalar absence classification');

		$directFaults = array(
			'rt098-direct-fault' => array('<i4>-501</i4>', '<i4>-506</i4>',
				'Could not find info-hash.', 'Could not find info/hash.'),
			'rt1621-direct-fault' => array('<i8>-500</i8>', '<i8>-506</i8>',
				'info-hash not found', 'info/hash not found'),
		);
		foreach ($directFaults as $capture => $mutations) {
			foreach (array('sourceGenericMapSnapshot', 'sourceTrackerSnapshot') as $method) {
				rSCGITransport::$calls = array();
				rSCGITransport::$raw = $this->capturedRaw($capture);
				$failure = null;
				$this->assertTrue($adapter->{$method}($hash, $failure) === false &&
					$failure === 'target-absent' && count(rSCGITransport::$calls) === 1,
					$method . ' keeps the captured missing target distinct from an RPC fault');
				foreach (array(array($mutations[0], $mutations[1]),
					array($mutations[2], $mutations[3])) as $mutation) {
					rSCGITransport::$calls = array();
					rSCGITransport::$raw = str_replace($mutation[0], $mutation[1],
						$this->capturedRaw($capture), $replacementCount);
					$failure = null;
					$this->assertTrue($replacementCount === 1 &&
						$adapter->{$method}($hash, $failure) === false &&
						$failure === 'rpc-fault' && count(rSCGITransport::$calls) === 1,
						$method . ' requires the exact family-specific missing-target fault');
				}
			}
		}

		$scalar = $this->sourceScalarFixture();
		$queue = $this->sourceQueueAdapter(array(array('failure' => 'target-absent')),
			array(), array());
		$outcome = (new RetrackersStableSourceSnapshot($queue))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$this->assertTrue($outcome === array('ok' => false, 'failure' => 'initial-absent') &&
			count($queue->calls) === 1,
			'a missing object is terminal initial-absent and never starts another snapshot round');
	}

	public function testStableSourceSnapshotBracketsCanonicalMapAndTrackerPairs()
	{
		if (!class_exists('RetrackersStableSourceSnapshot', false)) {
			$this->assertTrue(false,
				'update.php declares the stable source snapshot authority');
			return;
		}
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		$scalar = $this->sourceScalarFixture();
		$map = $this->sourceMapFixture();
		$mapReordered = $map;
		$mapReordered['pairs'] = array_reverse($mapReordered['pairs']);
		$trackers = $this->sourceTrackerFixture();
		$trackersReordered = $trackers;
		$trackersReordered['rows'] = array_reverse($trackersReordered['rows']);
		$adapter = $this->sourceQueueAdapter(array($scalar, $scalar),
			array($map, $mapReordered), array($trackers, $trackersReordered));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$expectedCalls = array();
		foreach (array('scalar', 'map', 'map', 'tracker', 'tracker', 'scalar') as $kind) {
			$expectedCalls[] = $kind . ':' . $hash;
		}
		$this->assertTrue(is_array($outcome) && $outcome['ok'] === true &&
			$adapter->calls === $expectedCalls,
			'the accepted snapshot uses one complete scalar-map-map-tracker-tracker-scalar bracket');
		if (!is_array($outcome) || !isset($outcome['snapshot'])) {
			return;
		}
		$snapshot = $outcome['snapshot'];
		$this->assertTrue($snapshot['source'] === array('kind' => 'session',
			'path' => '/session/' . $hash . '.torrent') &&
			$snapshot['scalar']['loaded_file'] === '/loaded-file-guard',
			'the session path wins without a filesystem probe while loaded_file remains a guard');
		$this->assertEquals(array(
			array('name' => 'present-empty', 'value' => ''),
			array('name' => 'retrackers-recovery',
				'value' => $scalar['values']['recovery_marker']),
			array('name' => 'retrackers-recovery-ack',
				'value' => $scalar['values']['recovery_ack']),
		), $snapshot['generic_map'],
			'the complete sorted generic map retains a present-empty value');
		$this->assertEquals(array(
			array('group' => '0', 'url' => 'http://127.0.0.1:9/a', 'type' => '1',
				'extra' => '0'),
			array('group' => '0', 'url' => 'http://127.0.0.1:9/b', 'type' => '1',
				'extra' => '0'),
		), $snapshot['tracker_topology'],
			'intra-tier tracker row order is not topology identity');
		$this->assertEquals(array(
			array('url' => 'http://127.0.0.1:9/a', 'multiplicity' => 1, 'state' => '0'),
			array('url' => 'http://127.0.0.1:9/b', 'multiplicity' => 1, 'state' => '1'),
		), $snapshot['tracker_enabled'],
			'enabled state is frozen by exact URL with multiplicity');
	}

	public function testSourceSelectionAndInitialOwnershipLifecycleGuardsAreFailClosed()
	{
		if (!class_exists('RetrackersStableSourceSnapshot', false)) {
			$this->assertTrue(false,
				'update.php declares the source selection and ownership authority');
			return;
		}
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		$capture = function ($scalar, $map, $tracker, $handoff) use ($hash) {
			$adapter = $this->sourceQueueAdapter(array($scalar, $scalar),
				array($map, $map), array($tracker, $tracker));
			return(array((new RetrackersStableSourceSnapshot($adapter))->capture($hash, $handoff),
				$adapter));
		};
		$invalid = $this->sourceQueueAdapter(array(), array(), array());
		$this->assertTrue((new RetrackersStableSourceSnapshot($invalid))->capture(
			strtolower($hash), 'not-a-handoff') ===
			array('ok' => false, 'failure' => 'ownership-mismatch') && $invalid->calls === array(),
			'invalid source authority input is refused before any RPC read');

		$scalar = $this->sourceScalarFixture(array('session_path' => '',
			'tied_source' => 'missing://tied-source'));
		list($tied) = $capture($scalar, $this->sourceMapFixture(),
			$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
		$this->assertTrue($tied['ok'] === true && $tied['snapshot']['source'] ===
			array('kind' => 'tied', 'path' => 'missing://tied-source'),
			'a nonempty tied source is accepted without probing the filesystem when session is empty');

		$scalar = $this->sourceScalarFixture(array('session_path' => 'virtual://session/',
			'tied_source' => 'missing://must-not-win'));
		list($session) = $capture($scalar, $this->sourceMapFixture(),
			$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
		$this->assertTrue($session['ok'] === true && $session['snapshot']['source'] ===
			array('kind' => 'session', 'path' => 'virtual://session/' . $hash . '.torrent'),
			'a nonempty session path always wins over tied and loaded-file strings');

		foreach (array(array('0', '0', '0'), array('0', '0', '1')) as $lifecycle) {
			$scalar = $this->sourceScalarFixture(array('state' => $lifecycle[0],
				'is_active' => $lifecycle[1], 'is_open' => $lifecycle[2]));
			list($allowed) = $capture($scalar, $this->sourceMapFixture(),
				$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
			$this->assertTrue($allowed['ok'] === true,
				'the characterized stopped lifecycle ' . implode(',', $lifecycle) . ' is eligible');
		}
		$scalar = $this->sourceScalarFixture(array('trackers_use_udp' => '0'), 2);
		list($newFamilyUdpOff) = $capture($scalar, $this->sourceMapFixture(array(), 2),
			$this->sourceTrackerFixture(null, 2), $scalar['values']['recovery_marker']);
		$this->assertTrue($newFamilyUdpOff ===
			array('ok' => false, 'failure' => 'initial-malformed'),
			'rTorrent 0.16.21 must expose its fixed trackers.use_udp value as one');
		foreach (array('0', '1') as $udp) {
			$scalar = $this->sourceScalarFixture(array('trackers_use_udp' => $udp), 1);
			list($oldFamilyUdp) = $capture($scalar, $this->sourceMapFixture(array(), 1),
				$this->sourceTrackerFixture(null, 1), $scalar['values']['recovery_marker']);
			$this->assertTrue($oldFamilyUdp['ok'] === true,
				'the older XMLRPC family accepts canonical trackers.use_udp=' . $udp);
		}
		$localId = $this->sourceScalarFixture()['values']['local_id'];
		$stateOneHandoff = 'v1:original:1:' . $localId . ':' . hash('sha256', 'alice');
		$startedScalar = $this->sourceScalarFixture(array('state' => '1', 'is_active' => '1',
			'is_open' => '1', 'recovery_marker' => $stateOneHandoff,
			'recovery_ack' => $stateOneHandoff));
		$startedMap = $this->sourceMapFixture(array('retrackers-recovery' => $stateOneHandoff,
			'retrackers-recovery-ack' => $stateOneHandoff));
		list($started) = $capture($startedScalar, $startedMap,
			$this->sourceTrackerFixture(), $stateOneHandoff);
		$this->assertTrue($started['ok'] === true,
			'the characterized active lifecycle 1,1,1 is eligible');

		$scalar = $this->sourceScalarFixture(array('session_path' => '', 'tied_source' => '',
			'loaded_file' => '/not-a-source'));
		list($missing) = $capture($scalar, $this->sourceMapFixture(),
			$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
		$this->assertTrue($missing === array('ok' => false, 'failure' => 'source-unreadable'),
			'loaded_file alone is a CAS guard and never becomes a third source');

		$scalar = $this->sourceScalarFixture(array('recovery_marker' => 'foreign',
			'recovery_ack' => 'foreign'));
		$map = $this->sourceMapFixture(array('retrackers-recovery' => 'foreign',
			'retrackers-recovery-ack' => 'foreign'));
		list($foreign) = $capture($scalar, $map, $this->sourceTrackerFixture(),
			$this->sourceScalarFixture()['values']['recovery_marker']);
		$this->assertTrue($foreign === array('ok' => false, 'failure' => 'ownership-mismatch'),
			'a stable foreign marker and acknowledgement cannot authorize the original generation');

		$scalar = $this->sourceScalarFixture(array('state' => '1', 'is_active' => '0',
			'is_open' => '1', 'recovery_marker' => $stateOneHandoff,
			'recovery_ack' => $stateOneHandoff));
		$map = $this->sourceMapFixture(array('retrackers-recovery' => $stateOneHandoff,
			'retrackers-recovery-ack' => $stateOneHandoff));
		list($paused) = $capture($scalar, $map, $this->sourceTrackerFixture(), $stateOneHandoff);
		$this->assertTrue($paused === array('ok' => false, 'failure' => 'lifecycle-unsupported'),
			'the measured paused tuple is refused without lifecycle mutation');

		foreach (array('1', '2', '3') as $hashing) {
			$scalar = $this->sourceScalarFixture(array('hashing' => $hashing));
			list($busyHashing) = $capture($scalar, $this->sourceMapFixture(),
				$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
			$this->assertTrue($busyHashing ===
				array('ok' => false, 'failure' => 'lifecycle-unsupported'),
				'd.hashing enum ' . $hashing . ' is valid wire data but not an eligible lifecycle');
		}

		foreach (array('-9223372036854775808', '-1', '1', '2', '3', '17') as $hashingFailed) {
			$scalar = $this->sourceScalarFixture(array('hashing_failed' => $hashingFailed));
			list($failed) = $capture($scalar, $this->sourceMapFixture(),
				$this->sourceTrackerFixture(), $scalar['values']['recovery_marker']);
			$this->assertTrue($failed ===
				array('ok' => false, 'failure' => 'initial-hashing-failed'),
				'an already canonical nonzero hashing_failed=' . $hashingFailed .
				' original is classified as failed rather than malformed');
		}
	}

	public function testSourceSnapshotRetriesOnlyCompleteRoundsWithoutMixingSamples()
	{
		if (!class_exists('RetrackersStableSourceSnapshot', false)) {
			$this->assertTrue(false,
				'update.php declares the bounded complete-round snapshot authority');
			return;
		}
		$hash = 'F5B2DC3C9AD3D8351B3536979490D1B10B9057B8';
		$scalar = $this->sourceScalarFixture();
		$tracker = $this->sourceTrackerFixture();
		foreach (array('transport-failed' => 'initial-transport',
			'rpc-fault' => 'initial-fault', 'malformed-response' => 'initial-malformed')
			as $wireFailure => $visibleFailure) {
			$failedAdapter = $this->sourceQueueAdapter(
				array(array('failure' => $wireFailure)), array(), array());
			$failed = (new RetrackersStableSourceSnapshot($failedAdapter))->capture(
				$hash, $scalar['values']['recovery_marker']);
			$this->assertTrue($failed === array('ok' => false, 'failure' => $visibleFailure) &&
				count($failedAdapter->calls) === 1,
				'a ' . $wireFailure . ' source read is classified without retry');
		}
		$firstMap = $this->sourceMapFixture(array('round' => 'one-a'));
		$firstMapDrift = $this->sourceMapFixture(array('round' => 'one-b'));
		$secondMap = $this->sourceMapFixture(array('round' => 'two'));
		$adapter = $this->sourceQueueAdapter(array($scalar, $scalar, $scalar, $scalar),
			array($firstMap, $firstMapDrift, $secondMap, $secondMap),
			array($tracker, $tracker, $tracker, $tracker));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$this->assertTrue($outcome['ok'] === true && count($adapter->calls) === 12 &&
			$this->pairsToMap($outcome['snapshot']['generic_map'])['round'] === 'two',
			'a drifting first generation is discarded and only the complete second round is exposed');
		$scalarDrift = $this->sourceScalarFixture(array('custom1' => 'changed-between-brackets'));
		$stableMap = $this->sourceMapFixture();
		$adapter = $this->sourceQueueAdapter(array($scalar, $scalarDrift, $scalar, $scalar),
			array($stableMap, $stableMap, $stableMap, $stableMap),
			array($tracker, $tracker, $tracker, $tracker));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$this->assertTrue($outcome['ok'] === true && count($adapter->calls) === 12 &&
			$outcome['snapshot']['scalar']['custom1'] === $scalar['values']['custom1'],
			'a scalar bracket drift discards every specialised sample from that generation');

		$maps = array();
		for ($round = 0; $round < 3; $round++) {
			$maps[] = $this->sourceMapFixture(array('round' => (string)$round . '-a'));
			$maps[] = $this->sourceMapFixture(array('round' => (string)$round . '-b'));
		}
		$adapter = $this->sourceQueueAdapter(array_fill(0, 6, $scalar), $maps,
			array_fill(0, 6, $tracker));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$this->assertTrue($outcome === array('ok' => false,
			'failure' => 'runtime-map-unstable') && count($adapter->calls) === 18,
			'three drifting map pairs consume three complete rounds and then fail visibly');

		$trackers = array();
		for ($round = 0; $round < 3; $round++) {
			$trackers[] = $this->sourceTrackerFixture(array(
				array('http://127.0.0.1:9/a', '0', '1', '0', '1')));
			$trackers[] = $this->sourceTrackerFixture(array(
				array('http://127.0.0.1:9/b', '0', '1', '0', '1')));
		}
		$map = $this->sourceMapFixture();
		$adapter = $this->sourceQueueAdapter(array_fill(0, 6, $scalar),
			array_fill(0, 6, $map), $trackers);
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
		$this->assertTrue($outcome === array('ok' => false,
			'failure' => 'tracker-state-ambiguous') && count($adapter->calls) === 18,
			'three drifting canonical tracker pairs fail without mixing tracker generations');

		$mixed = $this->sourceTrackerFixture(array(
			array('http://127.0.0.1:9/duplicate', '0', '1', '0', '0'),
			array('http://127.0.0.1:9/duplicate', '0', '1', '0', '1'),
		));
		$mixedReordered = $mixed;
		$mixedReordered['rows'] = array_reverse($mixedReordered['rows']);
		$adapter = $this->sourceQueueAdapter(array($scalar, $scalar), array($map, $map),
			array($mixed, $mixedReordered));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->capture(
			$hash, $scalar['values']['recovery_marker']);
