	 * Task 5: Hook installation wiring and safety.
	 * Proves that init.php and done.php use RETRACKERS_IMPORT_ONLY,
	 * do not stop/close/erase in the hook or overwrite no-op in done,
	 * and invoke RetrackersLifecycleCoordinator.
	 */
	public function testTask5InitAndDoneWiringUsesImportOnlyAndAvoidsLegacyHooks()
	{
		$initPath = __DIR__ . '/../../../plugins/retrackers/init.php';
