			'init.php does not rely on legacy custom4 state');

		$this->assertTrue(strpos($doneCode, 'cat=') === false,
			'done.php does not overwrite historical hooks with no-op cat= actions');
		$this->assertTrue(strpos($doneCode, 'getOnInsertCommand') === false,
			'done.php does not use getOnInsertCommand overwrite');

