		$this->assertTrue(strpos($initCode, 'retrackersRunLifecycleInit') !== false,
			'init.php invokes the classified lifecycle initialization seam');
		$this->assertTrue(strpos($doneCode, 'retrackersRunLifecycleDone') !== false,
			'done.php invokes the classified lifecycle teardown seam');
	}

	public function testLifecycleEntrypointDiagnosticsBoundArbitraryCoordinatorFailures()
	{
		if (!function_exists('retrackersRunLifecycleInit') ||
			!function_exists('retrackersRunLifecycleDone')) {
			$this->assertTrue(false,
				'the production lifecycle entrypoint seams publish bounded coordinator failures');
			return;
		}
		$this->installRtorrentQuoteDouble();
		$raw = '<?xml fault="https://tracker.invalid/passkey" path="/private/session">';
		foreach (array($raw, 'receipt-ledger-corrupt') as $reported) {
			$adapter = new class($reported) extends RetrackersLifecycleRpcAdapter {
				private $reported;
				public function __construct($reported) { $this->reported = $reported; }
				public function ensureLedgerExists(&$failure = null) {
					$failure = $this->reported;
					return(false);
				}
			};
			$jResult = '';
			$failure = null;
			$ok = retrackersRunLifecycleInit('alice', '/plugin/run.sh', '/usr/bin/php',
				$jResult, $failure, $adapter);
			$expected = $reported === 'receipt-ledger-corrupt' ?
				'receipt-ledger-corrupt' : 'lifecycle-unsupported';
			$this->assertTrue($ok === false && strpos($jResult, $expected) !== false &&
				strpos($jResult, 'tracker.invalid') === false &&
				strpos($jResult, '/private/session') === false,
				'init exposes only a closed classified failure before activation refusal');
		}

		$adapter = new class($raw) extends RetrackersLifecycleRpcAdapter {
			private $reported;
			public function __construct($reported) { $this->reported = $reported; }
			public function attestLedger(&$failure = null) {
				$failure = $this->reported;
				return(false);
			}
		};
		$jResult = '';
		$failure = null;
		$ok = retrackersRunLifecycleDone('alice', $jResult, $failure, $adapter);
		$this->assertTrue($ok === false && strpos($jResult, 'lifecycle-unsupported') !== false &&
			strpos($jResult, 'tracker.invalid') === false &&
			strpos($jResult, '/private/session') === false,
			'done exposes only a closed classified failure when the coordinator reports raw text');
	}

