	public function testTask3ImmutableStageCreatesDistinctUnlinkedCapabilitiesWithBoundedShortWrites()
	{
		$candidate = str_repeat('candidate-', 8193);
		$original = 'original-metainfo';
		$previousMask = umask(0027);
		$result = $this->anonymousStage($candidate, $original, array('write' => 'short'));
		$observedMask = umask($previousMask);
		$this->assertTrue($observedMask === 0027,
			'the immutable stage restores the caller umask after success');
		if ($result === false) {
			return;
		}
		$stage = $result['stage'];
		$this->assertTrue($stage instanceof RetrackersAnonymousStage && $result['failure'] === null,
			'the complete positive-short-write loop creates one immutable stage');
		if (!$stage instanceof RetrackersAnonymousStage) {
			return;
		}
		$candidateProof = $stage->candidate();
		$originalProof = $stage->original();
		$this->assertTrue(preg_match('#^/proc/[1-9][0-9]*/fd/[0-9]+$#D', $candidateProof['capability']) === 1 &&
			preg_match('#^/proc/[1-9][0-9]*/fd/[0-9]+$#D', $originalProof['capability']) === 1,
			'only decimal procfd capabilities are published');
		$this->assertTrue($candidateProof['dev'] !== $originalProof['dev'] ||
			$candidateProof['ino'] !== $originalProof['ino'],
			'candidate and original retain distinct open-file identities');
		$this->assertTrue(retrackersTestReadCapability($candidateProof['capability']) === $candidate &&
			retrackersTestReadCapability($originalProof['capability']) === $original,
			'both unlinked capabilities remain byte-readable');
		foreach (array($candidateProof, $originalProof) as $proof) {
			$stat = @stat($proof['capability']);
			$this->assertTrue(is_array($stat) && ($stat['mode'] & 0170000) === 0100000 &&
				($stat['mode'] & 0777) === 0600 && $stat['nlink'] === 0 &&
				(string)$stat['size'] === $proof['size'] &&
				hash('sha256', retrackersTestReadCapability($proof['capability'])) === $proof['sha256'],
				'an anonymous capability retains exact regular-file mode, link, size and hash');
		}
		$this->assertTrue(max($stage->writeRequests) <= 65536 && count($stage->writeRequests) > 3,
			'every write request is bounded and positive short writes are retried to completion');
		$this->assertEquals(array(), array_values(array_diff(scandir($result['root']), array('.', '..'))),
			'the proven empty private directory is removed before capability publication');
		$stage->abortBeforeArm();
	}

