	public function testTask3DaemonPreflightSendsExactlyTwoNoShellNonceHashProbes()
	{
		$result = $this->anonymousStage('candidate-preflight', 'original-preflight');
		if ($result === false) {
			return;
		}
		$stage = $result['stage'];
		if (!method_exists('RetrackersWorkerRpcAdapter', 'preflightStage')) {
			$this->assertTrue(false, 'the worker adapter exposes one narrow anonymous-stage preflight');
			$stage->abortBeforeArm();
			return;
		}
		$this->installRawTransportDouble();
		global $scgi_host, $scgi_port;
		$scgi_host = '/tmp/retrackers-test.sock';
		$scgi_port = 0;
		$nonces = array(str_repeat('1', 32), str_repeat('2', 32));
		rSCGITransport::$calls = array();
		rSCGITransport::$returnNull = false;
		rSCGITransport::$raw = $this->tinyStringBatchResponse($nonces);
		$adapter = $this->fixedPreflightAdapter($nonces);
		$failure = null;
		$ok = $adapter->preflightStage($stage, '/configured/php', $failure);
		$payload = rSCGITransport::$calls[0]['arguments'][2];
		$this->assertTrue($ok === true && $failure === null && count(rSCGITransport::$calls) === 1,
			'two procfd checks share one trusted RAW request');
		$this->assertTrue(substr_count($payload, '<name>methodName</name><value><string>execute.capture</string>') === 2 &&
			strpos($payload, '<string>sh</string>') === false && strpos($payload, $result['root']) === false,
			'the request uses two direct execute.capture argv probes and exposes no temporary pathname');
		$this->assertTrue(substr_count($payload, '<name>params</name><value><array><data>' .
			"\r\n<value><string></string></value>\r\n<value><string>/configured/php</string></value>") === 2,
			'both global execute.capture calls carry the empty XMLRPC target before the executable argv');
		$this->assertTrue(strpos($payload, 'proc_open(array("/bin/cat",$a[1])') !== false &&
			strpos($payload, 'fread($pipes[1],65536)') !== false &&
			strpos($payload, 'shell_exec') === false && strpos($payload, 'proc_open("') === false,
			'the frozen probe uses fixed array-form /bin/cat and bounded incremental PHP hashing');
		$this->assertTextOrder($payload, array('$s=@stat($a[1])', '$s["nlink"]!==0',
			'proc_open(array("/bin/cat",$a[1])', '$b=@fread($pipes[1],65536)',
			'$x=@proc_close($p)', '!hash_equals($a[5],hash_final($c))', 'echo $a[6]'),
			'the frozen helper validates identity before an argv-only open, then counts and hashes to clean exit');
		$this->assertTrue(strpos($payload, '!function_exists("proc_open")') !== false &&
			strpos($payload, '!is_resource($p)') !== false && strpos($payload, '$b===false') !== false &&
			strpos($payload, '$l&gt;$r') !== false && strpos($payload, '$err===false') !== false &&
			strpos($payload, '$err!==""') !== false && strpos($payload, '$x!==0') !== false &&
			strpos($payload, '$r!==0') !== false,
			'every missing open, read, byte-count, stderr or exit result is a no-nonce helper failure');
		$probeNonce = str_repeat('a', 32);
		$probeSuccess = $this->runFrozenPreflightProbe($stage->candidate(),
			$stage->candidate()['sha256'], $probeNonce);
		$this->assertTrue(is_array($probeSuccess) && $probeSuccess['status'] === 0 &&
			$probeSuccess['output'] === $probeNonce && $probeSuccess['error'] === '',
			'the configured PHP probe reads the live unlinked capability and emits only its nonce');
		$probeMismatch = $this->runFrozenPreflightProbe($stage->candidate(), str_repeat('0', 64), $probeNonce);
		$this->assertTrue(is_array($probeMismatch) && $probeMismatch['status'] !== 0 &&
			$probeMismatch['output'] === '' && $probeMismatch['error'] === '',
			'a daemon-side capability hash mismatch exits without emitting a nonce');
		foreach (array($stage->candidate(), $stage->original()) as $proof) {
			$this->assertTrue(strpos($payload, '<string>' . $proof['capability'] . '</string>') !== false &&
				strpos($payload, '<string>' . $proof['dev'] . '</string>') !== false &&
				strpos($payload, '<string>' . $proof['ino'] . '</string>') !== false &&
				strpos($payload, '<string>' . $proof['size'] . '</string>') !== false &&
				strpos($payload, '<string>' . $proof['sha256'] . '</string>') !== false,
				'each daemon probe receives only its capability and exact proof values');
		}
		$stage->abortBeforeArm();
	}

