	public function testTask3RecoveryPreflightFailureOccursBeforeEraseArmOrOldMutation()
	{
		$this->installRtorrentQuoteDouble();
		if (!class_exists('FileUtil', false)) {
			require_once(__DIR__ . '/../../../php/util.php');
		}
		if (!class_exists('RetrackersAnonymousStage', false) ||
			!method_exists('RetrackersWorkerRpcAdapter', 'preflightStage')) {
			$this->assertTrue(false, 'the recovery worker exposes immutable staging plus preflight');
			return;
		}
		$hash = str_repeat('A', 40);
		$localId = str_repeat('B', 40);
		$handoff = 'v1:original:0:' . $localId . ':' . hash('sha256', 'alice');
		$snapshot = array(
			'source' => array('path' => '/not-reread'),
			'scalar' => array('state' => '0', 'is_private' => '0', 'name' => 'pkg5-source'),
		);
		$snapshotService = new class($snapshot) {
			private $snapshot;
			public function __construct($snapshot) { $this->snapshot = $snapshot; }
			public function capture($hash, $handoff) { return(array('ok' => true, 'snapshot' => $this->snapshot)); }
		};
		$authority = new class {
			public function prepare($path, $hash, $additions, $deletions, $addToBegin) {
				return(array('ok' => true, 'changed' => true,
					'candidate' => 'candidate-before-arm', 'original' => 'original-before-arm'));
			}
		};
		$adapter = $this->recoveryTestAdapter(array('wp:' . $localId));
		$adapter->preflightResult = false;
		$adapter->preflightFailure = 'procfd-preflight-failed';
		$failure = null;
		$ok = RetrackersRecoveryCoordinator::run($hash, 'alice', $handoff, '0', $localId,
			$adapter, $authority, $snapshotService, null, '/configured/php');
		$methods = array_column($adapter->mutations, 'method');
		$armed = false;
		foreach ($adapter->mutations as $mutation) {
			if ($mutation['method'] === 'method.set_key' && isset($mutation['params'][1]) &&
				substr($mutation['params'][1], 0, 3) === 'ea:' && isset($mutation['params'][2])) {
				$armed = true;
			}
		}
		$this->assertTrue($ok === false, 'failed procfd preflight stops the recovery worker');
		$this->assertTrue(count($adapter->preflightCalls) === 1,
			'failed procfd preflight executes exactly once');
		$this->assertTrue(!$armed, 'failed procfd preflight occurs before ea can be armed');
		$this->assertTrue(count(array_intersect($methods,
			array('d.stop', 'd.close', 'd.erase', 'load.normal', 'load.start'))) === 0,
			'preflight refusal performs no old-object or load mutation');
	}

