	public function testTask4AtomicCommitBuilderFreezesEveryOuterAndInnerCasDimension()
	{
		$this->installRtorrentQuoteDouble();
		if (!class_exists('RetrackersOldGenerationCommitCallback', false)) {
			$this->assertTrue(false,
				'update.php declares the atomic old-generation commit callback');
			return;
		}
		$tx = str_repeat('1', 32);
		$hash = str_repeat('A', 40);
		$snapshot = $this->task4Snapshot('1');
		$handoff = $snapshot['scalar']['recovery_marker'];
		$callback = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $handoff, $snapshot, 16 * 1024 * 1024);
		$this->assertTrue($callback instanceof RetrackersOldGenerationCommitCallback &&
			$callback->method() === 'branch' && count($callback->params()) === 4 &&
			$callback->params()[0] === $hash,
			'the old generation is targeted by one typed direct branch callback');
		if (!($callback instanceof RetrackersOldGenerationCommitCallback)) {
			return;
		}
		$params = $callback->params();
		$grammar = $params[1] . "\n" . $params[2];
		foreach (array(
			'd.local_id=' => 'local id',
			'd.tied_to_file=' => 'tied source',
			'd.loaded_file=' => 'loaded source',
			'math.cnt=(d.custom.keys)' => 'generic map cardinality',
			'd.custom_throw=' => 'generic map membership and value',
			'math.cnt=(t.multicall,,cat=1)' => 'tracker row cardinality',
			't.is_extra_tracker=' => 'tracker topology extra flag',
			't.is_enabled=' => 'tracker enabled state',
			'd.state=' => 'state lifecycle',
			'd.is_active=' => 'active lifecycle',
			'd.is_open=' => 'open lifecycle',
			'd.hashing=' => 'hashing lifecycle',
		) as $needle => $dimension) {
			$this->assertTrue(substr_count($grammar, $needle) >= 2,
				'both CAS layers freeze ' . $dimension);
		}
		$this->assertTextOrder($params[2], array(
			'eb:' . $tx, 'ea:' . $tx, '$d.stop=', '$d.close=', '$branch=',
			'$d.erase=', 'ed:' . $tx, 'ex:' . $tx,
		), 'begin, quiesce, inner CAS, erase, done and terminal tail share one command');
		$this->assertTrue($params[3] === 'cat=RETRACKERS_SKIPPED',
			'outer false returns only the exact skipped sentinel');
		$arm = RetrackersRecoveryPhaseArmCallback::build('ea', $tx);
		$armGrammar = implode("\n", $arm->params());
		$this->assertTrue($arm instanceof RetrackersRecoveryPhaseArmCallback &&
			$arm->params()[0] === '' &&
			substr_count($armGrammar, 'wa:' . $tx) === 1 &&
			substr_count($armGrammar, 'ea:' . $tx) === 2 &&
			strpos($armGrammar, 'eb:' . $tx) !== false &&
			strpos($armGrammar, 'ed:' . $tx) !== false &&
			strpos($armGrammar, 'ex:' . $tx) !== false,
			'ea arms once only under live wa and no prior phase receipt');
		foreach (array('ea', 'eb', 'ed', 'ex') as $prefix) {
			$this->assertTrue(strpos($armGrammar,
				'not=(method.has_key,rr.receipts.v1,' . $prefix . ':' . $tx . ')') !== false,
				$prefix . ' absence uses the live rTorrent parenthesized command form');
		}
		$this->assertTrue(strpos($armGrammar, 'not=\\"method.has_key') === false,
			'phase absence checks never negate a quoted string literal');
	}

	public function testTask4BoundedCommitBuilderOwnsExactEscapedWireAndCap()
	{
		$this->installRtorrentQuoteDouble();
		if (!$this->installRawTransportDouble()) {
			return;
		}
		rSCGITransport::$calls = array();
		if (!method_exists('RetrackersOldGenerationCommitCallback', 'wire') ||
			!method_exists('RetrackersOldGenerationCommitCallback', 'estimatedWireBytes')) {
			$this->assertTrue(false,
				'the bounded callback exposes its one checked wire and exact byte estimate');
			return;
		}
		$tx = str_repeat('8', 32);
		$hash = str_repeat('A', 40);
		$snapshot = $this->task4Snapshot('1');
		$handoff = $snapshot['scalar']['recovery_marker'];
		$snapshot['scalar']['custom1'] = 'slash\\quote"amp&less<greater>';
		$snapshot['generic_map'][] = array(
			'name' => 'name\\"&<>',
			'value' => 'value\\"&<>',
		);
		$failure = null;
		$probe = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $handoff, $snapshot, 16 * 1024 * 1024, $failure);
		$this->assertTrue($probe instanceof RetrackersOldGenerationCommitCallback &&
			$failure === null, 'the escape-heavy snapshot builds below the daemon cap');
		if (!($probe instanceof RetrackersOldGenerationCommitCallback)) {
			$this->assertTrue(false, 'escape estimator parity refused before transport: ' .
				(string)$failure . ' sends=' . count(rSCGITransport::$calls));
			return;
		}
		$expectedWire = retrackersBuildDirectRequest($probe->method(), $probe->params());
		$failure = null;
		$callback = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $handoff, $snapshot, strlen($expectedWire), $failure);
		$this->assertTrue($callback instanceof RetrackersOldGenerationCommitCallback &&
			$failure === null && $callback->wire() === retrackersBuildDirectRequest(
				$callback->method(), $callback->params()) &&
			$callback->estimatedWireBytes() === strlen($callback->wire()),
			'the complete escaped direct request has exact materialised and estimated bytes');
		$failure = null;
		$tooSmall = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $handoff, $snapshot, strlen($expectedWire) - 1, $failure);
		$this->assertTrue($tooSmall === false && $failure === 'commit-request-too-large',
			'the exact complete-wire cap rejects only cap plus one');

		$sealedWire = $callback->wire();
		$changedParams = $callback->params();
		$changedParams[3] .= '-mutated-after-build';
		$paramsProperty = new ReflectionProperty(
			'RetrackersOldGenerationCommitCallback', 'params');
		if (PHP_VERSION_ID < 80100) {
			$paramsProperty->setAccessible(true);
		}
		$paramsProperty->setValue($callback, $changedParams);
		$this->assertTrue(retrackersBuildDirectRequest(
			$callback->method(), $callback->params()) !== $sealedWire,
			'a later callback parameter mutation would produce different rebuilt bytes');
		rSCGITransport::$calls = array();
		rSCGITransport::$returnNull = false;
		rSCGITransport::$raw = $this->tinyRawResponse('<string>RETRACKERS_ERASED</string>');
		$adapter = new RetrackersWorkerRpcAdapter();
		$failure = null;
		$reply = $adapter->executeOldGenerationCommit($callback, $failure);
		$this->assertTrue($reply === 'RETRACKERS_ERASED' && $failure === null &&
			count(rSCGITransport::$calls) === 1 &&
			$callback->wire() === $sealedWire &&
			rSCGITransport::$calls[0]['arguments'][2] === $sealedWire,
			'execution sends the already checked callback wire exactly once byte-for-byte');
	}

