			str_repeat('7', 32), str_repeat('A', 40),
			$snapshot['scalar']['recovery_marker'], $snapshot, 16 * 1024 * 1024, $failure);
		$reordered = $snapshot;
		$reordered['tracker_enabled'] = array_reverse($reordered['tracker_enabled']);
		$reorderedFailure = null;
		$binaryLookup = RetrackersOldGenerationCommitCallback::build(
			str_repeat('7', 32), str_repeat('A', 40),
			$reordered['scalar']['recovery_marker'], $reordered, 16 * 1024 * 1024,
			$reorderedFailure);
