			hash('sha256', $baseline->wire()) : '';
		$this->assertTrue($baseline instanceof RetrackersOldGenerationCommitCallback &&
			$binaryLookup instanceof RetrackersOldGenerationCommitCallback &&
			$failure === null && $reorderedFailure === null &&
			$baseline->wire() === $binaryLookup->wire() &&
			$wireHash === 'da8521f592dfb0e83459d062737389f7543f7e62ab22ba99547db9168bd4e437',
			'repeated topology tuples retain first-occurrence group order, count and original ' .
			'membership order while enabled lookup is reordered; wire=' . $wireHash);
	}

