	public function testTask4OuterAndInnerCasFreezeAllMutableGenerationDimensions()
	{
		$this->installRtorrentQuoteDouble();
		if (!class_exists('RetrackersOldGenerationCommitCallback', false)) {
			$this->assertTrue(false,
				'update.php declares the full old-generation CAS builder');
			return;
		}
		$tx = str_repeat('3', 32);
		$hash = str_repeat('A', 40);
		$original = $this->task4Snapshot('1');
		$handoff = $original['scalar']['recovery_marker'];
		$baseline = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $handoff, $original, 16 * 1024 * 1024)->params();
		$localIdChanged = $original;
		$newLocalId = str_repeat('C', 40);
		$newHandoff = str_replace(str_repeat('B', 40), $newLocalId, $handoff);
		$localIdChanged['scalar']['local_id'] = $newLocalId;
		$localIdChanged['scalar']['recovery_marker'] = $newHandoff;
		$localIdChanged['scalar']['recovery_ack'] = $newHandoff;
		foreach ($localIdChanged['generic_map'] as &$pair) {
			if (in_array($pair['name'], array('retrackers-recovery',
				'retrackers-recovery-ack'), true)) {
				$pair['value'] = $newHandoff;
			}
		}
		unset($pair);
		$localParams = RetrackersOldGenerationCommitCallback::build(
			$tx, $hash, $newHandoff, $localIdChanged, 16 * 1024 * 1024)->params();
		$this->assertTrue($localParams[1] !== $baseline[1] &&
			$localParams[2] !== $baseline[2],
			'local-id participates independently in both outer and post-quiesce CAS');
		$mutations = array(
			'source' => function ($snapshot) { $snapshot['scalar']['loaded_file'] .= '.changed'; return($snapshot); },
			'generic-map' => function ($snapshot) { $snapshot['generic_map'][0]['value'] = 'changed'; return($snapshot); },
			'tracker-topology' => function ($snapshot) { $snapshot['tracker_topology'][0]['extra'] = '1'; return($snapshot); },
			'enabled-state' => function ($snapshot) { $snapshot['tracker_enabled'][0]['state'] = '1'; return($snapshot); },
		);
		foreach ($mutations as $name => $mutate) {
			$changed = $mutate($original);
			$params = RetrackersOldGenerationCommitCallback::build(
				$tx, $hash, $handoff, $changed, 16 * 1024 * 1024)->params();
			$this->assertTrue($params[1] !== $baseline[1] && $params[2] !== $baseline[2],
				$name . ' participates independently in both outer and post-quiesce CAS');
		}
	}

	public function testTask4FreshObservationIsFullStableAndReadOnly()
	{
		$hash = str_repeat('A', 40);
		$original = $this->task4Snapshot('1');
		$scalar = array('family' => $original['family'], 'values' => $original['scalar']);
		$scalar['values']['state'] = '0';
		$scalar['values']['is_active'] = '0';
		$scalar['values']['is_open'] = '0';
		$map = array('family' => $original['family'], 'pairs' => $original['generic_map']);
		$rows = array();
		foreach ($original['tracker_topology'] as $row) {
			$enabled = '0';
			foreach ($original['tracker_enabled'] as $entry) {
				if ($entry['url'] === $row['url']) {
					$enabled = $entry['state'];
					break;
				}
			}
			$rows[] = array($row['url'], $row['group'], $row['type'], $row['extra'], $enabled);
		}
		$trackers = array('family' => $original['family'], 'rows' => $rows);
		$adapter = $this->sourceQueueAdapter(array($scalar, $scalar),
			array($map, $map), array($trackers, $trackers));
		$outcome = (new RetrackersStableSourceSnapshot($adapter))->observe($hash);
		$this->assertTrue(isset($outcome['ok'], $outcome['presence'], $outcome['snapshot']) &&
			$outcome['ok'] === true && $outcome['presence'] === 'present' &&
			$outcome['snapshot']['scalar']['state'] === '0' &&
			$outcome['snapshot']['generic_map'] === $original['generic_map'] &&
			$outcome['snapshot']['tracker_topology'] === $original['tracker_topology'] &&
			$outcome['snapshot']['tracker_enabled'] === $original['tracker_enabled'],
			'reconciliation observes the complete stable post-quiesce generation');
		$this->assertEquals(array('scalar:' . $hash, 'map:' . $hash, 'map:' . $hash,
			'tracker:' . $hash, 'tracker:' . $hash, 'scalar:' . $hash), $adapter->calls,
			'the fresh observation is bounded and read-only');

		$absentAdapter = $this->sourceQueueAdapter(
			array(array('failure' => 'target-absent')), array(), array());
		$absent = (new RetrackersStableSourceSnapshot($absentAdapter))->observe($hash);
		$this->assertTrue($absent === array('ok' => true, 'presence' => 'absent') &&
			$absentAdapter->calls === array('scalar:' . $hash),
			'exact target absence is a terminal observation without extra requests');
	}

