	public function testTask4ReleaseAndCleanupCallbacksAreExactOrderedSingleCommands()
	{
		$this->installRtorrentQuoteDouble();
		$this->assertTrue(class_exists('RetrackersHandoffReleaseCallback', false) &&
			class_exists('RetrackersTerminalCleanupCallback', false),
			'Task 3 declares both narrow typed callbacks');
		if (!class_exists('RetrackersHandoffReleaseCallback', false) ||
			!class_exists('RetrackersTerminalCleanupCallback', false)) {
			return;
		}
		$tx = str_repeat('a', 32);
		$hash = str_repeat('A', 40);
		$localId = str_repeat('B', 40);
		$handoff = 'v1:original:0:' . $localId . ':' . str_repeat('c', 64);
		$release = RetrackersHandoffReleaseCallback::build($tx, $hash, $handoff, $localId);
		$this->assertTrue($release instanceof RetrackersHandoffReleaseCallback &&
			$release->method() === 'branch' && count($release->params()) === 4 &&
			$release->params()[0] === $hash,
			'release is one targeted four-parameter branch');
		$releaseParams = $release->params();
		foreach (array('wa:' . $tx, 'd.local_id=', $localId,
			'd.custom=retrackers-recovery', 'd.custom=retrackers-recovery-ack', $handoff) as $needle) {
			$this->assertTrue(strpos($releaseParams[1], $needle) !== false,
				'release condition freezes ' . $needle);
		}
		$this->assertTextOrder($releaseParams[2], array(
			'd.custom.set=retrackers-recovery-ack,',
			'd.custom.set=retrackers-recovery,',
			'RETRACKERS_HANDOFF_RELEASED',
		), 'release clears acknowledgement before marker and returns its terminal sentinel');
		$this->assertTrue($releaseParams[3] === 'cat=RETRACKERS_HANDOFF_CHANGED' &&
			$release->responsePlan(2) === retrackersRestrictedPlanDirectScalar('string'),
			'release false body and direct string response plan are exact');

		$cleanup = RetrackersTerminalCleanupCallback::build($tx);
		$this->assertTrue($cleanup instanceof RetrackersTerminalCleanupCallback &&
			$cleanup->method() === 'branch' && count($cleanup->params()) === 4 &&
			$cleanup->params()[0] === '',
			'cleanup is one global non-yielding branch callback');
		$cleanupGrammar = implode("\n", $cleanup->params());
		$this->assertTextOrder($cleanupGrammar, array(
			'v1:candidate-ready:' . $tx,
			'v1:rollback-ready:' . $tx,
			'wa:' . $tx,
			'rr-lf-' . $tx,
			'rr-rf-' . $tx,
			'ea:' . $tx, 'eb:' . $tx, 'ed:' . $tx, 'ex:' . $tx,
			'la:' . $tx, 'lb:' . $tx, 'lf:' . $tx,
			'ca:' . $tx, 'cb:' . $tx, 'cd:' . $tx, 'cx:' . $tx,
			'ra:' . $tx, 'rb:' . $tx, 'rf:' . $tx,
			'RETRACKERS_TERMINAL_CLEANED',
		), 'terminal cleanup deletes both capabilities before wa and the ordered suffix');
		$this->assertTrue(preg_match('/(?:d\\.(?:stop|close|erase)|load\\.|d\\.start)/',
			$releaseParams[2] . "\n" . $cleanupGrammar) === 0,
			'release and cleanup contain no object lifecycle operation');
	}

