	public function testTask4FiveBuilderFailuresAbortThenReleaseThenCleanup()
	{
		$this->installRtorrentQuoteDouble();
		$failures = array(
			'runtime-value-unrepresentable',
			'commit-request-limit-invalid',
			'commit-request-too-large',
			'commit-builder-headroom',
			'commit-size-invariant',
		);
		foreach ($failures as $builderFailure) {
			$this->assertTrue(RetrackersRecoveryCoordinator::isDeterministicBuilderFailure(
				$builderFailure), $builderFailure . ' is an exact deterministic pre-arm class');
			$created = $this->anonymousStage('candidate-' . $builderFailure,
				'original-' . $builderFailure);
			if ($created === false || !($created['stage'] instanceof RetrackersAnonymousStage)) {
				continue;
			}
			$stage = $created['stage'];
			$candidateProof = $stage->candidate();
			$originalProof = $stage->original();
			$tx = substr(hash('sha256', $builderFailure), 0, 32);
			$hash = str_repeat('A', 40);
			$localId = str_repeat('B', 40);
			$handoff = 'v1:original:0:' . $localId . ':' . str_repeat('c', 64);
			$keys = array('v1:candidate-ready:' . $tx,
				'v1:rollback-ready:' . $tx, 'wa:' . $tx, 'ea:' . $tx);
			$adapter = $this->recoveryTestAdapter($keys);
			$failure = null;
			$result = RetrackersRecoveryCoordinator::handleCommitFailureBeforeArm(
				$builderFailure, $tx, $hash, $handoff, $localId, $stage, $adapter,
				$failure);
			$methods = array_column($adapter->mutations, 'method');
			$this->assertTrue($result === 'clean' && $failure === null &&
				$adapter->recoveryEvents === array('release', 'cleanup') &&
				count($adapter->releaseCallbacks) === 1 &&
				count($adapter->terminalCleanupCallbacks) === 1,
				$builderFailure . ' follows abort, one release, then one cleanup');
			$this->assertTrue(retrackersTestCapabilityIdentityClosed($candidateProof) &&
				retrackersTestCapabilityIdentityClosed($originalProof) &&
				$adapter->phaseArmCalls === array() && $adapter->oldCommitCalls === array() &&
				count(array_intersect($methods,
					array('d.stop', 'd.close', 'd.erase', 'load.normal', 'load.start'))) === 0,
				$builderFailure . ' closes both capabilities before any ea, commit or load');
			$this->removeTree($created['root']);
		}
		foreach (array('commit-arm-pending', 'commit-dispatch-pending',
			'commit-completion-pending', 'partial-quiesce-ambiguous') as $uncertain) {
			$this->assertTrue(!RetrackersRecoveryCoordinator::isDeterministicBuilderFailure(
				$uncertain), $uncertain . ' stays outside deterministic disposal');
		}
		$untouched = $this->anonymousStage('candidate-uncertain', 'original-uncertain');
		if ($untouched !== false && $untouched['stage'] instanceof RetrackersAnonymousStage) {
			$tx = str_repeat('9', 32);
			$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
			$failure = null;
			$result = RetrackersRecoveryCoordinator::handleCommitFailureBeforeArm(
				'commit-completion-pending', $tx, str_repeat('A', 40),
				'v1:original:0:' . str_repeat('B', 40) . ':' . str_repeat('c', 64),
				str_repeat('B', 40), $untouched['stage'], $adapter, $failure);
			$this->assertTrue($result === 'not-deterministic' &&
				$failure === 'commit-completion-pending' &&
				$adapter->releaseCallbacks === array() &&
				$adapter->terminalCleanupCallbacks === array(),
				'non-builder completion uncertainty is left intact for the caller hold path');
			$untouched['stage']->abortBeforeArm();
			$this->removeTree($untouched['root']);
		}
	}

