	public function testTask4RunDisposesEveryReachablePreFenceFailure()
	{
		$this->installRtorrentQuoteDouble();
		if (!class_exists('FileUtil', false)) {
			require_once(__DIR__ . '/../../../php/util.php');
		}
		$hash = str_repeat('A', 40);
		$snapshot = $this->task4Snapshot('0');
		$localId = $snapshot['scalar']['local_id'];
		$handoff = $snapshot['scalar']['recovery_marker'];
		$cases = array(
			'snapshot' => 'initial-transport',
			'prepare' => 'source-hash-mismatch',
			'stage' => 'stage-input-invalid',
			'preflight' => 'procfd-preflight-failed',
			'fence' => 'candidate-fence-not-implemented',
		);
		foreach ($cases as $kind => $expectedFailure) {
			$snapshotService = new class($snapshot, $kind) {
				private $snapshot;
				private $kind;
				public function __construct($snapshot, $kind) {
					$this->snapshot = $snapshot;
					$this->kind = $kind;
				}
				public function capture($hash, $handoff) {
					return($this->kind === 'snapshot' ?
						array('ok' => false, 'failure' => 'initial-transport') :
						array('ok' => true, 'snapshot' => $this->snapshot));
				}
				public function observe($hash) {
					throw new Exception('pre-fence refusal must not observe a commit');
				}
			};
			$authority = new class($kind) {
				private $kind;
				public function __construct($kind) { $this->kind = $kind; }
				public function prepare($path, $hash, $additions, $deletions, $addToBegin) {
					if ($this->kind === 'prepare') {
						return(array('ok' => false, 'reason' => 'source-hash-mismatch'));
					}
					if ($this->kind === 'stage') {
						return(array('ok' => true, 'changed' => true,
							'candidate' => array(), 'original' => 'original-stage'));
					}
					return(array('ok' => true, 'changed' => true,
						'candidate' => 'candidate-' . $this->kind,
						'original' => 'original-' . $this->kind,
						'projection' => array('ok' => true, 'changed' => true,
							'announce' => 'http://127.0.0.1:9/a?x=1,2',
							'announce_list' => array(
								array('http://127.0.0.1:9/a?x=1,2'),
								array('udp://127.0.0.1:9/b')))));
				}
			};
			$adapter = $this->recoveryTestAdapter(array('wp:' . $localId));
			if ($kind === 'preflight') {
				$adapter->preflightResult = false;
				$adapter->preflightFailure = 'procfd-preflight-failed';
			}
			$result = RetrackersRecoveryCoordinator::run($hash, 'alice', $handoff, '0',
				$localId, $adapter, $authority, $snapshotService, null, '/configured/php');
			$methods = array_column($adapter->mutations, 'method');
			$objectWrites = array_filter($adapter->mutations, function ($mutation) {
				return($mutation['method'] === 'd.custom.set');
			});
			$closed = true;
			if ($kind === 'preflight' || $kind === 'fence') {
				$proofs = isset($adapter->preflightCalls[0]) ?
					$adapter->preflightCalls[0] : array();
				$closed = count($proofs) >= 2 &&
					retrackersTestCapabilityIdentityClosed($proofs[0]) &&
					retrackersTestCapabilityIdentityClosed($proofs[1]);
			}
			$this->assertTrue($result === false &&
				$adapter->recoveryFailure() === $expectedFailure &&
				$adapter->recoveryEvents === array('release', 'cleanup') &&
				count($adapter->releaseCallbacks) === 1 &&
				count($adapter->terminalCleanupCallbacks) === 1 &&
				$adapter->ledgerKeys === array() && $objectWrites === array() && $closed &&
				$adapter->phaseArmCalls === array() && $adapter->oldCommitCalls === array() &&
				count(array_intersect($methods,
					array('d.stop', 'd.close', 'd.erase', 'load.normal', 'load.start'))) === 0,
				$kind . ' refusal releases and cleans the adopted original handoff');
		}
	}

