				public $flags = array();
				public $groups = array();
				public function prepare($path, $hash, $additions, $deletions, $addToBegin) {
					$this->flags[] = $addToBegin;
					$this->groups[] = array($additions, $deletions);
					return(array('ok' => true, 'changed' => false,
						'candidate' => null, 'original' => 'original'));
				}
			};
			$additions = array(array('http://127.0.0.1/b', 'udp://127.0.0.1/a'),
