				count($adapter->releaseCallbacks) === 1 &&
				count($adapter->terminalCleanupCallbacks) === 1,
				'run normalizes shipped addToBegin ' . var_export($case[0], true) .
				' to one exact boolean without bypassing safe no-change release');
		}

		foreach (array('addToBegin', 'dontAddPrivate') as $property) {
		foreach (array(2, -1, 'yes', '', null, '01', ' 0', 0.0, 1.0, array(), new stdClass()) as $invalid) {
			$snapshotService = new class($snapshot) {
				private $snapshot;
				public function __construct($snapshot) { $this->snapshot = $snapshot; }
				public function capture($hash, $handoff) {
					return(array('ok' => true, 'snapshot' => $this->snapshot));
				}
			};
			$authority = new class {
				public $calls = 0;
				public function prepare($path, $hash, $additions, $deletions, $addToBegin) {
					$this->calls++;
					return(array('ok' => true, 'changed' => false));
				}
			};
			$config = (object)array('list' => array(), 'todelete' => array(),
				'addToBegin' => false, 'dontAddPrivate' => false);
			$config->{$property} = $invalid;
			$adapter = $this->recoveryTestAdapter(
				array('wp:' . $localId), array($released));
			$result = RetrackersRecoveryCoordinator::run($hash, 'alice', $handoff, '0',
				$localId, $adapter, $authority, $snapshotService, $config, '/configured/php');
			$this->assertTrue($result === false && $authority->calls === 0 &&
				$adapter->recoveryFailure() === 'runtime-value-unrepresentable' &&
				count($adapter->releaseCallbacks) === 1 &&
				count($adapter->terminalCleanupCallbacks) === 1,
				'an unsupported ' . $property . ' value is classified after adoption and released safely');
