	public function testTask5OmittingAnyBaselineCreationFieldBreaksExactCandidateAndRollbackPlans()
	{
		$this->installRtorrentQuoteDouble();
		if (!class_exists('RetrackersPostEraseObligation', false)) {
			$this->assertTrue(false,
				'Task 5 builds the complete candidate and rollback obligation before old erase');
			return;
		}
		$created = $this->anonymousStage('candidate-task5-plan', 'original-task5-plan');
		if ($created === false || !($created['stage'] instanceof RetrackersAnonymousStage)) {
			return;
		}
		$tx = str_repeat('1', 32);
		$hash = str_repeat('A', 40);
		$snapshot = $this->task4Snapshot('1');
		$projection = array(
			'ok' => true,
			'changed' => true,
			'announce' => 'http://127.0.0.1:9/a?x=1,2',
			'announce_list' => array(
				array('http://127.0.0.1:9/a?x=1,2'),
				array('udp://127.0.0.1:9/b'),
			),
		);
		$failure = null;
		$obligation = RetrackersPostEraseObligation::build(
			$tx, $hash, $created['stage'], $snapshot, $projection, 16 * 1024 * 1024, $failure);
		$this->assertTrue($obligation instanceof RetrackersPostEraseObligation && $failure === null,
			'Task 5 builds the complete candidate and rollback obligation before old erase');
		if (!($obligation instanceof RetrackersPostEraseObligation)) {
			$created['stage']->abortBeforeArm();
			$this->removeTree($created['root']);
			return;
		}
		$candidate = array_values(array_filter(
			$obligation->candidate()->creationCommands(), function ($command) {
				return(strpos($command, 't.multicall=') !== 0);
			}));
		$rollback = array_values(array_filter(
			$obligation->rollback()->creationCommands(), function ($command) {
				return(strpos($command, 't.multicall=') !== 0);
			}));
		$expectedCandidate = array(
			'd.custom.set=retrackers-recovery,"v1:candidate-claim:' . $tx . '"',
			'd.custom.set=retrackers-recovery-ack,""',
			'd.custom.set="awkward,key","line' . "\n" . 'quoted\\"slash\\\\"',
			'd.custom.set="present-empty",""',
			'd.directory_base.set="/data/with,comma"',
			'd.tied_to_file.set=""',
			'd.loaded_file.set=""',
			'd.custom1.set="label"',
			'd.custom2.set=""',
			'd.custom3.set="category"',
			'd.custom4.set="state"',
			'd.custom5.set="fifth"',
			'd.priority.set="2"',
			'd.throttle_name.set="slow"',
		);
		$expectedRollback = $expectedCandidate;
		$expectedRollback[0] = 'd.custom.set=retrackers-recovery,"v1:rollback-claim:' . $tx . '"';
		$this->assertEquals($expectedCandidate,
			array_slice($candidate, 0, count($expectedCandidate)),
			'omitting any candidate baseline field loses frozen state before the replacement hook');
		$this->assertEquals($expectedRollback,
			array_slice($rollback, 0, count($expectedRollback)),
			'omitting any rollback baseline field loses the byte-identical source restoration state');
		$created['stage']->abortBeforeArm();
		$this->removeTree($created['root']);
	}

