$built = is_array($fixture) &&
	$fixture['obligation'] instanceof RetrackersPostEraseObligation;
$cleanupAttempted = false;
$cleanupBuilt = false;
$cleanupFailure = null;
if ($built) {
	$prefixes = $fixture['obligation']->candidate()->validPrefixes();
	$cleanupAttempted = true;
	$cleanupBuilt = RetrackersCandidateCleanupCallback::build(
		str_repeat('2', 32), str_repeat('A', 40),
		$prefixes[count($prefixes) - 1], 16 * 1024 * 1024,
		$cleanupFailure) instanceof RetrackersCandidateCleanupCallback;
}
$originalReadable = is_array($fixture) && isset($fixture['stage']) &&
	$fixture['stage'] instanceof RetrackersAnonymousStage &&
	retrackersTestReadCapability($fixture['stage']->original()['capability']) === 'original-task5';
$result = array(
	'memory_limit' => ini_get('memory_limit'),
	'obligation' => $built,
	'obligation_failure' => is_array($fixture) ? $fixture['failure'] : 'no-fixture',
	'cleanup_attempted' => $cleanupAttempted,
	'cleanup_built' => $cleanupBuilt,
	'cleanup_failure' => $cleanupFailure,
	'original_readable' => $originalReadable,
	'peak' => memory_get_peak_usage(true),
);
echo json_encode($result);
$closeMethod = new ReflectionMethod('RetrackersUpdateTest', 'closeTask5Fixture');
if (PHP_VERSION_ID < 80100) $closeMethod->setAccessible(true);
$closeMethod->invoke($test, $fixture);
$test->tearDownClass();
PHP;
		$descriptors = array(
			0 => array('pipe', 'r'),
			1 => array('pipe', 'w'),
			2 => array('pipe', 'w'),
		);
		$process = proc_open(array(PHP_BINARY, '-d', 'memory_limit=128M', '-r', $script,
			'--', realpath(__DIR__ . '/UpdateTest.php'), (string)$bytes),
			$descriptors, $pipes);
		if (!is_resource($process)) {
			return(false);
		}
		fclose($pipes[0]);
		$output = stream_get_contents($pipes[1]);
		fclose($pipes[1]);
		$error = stream_get_contents($pipes[2]);
		fclose($pipes[2]);
		return(array('status' => proc_close($process), 'output' => $output,
			'error' => $error, 'result' => json_decode($output, true)));
	}

	public function testTask5MissingReservedOrUnsortedGenericKeysCannotEnterCreationPlans()
	{
		$snapshot = $this->task4Snapshot('1');
		$snapshot['generic_map'] = array(
			array('name' => 'z-key', 'value' => 'z'),
			array('name' => 'retrackers-recovery-ack',
				'value' => $snapshot['scalar']['recovery_ack']),
			array('name' => 'A-key', 'value' => 'A'),
			array('name' => 'retrackers-recovery',
				'value' => $snapshot['scalar']['recovery_marker']),
			array('name' => 'a-key', 'value' => 'a'),
		);
		$fixture = $this->task5ObligationFixture($snapshot);
		if ($fixture === false || !($fixture['obligation'] instanceof RetrackersPostEraseObligation)) {
			$this->assertTrue(false,
				'generic keys are decoded-byte sorted while both reserved source keys are proved and replaced');
			$this->closeTask5Fixture($fixture);
			return;
		}
		$commands = $fixture['obligation']->candidate()->creationCommands();
		$generic = array_values(array_filter($commands, function ($command) {
			return(strpos($command, 'd.custom.set="') === 0);
		}));
		$this->assertEquals(array(
			'd.custom.set="A-key","A"',
			'd.custom.set="a-key","a"',
			'd.custom.set="z-key","z"',
		), $generic,
			'unsorted input cannot reorder generic creation or copy either reserved marker key');
		$missing = $snapshot;
		array_splice($missing['generic_map'], 1, 1);
		$missingFixture = $this->task5ObligationFixture($missing);
		$this->assertTrue(is_array($missingFixture) && $missingFixture['obligation'] === false &&
			$missingFixture['failure'] === 'runtime-value-unrepresentable',
			'missing reserved source keys cannot silently become a smaller candidate map');
		$this->closeTask5Fixture($missingFixture);
		$this->closeTask5Fixture($fixture);
	}

