		);
		$snapshot['tracker_enabled'] = array(
			array('url' => 'dht://', 'multiplicity' => 1, 'state' => '1'),
			array('url' => 'http://survive', 'multiplicity' => 1, 'state' => '0'),
			array('url' => 'udp://delete', 'multiplicity' => 1, 'state' => '1'),
		);
		$projection = array('ok' => true, 'changed' => true,
			'announce' => 'http://survive',
			'announce_list' => array(
				array('https://new', 'http://survive'),
				array('udp://new', 'http://survive'),
			));
		$fixture = $this->task5ObligationFixture($snapshot, $projection);
		if ($fixture === false || !($fixture['obligation'] instanceof RetrackersPostEraseObligation) ||
			!method_exists($fixture['obligation']->candidate(), 'expectedTrackerState')) {
			$this->assertTrue(false,
				'candidate projection freezes surviving, new, deleted, duplicate, DHT and 0.9.8 UDP state');
			$this->closeTask5Fixture($fixture);
			return;
		}
		$expected = array(
			'topology' => array(
				array('group' => '0', 'url' => 'http://survive', 'type' => '1', 'extra' => '0'),
				array('group' => '0', 'url' => 'https://new', 'type' => '1', 'extra' => '0'),
				array('group' => '1', 'url' => 'http://survive', 'type' => '1', 'extra' => '0'),
				array('group' => '1', 'url' => 'udp://new', 'type' => '2', 'extra' => '0'),
			),
			'enabled' => array(
				array('url' => 'http://survive', 'multiplicity' => 2, 'state' => '0'),
				array('url' => 'https://new', 'multiplicity' => 1, 'state' => '1'),
				array('url' => 'udp://new', 'multiplicity' => 1, 'state' => '0'),
			),
			'dht_present' => true,
		);
