			'candidate projection freezes surviving, new, deleted, duplicate, DHT and 0.9.8 UDP state');
		$largest = null;
		foreach ($fixture['obligation']->candidate()->validPrefixes() as $tuple) {
			$current = $fixture['obligation']->candidate()->cleanupPlanForTuple($tuple);
			if ($current instanceof RetrackersCandidateCleanupPlan &&
				($largest === null || $current->estimatedWireBytes() >
					$largest->estimatedWireBytes())) {
				$largest = $current;
			}
		}
		$cleanupFailure = null;
		$callback = $largest instanceof RetrackersCandidateCleanupPlan ?
			$largest->materialize($cleanupFailure) : false;
		$this->assertTrue($callback instanceof RetrackersCandidateCleanupCallback &&
			$cleanupFailure === null && strlen($callback->wire()) ===
				$largest->estimatedWireBytes(),
			'a family-1 DHT prefix accepted at 128M materializes the exact preflighted cleanup wire');
		$this->closeTask5Fixture($fixture);
	}

	public function testTask5TopologyAssertionRejectsUnsupportedNormalizedMissingAndExtraRows()
	{
