			'group' => '0', 'type' => '1', 'extra' => '0', 'enabled' => '0');
		$udp = array('url' => 'udp://127.0.0.1:9/b',
			'group' => '1', 'type' => '2', 'extra' => '0', 'enabled' => '1');
