		$cases = array(
			'exact tuple' => array($valid, true),
			'missing disabled row' => array(array($udp), false),
			'extra row' => array(array($http, $udp, $udp), false),
			'normalized type drift' => array(array($http, array_merge($udp,
				array('type' => '1'))), false),
			'group drift' => array(array($http, array_merge($udp,
				array('group' => '0'))), false),
			'extra-bit drift' => array(array(array_merge($http,
				array('extra' => '1')), $udp), false),
			'enabled drift' => array(array(array_merge($http,
				array('enabled' => '1')), $udp), false),
			'unexpected dht row' => array(array($http, $udp, array(
				'url' => 'dht://', 'group' => '2', 'type' => '3',
				'extra' => '0', 'enabled' => '1')), false),
		);
		foreach ($cases as $name => $case) {
			$this->assertTrue($this->task5EvaluateTrackerAssertion(
				$assertion, $case[0]) === $case[1],
