		$this->assertTrue(is_array($sparse) && $sparse['obligation'] === false &&
			$sparse['failure'] === 'candidate-tracker-projection-failed',
			'a sparse or noncanonical announce-list group cannot become an unvalidated tracker group command');
		$this->closeTask5Fixture($sparse);
		$this->closeTask5Fixture($fixture);
	}

	public function testTask5CompleteEncodedLoadWireAcceptsExactLimitAndRejectsLimitPlusOne()
	{
		$fixture = $this->task5ObligationFixture();
		if ($fixture === false || !($fixture['obligation'] instanceof RetrackersPostEraseObligation) ||
			!method_exists($fixture['obligation']->candidate(), 'wire') ||
			!method_exists($fixture['obligation']->candidate(), 'estimatedWireBytes')) {
			$this->assertTrue(false, 'the exact complete load wrapper wire is sealed and size checked before erase');
			$this->closeTask5Fixture($fixture);
			return;
		}
		$plan = $fixture['obligation']->candidate();
		$cleanupLimit = 0;
		$largestCleanup = null;
		foreach ($plan->validPrefixes() as $tuple) {
			$cleanupPlan = $plan->cleanupPlanForTuple($tuple);
			if ($cleanupPlan instanceof RetrackersCandidateCleanupPlan &&
				$cleanupPlan->estimatedWireBytes() > $cleanupLimit) {
				$cleanupLimit = $cleanupPlan->estimatedWireBytes();
				$largestCleanup = $cleanupPlan;
			}
		}
		$limit = max(strlen($plan->wire()),
			strlen($fixture['obligation']->rollback()->wire()), $cleanupLimit);
		$this->assertTrue(strlen($plan->wire()) === $plan->estimatedWireBytes(),
			'the exact escaped XML wire length is measured from the same bytes later dispatched');
		$cleanupFailure = null;
		$cleanupCallback = $largestCleanup instanceof RetrackersCandidateCleanupPlan ?
			$largestCleanup->materialize($cleanupFailure) : false;
		$this->assertTrue($cleanupCallback instanceof RetrackersCandidateCleanupCallback &&
			$cleanupFailure === null && strlen($cleanupCallback->wire()) === $cleanupLimit &&
			$cleanupCallback->estimatedWireBytes() === $cleanupLimit,
			'the largest sealed cleanup plan materializes the exact complete XML length preflighted before erase');
		$failure = null;
		$exact = RetrackersPostEraseObligation::build(str_repeat('2', 32),
			str_repeat('A', 40), $fixture['stage'], $fixture['snapshot'],
			$fixture['projection'], $limit, $failure);
		$tooSmallFailure = null;
		$tooSmall = RetrackersPostEraseObligation::build(str_repeat('2', 32),
			str_repeat('A', 40), $fixture['stage'], $fixture['snapshot'],
			$fixture['projection'], $limit - 1, $tooSmallFailure);
		$this->assertTrue($exact instanceof RetrackersPostEraseObligation &&
			$failure === null && $tooSmall === false &&
			$tooSmallFailure === 'cleanup-request-too-large',
			'exact largest complete XML limit is accepted while cleanup limit plus one is rejected before old mutation');
		$headroom = $this->task5PrefixHeadroomProbe();
		$parts = is_array($headroom) ? explode('|', $headroom['output']) : array();
		$this->assertTrue(is_array($headroom) && $headroom['status'] === 0 &&
			$headroom['error'] === '' && count($parts) === 4 && $parts[0] === '128M' &&
			$parts[1] === 'false' && $parts[2] === 'prefix-builder-headroom' &&
			(int)$parts[3] < 128 * 1024 * 1024,
			'a large finite prefix obligation refuses with explicit headroom before quadratic tuple materialisation or old mutation');
		$this->closeTask5Fixture($fixture);
	}

