	public function testTask5EveryEligibleCleanupPrefixStoresExactWireBeforeEraseAndDispatchesWithoutRebuild()
	{
		$fixture = $this->task5ObligationFixture();
		$candidate = is_array($fixture) &&
			$fixture['obligation'] instanceof RetrackersPostEraseObligation ?
			$fixture['obligation']->candidate() : null;
		$prefixes = $candidate instanceof RetrackersLoadObligation ?
			$candidate->validPrefixes() : array();
		$callbacks = array();
		$allSealed = count($prefixes) > 0;
		foreach ($prefixes as $tuple) {
			$plan = $candidate->cleanupPlanForTuple($tuple);
			if (!($plan instanceof RetrackersCandidateCleanupPlan) ||
				!method_exists($plan, 'callback')) {
				$allSealed = false;
				break;
			}
			$callback = $plan->callback();
			if (!($callback instanceof RetrackersCandidateCleanupCallback) ||
				$callback->wire() === '' || strlen($callback->wire()) !==
					$plan->estimatedWireBytes()) {
				$allSealed = false;
				break;
			}
			$callbacks[] = $callback;
		}
		$this->assertTrue($allSealed && count($callbacks) === count($prefixes),
			'every cleanup-eligible finite prefix owns its exact checked XML callback before old-generation mutation');
		if (!$allSealed || count($callbacks) !== count($prefixes)) {
			$this->closeTask5Fixture($fixture);
			return;
		}
		$tx = str_repeat('2', 32);
		$hash = str_repeat('A', 40);
		$stored = $callbacks[0];
		$storedWire = $stored->wire();
		$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
		$adapter->cleanupCallbackResults = array('RETRACKERS_CANDIDATE_SKIPPED');
		$adapter->cleanupReceiptSequence = array(
			array('begin' => '0', 'done' => '0', 'exit' => '0'));
		$observer = new class($this->task5PresentObservation($prefixes[0])) {
			private $observation;
			public function __construct($observation) { $this->observation = $observation; }
			public function observe($hash) { return($this->observation); }
		};
		$failure = null;
		$result = RetrackersRecoveryCoordinator::cleanupOwnedCandidate(
			$tx, $hash, $candidate, $prefixes[0], $adapter, $observer, $failure);
		$this->assertTrue($result === 'candidate-cleanup-skipped' && $failure === null &&
			count($adapter->cleanupCallbacks) === 1 &&
			$adapter->cleanupCallbacks[0] === $stored &&
			$adapter->cleanupCallbacks[0]->wire() === $storedWire,
			'post-erase cleanup dispatch consumes the identical prechecked stored XML callback without param or wire reconstruction');
		$this->closeTask5Fixture($fixture);
	}

