			unset($fixture, $candidate, $plan);
		}
		if (!($callbacks['1'] instanceof RetrackersCandidateCleanupCallback) ||
			!($callbacks['0'] instanceof RetrackersCandidateCleanupCallback)) {
			$this->assertTrue(false,
				'the emitted cleanup callbacks are available to the independent semantic evaluator');
			return;
		}

		$running = $this->task5EvaluateCleanupCallback($callbacks['1'],
			$this->task5LiteralCleanupModel($tuples['1'], $tx));
		$this->assertTrue($running['result'] === 'RETRACKERS_CANDIDATE_ERASED' &&
			$running['trace'] === array('outer-match', $cb, $ca . '-consume',
				'stop', 'close', 'inner-match', 'erase', $cd, $cx) &&
			$running['model']['exists'] === false &&
			isset($running['model']['ledger'][$wa], $running['model']['ledger'][$cb],
				$running['model']['ledger'][$cd], $running['model']['ledger'][$cx]) &&
			!isset($running['model']['ledger'][$ca]),
			'a running exact tuple executes outer CAS cb ca stop close inner CAS erase cd then terminal cx in order');

		$stopped = $this->task5EvaluateCleanupCallback($callbacks['0'],
			$this->task5LiteralCleanupModel($tuples['0'], $tx));
		$this->assertTrue($stopped['result'] === 'RETRACKERS_CANDIDATE_ERASED' &&
			$stopped['trace'] === array('outer-match', $cb, $ca . '-consume',
				'close', 'inner-match', 'erase', $cd, $cx) &&
			!in_array('stop', $stopped['trace'], true),
			'an already stopped exact tuple omits stop but still closes before inner CAS erase cd and cx');

		$outerModel = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		$outerModel['scalar']['custom1'] = 'concurrent-before-outer';
		$outer = $this->task5EvaluateCleanupCallback($callbacks['1'], $outerModel);
		$this->assertTrue($outer['result'] === 'RETRACKERS_CANDIDATE_SKIPPED' &&
			$outer['trace'] === array('outer-miss') && $outer['model']['exists'] === true &&
			isset($outer['model']['ledger'][$wa], $outer['model']['ledger'][$ca]) &&
			!isset($outer['model']['ledger'][$cb], $outer['model']['ledger'][$cd],
				$outer['model']['ledger'][$cx]),
			'an outer frozen-tuple mismatch writes no cleanup receipt and leaves the candidate untouched');

		$trackerDrifts = array();
		$missing = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		array_pop($missing['trackers']);
		$trackerDrifts[] = $missing;
		$extra = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		$extra['trackers'][] = array('url' => 'https://foreign.invalid/announce',
			'group' => '2', 'type' => '1', 'extra' => '0', 'enabled' => '1');
		$trackerDrifts[] = $extra;
		$duplicate = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		$duplicate['trackers'][] = $duplicate['trackers'][0];
		$trackerDrifts[] = $duplicate;
		$enabled = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		$enabled['trackers'][0]['enabled'] = '0';
		$trackerDrifts[] = $enabled;
		$dht = $this->task5LiteralCleanupModel($tuples['1'], $tx);
		$dht['trackers'][] = array('url' => 'dht://', 'group' => '0',
			'type' => '3', 'extra' => '0', 'enabled' => '1');
		$trackerDrifts[] = $dht;
		$trackerFrozen = true;
		foreach ($trackerDrifts as $model) {
			$evaluated = $this->task5EvaluateCleanupCallback($callbacks['1'], $model);
			$trackerFrozen = $trackerFrozen &&
				$evaluated['result'] === 'RETRACKERS_CANDIDATE_SKIPPED' &&
				$evaluated['trace'] === array('outer-miss') &&
				$evaluated['model']['exists'] === true &&
				isset($evaluated['model']['ledger'][$wa],
					$evaluated['model']['ledger'][$ca]) &&
				!isset($evaluated['model']['ledger'][$cb],
					$evaluated['model']['ledger'][$cd],
					$evaluated['model']['ledger'][$cx]);
		}
		$this->assertTrue($trackerFrozen,
			'missing extra duplicate enabled-drift and unexpected-DHT rows all fail the outer frozen cleanup CAS');

		$inner = $this->task5EvaluateCleanupCallback($callbacks['1'],
			$this->task5LiteralCleanupModel($tuples['1'], $tx),
			array('custom1' => 'concurrent-before-inner'));
		$this->assertTrue($inner['result'] === 'RETRACKERS_CANDIDATE_QUIESCE_CHANGED' &&
			$inner['trace'] === array('outer-match', $cb, $ca . '-consume',
				'stop', 'close', 'inner-miss', $cx) &&
			$inner['model']['exists'] === true &&
			isset($inner['model']['ledger'][$wa], $inner['model']['ledger'][$cb],
				$inner['model']['ledger'][$cx]) &&
			!isset($inner['model']['ledger'][$ca], $inner['model']['ledger'][$cd]),
			'a post-close frozen-tuple mismatch cannot erase or write cd and still reaches terminal cx');
	}

