	public function testTask5EveryPhaseArmIsOneAtomicWaFencedCallbackWithExactCapabilityWrite()
	{
		$this->installRtorrentQuoteDouble();
		$tx = str_repeat('3', 32);
		$expect = array(
			'ea' => array('ea', 'eb', 'ed', 'ex'),
			'la' => array('la', 'lb', 'lf'),
			'ca' => array('ca', 'cb', 'cd', 'cx'),
			'ra' => array('ra', 'rb', 'rf'),
		);
		foreach ($expect as $phase => $keys) {
			$callback = RetrackersRecoveryPhaseArmCallback::build($phase, $tx);
			if (!($callback instanceof RetrackersRecoveryPhaseArmCallback)) {
				$this->assertTrue(false, $phase . ' must be a supported one-shot phase arm');
				continue;
			}
			$grammar = implode("\n", $callback->params());
			$ok = strpos($grammar, 'wa:' . $tx) !== false &&
				strpos($grammar, 'RETRACKERS_PHASE_ARMED') !== false &&
				strpos($grammar, 'RETRACKERS_PHASE_CHANGED') !== false;
			foreach ($keys as $key) {
				$ok = $ok && strpos($grammar, $key . ':' . $tx) !== false;
			}
			if ($phase === 'la') {
				$ok = $ok && strpos($grammar, 'v1:candidate-ready:' . $tx . ',1') !== false;
			} elseif ($phase === 'ra') {
				$ok = $ok && strpos($grammar, 'v1:rollback-ready:' . $tx . ',1') !== false;
			}
			$this->assertTrue($ok, $phase .
				' arm must reject every own phase key and atomically write its exact capability');
		}
	}

	public function testTask5LoadWrapperCannotUseLegacySchedulerOrRegisterAfterBeginOrLoad()
	{
		$fixture = $this->task5ObligationFixture();
		if ($fixture === false || !($fixture['obligation'] instanceof RetrackersPostEraseObligation)) {
			$this->assertTrue(false, 'candidate and rollback wrappers use the canonical ordered scheduler grammar');
			$this->closeTask5Fixture($fixture);
			return;
		}
		foreach (array($fixture['obligation']->candidate(),
			$fixture['obligation']->rollback()) as $plan) {
			$fence = $plan->phase() === 'la' ? 'lf' : 'rf';
			$body = $plan->callback()->params()[2];
			$this->assertTextOrder($body, array(
				'$schedule=', 'method.set_key=rr.receipts.v1,' .
					($plan->phase() === 'la' ? 'lb:' : 'rb:'),
				'method.set_key=rr.receipts.v1,' . $plan->phase() . ':',
				'$' . $plan->loadMethod() . '=', 'RETRACKERS_LOAD_DISPATCHED'),
				'a wrapper must register the exact schedule before begin, arm consumption and load');
			$this->assertTrue(strpos($body,
				'rr-' . $fence . '-' . str_repeat('2', 32)) !== false &&
				strpos($body, 'schedule2') === false &&
				strpos($body, '\\"1\\"') !== false && strpos($body, '\\"0\\"') !== false,
				'a load wrapper cannot change the tx-specific fence schedule name emit schedule2 or use noncanonical first and interval values');
		}
		$this->closeTask5Fixture($fixture);
		global $retrackersUpdateTestCommands;
		$old = $retrackersUpdateTestCommands;
		$retrackersUpdateTestCommands['schedule'] = 'schedule2';
		$retrackersUpdateTestCommands['schedule_remove'] = 'schedule_remove2';
		$legacy = $this->task5ObligationFixture();
		$retrackersUpdateTestCommands = $old;
		$legacyWire = is_array($legacy) &&
			$legacy['obligation'] instanceof RetrackersPostEraseObligation ?
			$legacy['obligation']->candidate()->wire() . "\n" .
				$legacy['obligation']->rollback()->wire() : '';
		$this->assertTrue($legacyWire !== '' &&
			strpos($legacyWire, '$schedule=') !== false &&
			strpos($legacyWire, 'schedule2') === false,
			'a legacy scheduler alias is canonicalized before any candidate or rollback wire is sealed');
		$this->closeTask5Fixture($legacy);
	}

