	public function testReviewPostEventRuntimeTrackersRemainAuthoritative()
	{
		$fixture = $this->task5ObligationFixture();
		$tx = str_repeat('2', 32);
		foreach (array('candidate', 'rollback') as $kind) {
			$plan = $kind === 'candidate' ? $fixture['obligation']->candidate() :
				$fixture['obligation']->rollback();
			foreach (array('http://post-event', 'dht://') as $url) {
				$ready = $this->task5ReadyObservation($plan, $kind, $tx);
				unset($ready['snapshot']['dht_present']);
				$ready['snapshot']['tracker_topology'][] = array('group' => '2',
					'url' => $url, 'type' => $url === 'dht://' ? '3' : '1', 'extra' => '1');
				$ready['snapshot']['tracker_enabled'][] = array('url' => $url,
					'multiplicity' => 1, 'state' => '1');
				$class = $kind === 'candidate' ?
					RetrackersRecoveryCoordinator::classifyCandidateObservation(
						$tx, str_repeat('A', 40), $plan, $ready) :
					RetrackersRecoveryCoordinator::classifyRollbackObservation(
						$tx, str_repeat('A', 40), $ready);
				$this->assertTrue($class === $kind . '-confirmed',
					$kind . ' preserves an authenticated post-event extra ' . $url);
				$claim = $ready;
				$claim['snapshot']['scalar']['hashing_failed'] = '1';
				$marker = 'v1:' . $kind . '-claim:' . $tx;
				$claim['snapshot']['scalar']['recovery_marker'] = $marker;
				$claim['snapshot']['scalar']['recovery_ack'] = '';
				foreach ($claim['snapshot']['generic_map'] as &$pair) {
					if ($pair['name'] === 'retrackers-recovery') { $pair['value'] = $marker; }
					if ($pair['name'] === 'retrackers-recovery-ack') { $pair['value'] = ''; }
				}
				unset($pair);
				if ($kind === 'candidate') {
					$this->assertTrue(RetrackersRecoveryCoordinator::classifyCandidateObservation(
						$tx, str_repeat('A', 40), $plan, $claim) !== 'candidate-partial',
						'an extra post-event row cannot disappear from the partial-cleanup CAS tuple');
				}
			}
		}
		$this->closeTask5Fixture($fixture);
	}

	public function testReviewProductionRoutePollsAndRealShellPreservesEveryArgument()
	{
		$fixture = $this->runWholeTransactionFixture('candidate', function ($adapter) {
			$adapter->loadPhaseReceiptSequence = array(false,
				array('begin' => '0', 'fence' => '0'), array('begin' => '1', 'fence' => '1'));
			array_unshift($adapter->scalarSequence, false);
			$adapter->ledgerReadFailureAt = 3;
		});
		$adapter = $fixture['adapter'];
		$this->assertTrue($fixture['result'] === true &&
			count($adapter->oldCommitCalls) === 1 && count($adapter->loadCallbacks) === 1 &&
			count($adapter->releaseCallbacks) === 1 && count($adapter->terminalCleanupCallbacks) === 1 &&
			$adapter->loadPhaseReceiptReads === 3 && $adapter->scalarReads === 2 &&
			$adapter->ledgerReadCount === 4,
			'the production run route survives delayed load release and cleanup reads without replay');

		global $retrackersUpdateTestProfile;
		$root = $retrackersUpdateTestProfile . "/shell path ' , \\ fixture";
		mkdir($root, 0700);
		copy(__DIR__ . '/../../../plugins/retrackers/run.sh', $root . '/run.sh');
		// Some supported run.sh revisions intentionally discard stdout/stderr.
		// A file receipt tests argv independently of that logging policy.
		file_put_contents($root . '/update.php',
			'<?php file_put_contents(' . var_export($root . '/argv.json', true) .
			', json_encode($argv)); exit(23);');
		symlink(PHP_BINARY, $root . "/php ' , \\ binary");
		$args = array("hash with ' , \\ spaces", '', 'v1:original:0:' . str_repeat('B', 40));
		$process = proc_open(array('/bin/sh', $root . '/run.sh', $root . "/php ' , \\ binary",
			$args[0], $args[1], $args[2]),
			array(0 => array('pipe', 'r'), 1 => array('pipe', 'w'), 2 => array('pipe', 'w')), $pipes);
		$this->assertTrue(is_resource($process), 'the actual run.sh starts through its shell interpreter');
		if (is_resource($process)) {
			fclose($pipes[0]);
			$output = stream_get_contents($pipes[1]);
			$error = stream_get_contents($pipes[2]);
			fclose($pipes[1]);
			fclose($pipes[2]);
			$status = proc_close($process);
			$this->assertTrue($status === 23 && $error === '' &&
				json_decode(file_get_contents($root . '/argv.json'), true) ===
					array_merge(array('./update.php'), $args),
				'the actual run.sh preserves empty and quoted argv and the worker exit status');
		}
		$this->removeTree($root);
	}

	public function testReviewSourceAndResumeTopologyRefuseLossBeforeMutation()
	{
		if (!method_exists('RetrackersPostEraseObligation', 'sourceEligible')) {
			$this->assertTrue(false, 'source and resume topology have an executable pre-erase gate');
			return;
		}
		$this->loadTorrentRuntime();
		$b = function ($s) { return(strlen($s) . ':' . $s); };
		$info = $this->rawInfoFixture();
		$url = 'http://one';
		$projection = array('announce' => $url, 'announce_list' => array(array($url)));
		$snapshot = $this->task4Snapshot();
		$snapshot['tracker_topology'] = array(array('group' => '0', 'url' => $url,
			'type' => '1', 'extra' => '0'));
		$snapshot['tracker_enabled'] = array(array('url' => $url, 'multiplicity' => 1, 'state' => '1'));
		$envelope = '8:announce' . $b($url) . '13:announce-listll' . $b($url) . 'ee';
		$resume = '17:libtorrent_resumed8:trackersd' . $b($url);
		$cases = array(
			'exact source' => array($snapshot, $envelope, '', true),
			'valid resume enabled' => array($snapshot, $envelope, $resume . 'd7:enabledi0eeee', true),
			'valid redundant resume extra' => array($snapshot, $envelope,
				$resume . 'd7:enabledi1e13:extra_trackeri1e5:groupi0eeee', true),
			'wrong resume enabled type' => array($snapshot, $envelope,
				$resume . 'd7:enabled1:0eee', false),
			'wrong resume enabled value' => array($snapshot, $envelope,
				$resume . 'd7:enabledi2eeee', false),
			'negative resume group' => array($snapshot, $envelope,
				$resume . 'd13:extra_trackeri1e5:groupi-1eeee', false),
			'extra without group' => array($snapshot, $envelope,
				$resume . 'd13:extra_trackeri1eeee', false),
			'list where tracker map belongs' => array($snapshot, $envelope,
				'17:libtorrent_resumed8:trackerslee', false),
			'list where resume map belongs' => array($snapshot, $envelope,
				'17:libtorrent_resumele', false),
			'resume non-source endpoint' => array($snapshot, $envelope,
				'17:libtorrent_resumed8:trackersd10:http://twod7:enabledi1eeee', false),
			'list wins over top announce' => array($snapshot,
				'8:announce10:http://two13:announce-listll' . $b($url) . 'ee', '', true),
			'empty and unsupported groups do not consume group numbers' => array($snapshot,
				'13:announce-listllel9:ftp://fooe l' . $b($url) . 'ee', '', true),
			'trimmed source matches daemon URL' => array($snapshot,
				'8:announce' . $b(" \t" . $url . "\r\n"), '', true),
		);
		// Whitespace between bencode values is not legal; this spelling keeps
		// the intentionally empty / unsupported tiers readable in the fixture.
		$cases['empty and unsupported groups do not consume group numbers'][1] =
			str_replace(' ', '', $cases['empty and unsupported groups do not consume group numbers'][1]);
		$extra = $snapshot;
		$extra['tracker_topology'][0]['extra'] = '1';
		$cases['runtime extra is never erased'] = array($extra, $envelope, '', false);
		$drift = $snapshot;
		$drift['tracker_topology'][0]['group'] = '1';
		$cases['source group mismatch'] = array($drift, $envelope, '', false);
		$dht = $snapshot;
		$dht['tracker_topology'][] = array('group' => '1', 'url' => 'dht://', 'type' => '3', 'extra' => '0');
		$dht['tracker_enabled'][] = array('url' => 'dht://', 'multiplicity' => 1, 'state' => '1');
		$cases['one synthetic DHT row'] = array($dht, $envelope, '', true);
		$dht['tracker_topology'][1]['type'] = '1';
		$cases['wrong DHT type'] = array($dht, $envelope, '', false);
		foreach ($cases as $name => $case) {
			$bytes = 'd' . $case[1] . '4:info' . $info . $case[2] . 'e';
			$scan = (new RetrackersBencodeScanner())->scan($bytes, strtoupper(sha1($info)), true);
			$this->assertTrue($scan['ok'] === true, $name . ' fixture is valid canonical bencode');
			$failure = null;
			$result = RetrackersPostEraseObligation::sourceEligible(
				$case[0], $bytes, $scan, $projection, $failure);
			$this->assertTrue($result === $case[3] &&
				$failure === ($case[3] ? null : 'runtime-tracker-topology-mismatch'),
				$name . ' has the exact pre-erase topology verdict');
		}
	}

	public function testReviewLateReceiptsNeverRedispatchAndKnownOutcomesRetire()
	{
		$fixture = $this->task5ObligationFixture();
		$tx = str_repeat('2', 32);
		$hash = str_repeat('A', 40);
		$snapshot = $fixture['snapshot'];
		$observer = $this->task4Observer(array_fill(0, 8,
			array('ok' => true, 'presence' => 'absent')));
		$lateReceipts = array(false,
			array('begin' => '0', 'done' => '0', 'exit' => '0'),
			array('begin' => '1', 'done' => '0', 'exit' => '0'),
			array('begin' => '1', 'done' => '1', 'exit' => '1'));
		$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
		$adapter->oldCommitResult = false;
		$adapter->oldCommitReceiptSequence = $lateReceipts;
		$failure = null;
		$result = RetrackersRecoveryCoordinator::commitOldGeneration($tx, $hash,
			$snapshot['scalar']['recovery_marker'], '1', $snapshot['scalar']['local_id'],
			$snapshot, $adapter, $failure, $observer, null, null, true);
		$this->assertTrue($result === true && $failure === null &&
			$adapter->oldCommitReceiptReads === 4 && count($adapter->oldCommitCalls) === 1 &&
			count($adapter->phaseArmCalls) === 1,
			'a late old-commit receipt completes through reads, never another erase or arm');

		foreach (array($fixture['obligation']->candidate(),
			$fixture['obligation']->rollback()) as $plan) {
			$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
			$adapter->loadCallbackResults = array(false);
			$adapter->loadPhaseReceiptSequence = array(false,
				array('begin' => '0', 'fence' => '0'),
				array('begin' => '1', 'fence' => '0'),
				array('begin' => '1', 'fence' => '1'));
			$result = RetrackersRecoveryCoordinator::dispatchLoadObligation(
				$tx, $plan, $adapter, $failure, true);
			$this->assertTrue($result === true && $failure === null &&
				$adapter->loadPhaseReceiptReads === 4 && count($adapter->loadCallbacks) === 1 &&
				count($adapter->phaseArmCalls) === 1,
				$plan->phase() . ' awaits delayed begin and fence without a second arm or load');
		}
		$candidate = $fixture['obligation']->candidate();
		$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
		$adapter->cleanupCallbackResults = array(false);
		$adapter->cleanupReceiptSequence = $lateReceipts;
		$confirmedId = null;
		$result = RetrackersRecoveryCoordinator::cleanupOwnedCandidate(
			$tx, $hash, $candidate, $candidate->validPrefixes()[0],
			$adapter, $observer, $failure, $confirmedId, true);
		$this->assertTrue($result === 'candidate-cleanup-confirmed' && $failure === null &&
			$adapter->cleanupReceiptReads === 4 && count($adapter->cleanupCallbacks) === 1 &&
			count($adapter->phaseArmCalls) === 1,
			'late cleanup completion is read-only and does not erase twice');

		$marker = 'v1:candidate-ready:' . $tx;
		$adapter = $this->recoveryTestAdapter(array('wa:' . $tx), array(
			array('local_id' => $hash, 'recovery_marker' => $marker, 'recovery_ack' => $marker),
			array('local_id' => $hash, 'recovery_marker' => '', 'recovery_ack' => '')));
		$adapter->releaseResults = array(false);
		$result = RetrackersRecoveryCoordinator::releaseSurvivingHandoff(
			$tx, $hash, $marker, $hash, $adapter, $failure, true);
		$this->assertTrue($result === 'released' && $failure === null &&
			$adapter->scalarReads === 2 && count($adapter->releaseCallbacks) === 1 &&
			$adapter->terminalCleanupCallbacks === array(),
			'a delayed release is observed without retrying the write or cleaning a live lease');

		$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
		$adapter->terminalCleanupResults = array(false);
		$adapter->ledgerReadSequence = array(false, array('wa:' . $tx), array());
		$result = RetrackersRecoveryCoordinator::terminalCleanup($tx, $adapter, $failure, true);
		$this->assertTrue($result === 'clean' && $failure === null &&
			$adapter->ledgerReadCount === 3 && count($adapter->terminalCleanupCallbacks) === 1,
			'unknown and live-wa reads are polled without repeating the full cleanup callback');
		$this->closeTask5Fixture($fixture);

		foreach (array('quiesce-changed', 'partial-quiesce-ambiguous',
			'foreign-generation', 'commit-absent-ambiguous') as $reason) {
			$fixture = $this->task5ObligationFixture();
			$adapter = $this->recoveryTestAdapter(array('wa:' . $tx, 'eb:' . $tx, 'ex:' . $tx));
			$candidate = $fixture['stage']->candidate();
			$original = $fixture['stage']->original();
			$result = RetrackersRecoveryCoordinator::handleCommitFailureBeforeArm($reason,
				$tx, $hash, $snapshot['scalar']['recovery_marker'],
				$snapshot['scalar']['local_id'], $fixture['stage'], $adapter, $failure, true);
			$this->assertTrue($result === 'clean' && $failure === null &&
				count($adapter->terminalCleanupCallbacks) === 1 &&
				$adapter->releaseCallbacks === array() && $adapter->loadCallbacks === array() &&
				$adapter->ledgerKeys === array() &&
				retrackersTestCapabilityIdentityClosed($candidate) &&
				retrackersTestCapabilityIdentityClosed($original),
				$reason . ' is terminal quarantine, not an indefinite lease or a restart');
			$this->closeTask5Fixture($fixture);
		}
	}

	public function testTask5LostArmReplyNeverAuthorizesDispatchFromLaterKeys()
	{
		if (!method_exists('RetrackersRecoveryCoordinator', 'armPostErasePhase')) {
			$this->assertTrue(false, 'lost post-erase arm replies have a sticky pending outcome');
			return;
		}
		$tx = str_repeat('4', 32);
		$cases = array(
			'candidate absent' => array('la', array(), false, 'load-arm-pending'),
			'candidate phase without capability' => array(
				'la', array('la:' . $tx), false, 'load-arm-pending'),
			'candidate complete' => array('la', array(
				'la:' . $tx, 'v1:candidate-ready:' . $tx), false, 'load-arm-pending'),
			'rollback phase without capability' => array(
				'ra', array('ra:' . $tx), false, 'load-arm-pending'),
			'rollback complete' => array('ra', array(
				'ra:' . $tx, 'v1:rollback-ready:' . $tx), false, 'load-arm-pending'),
			'cleanup complete' => array('ca', array('ca:' . $tx), false, 'cleanup-arm-pending'),
		);
		foreach ($cases as $name => $case) {
			$keys = array_merge(array('wa:' . $tx), $case[1]);
			$adapter = $this->recoveryTestAdapter($keys);
			$adapter->phaseArmResults = array(false);
			$failure = null;
			$result = RetrackersRecoveryCoordinator::armPostErasePhase(
				$case[0], $tx, $adapter, $failure);
			$this->assertTrue($result === $case[2] && count($adapter->phaseArmCalls) === 1 &&
				$adapter->mutations === array() && $adapter->terminalCleanupCallbacks === array() &&
				$failure === $case[3],
				$name . ' lost arm reply stays pending despite later keys without retry revoke or cleanup');
		}
	}

