	private function task5UnquoteCommandArgument($value)
	{
		$length = strlen($value);
		if ($length < 2 || $value[0] !== '"' || $value[$length - 1] !== '"') {
			return($value);
		}
		$output = '';
		for ($index = 1; $index < $length - 1; $index++) {
			if ($value[$index] === '\\' && $index + 1 < $length - 1) {
				$index++;
			}
			$output .= $value[$index];
		}
		return($output);
	}

	private function task5SplitCommandArguments($value)
	{
		$parts = array();
		$part = '';
		$quoted = false;
		$escaped = false;
		for ($index = 0; $index < strlen($value); $index++) {
			$byte = $value[$index];
			if ($escaped) {
				$part .= $byte;
				$escaped = false;
				continue;
			}
			if ($byte === '\\' && $quoted) {
				$part .= $byte;
				$escaped = true;
				continue;
			}
			if ($byte === '"') {
				$quoted = !$quoted;
				$part .= $byte;
				continue;
			}
			if ($byte === ',' && !$quoted) {
				$parts[] = $part;
				$part = '';
				continue;
			}
			$part .= $byte;
		}
		$parts[] = $part;
		return($parts);
	}

	private function task5TrackerExpressionValue($expression, array $rows, $row = null)
	{
		if (strncmp($expression, 'cat=', 4) === 0) {
			$value = '';
			foreach ($this->task5SplitCommandArguments(substr($expression, 4)) as $part) {
				$value .= $this->task5UnquoteCommandArgument($part);
			}
			return($value);
		}
		if (strncmp($expression, 'value=', 6) === 0) {
			return(substr($expression, 6));
		}
		$getters = array(
			't.url=' => 'url',
			't.group=' => 'group',
			't.type=' => 'type',
			't.is_extra_tracker=' => 'extra',
			't.is_enabled=' => 'enabled',
		);
		if (is_array($row) && isset($getters[$expression]) &&
			array_key_exists($getters[$expression], $row)) {
			return($row[$getters[$expression]]);
		}
		if ($expression === 'math.cnt=(t.multicall,,cat=1)') {
			// Empty flattened arguments fault on the measured daemon, not zero.
			return(count($rows) === 0 ? null : (string)count($rows));
		}
		foreach (array('math.add=(t.multicall,,' => 'add',
			'math.min=(t.multicall,,' => 'min') as $prefix => $operator) {
			if (strncmp($expression, $prefix, strlen($prefix)) !== 0 ||
				substr($expression, -1) !== ')') {
				continue;
			}
			$project = $this->task5UnquoteCommandArgument(substr(
				$expression, strlen($prefix), -1));
			$values = array();
			foreach ($rows as $tracker) {
				$value = $this->task5TrackerExpressionValue($project, $rows, $tracker);
				if (!is_string($value) || preg_match('/^-?[0-9]+$/D', $value) !== 1) {
					return(null);
				}
				$values[] = (int)$value;
			}
			if ($operator === 'add') {
				return(count($values) === 0 ? null : (string)array_sum($values));
			}
			return(count($values) > 0 ? (string)min($values) : null);
		}
		if (strncmp($expression, 'branch=', 7) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 7));
			if (count($parts) !== 3) {
				return(null);
			}
			$selected = $this->task5EvaluateTrackerPredicate(
				$this->task5UnquoteCommandArgument($parts[0]), $rows, $row) ?
				$parts[1] : $parts[2];
			return($this->task5TrackerExpressionValue(
				$this->task5UnquoteCommandArgument($selected), $rows, $row));
		}
		return(null);
	}

	private function task5EvaluateTrackerPredicate($expression, array $rows, $row = null)
	{
		foreach (array('and=' => true, 'or=' => false) as $prefix => $isAnd) {
			if (strncmp($expression, $prefix, strlen($prefix)) !== 0) {
				continue;
			}
			$parts = $this->task5SplitCommandArguments(
				substr($expression, strlen($prefix)));
			if (count($parts) !== 2) {
				return(false);
			}
			$left = $this->task5EvaluateTrackerPredicate(
				$this->task5UnquoteCommandArgument($parts[0]), $rows, $row);
			$right = $this->task5EvaluateTrackerPredicate(
				$this->task5UnquoteCommandArgument($parts[1]), $rows, $row);
			return($isAnd ? $left && $right : $left || $right);
		}
		if (strncmp($expression, 'not=', 4) === 0) {
			// Captured on both daemon families: not evaluates command objects,
			// but a quoted command is just a nonempty string.
			return(substr($expression, 4) === '(t.multicall,,cat=1)' ?
				count($rows) === 0 : $this->task5UnquoteCommandArgument(substr($expression, 4)) === '');
		}
		if (strncmp($expression, 'equal=', 6) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 6));
			return(count($parts) === 2 &&
				$this->task5TrackerExpressionValue(
					$this->task5UnquoteCommandArgument($parts[0]), $rows, $row) ===
				$this->task5TrackerExpressionValue(
					$this->task5UnquoteCommandArgument($parts[1]), $rows, $row));
		}
		$value = $this->task5TrackerExpressionValue($expression, $rows, $row);
		return(is_string($value) && $value !== '' && $value !== '0');
	}

	private function task5EvaluateTrackerAssertion($command, array $rows)
	{
		if (!is_string($command) || strncmp($command, 'branch=', 7) !== 0) {
			return(false);
		}
		$parts = $this->task5SplitCommandArguments(substr($command, 7));
		return(count($parts) === 3 && $this->task5EvaluateTrackerPredicate(
			$this->task5UnquoteCommandArgument($parts[0]), $rows));
	}

	private function task5LiteralCleanupTuple($capability, $state)
	{
		$tx = str_repeat('2', 32);
		$claim = 'v1:candidate-claim:' . $tx;
		return(array(
			'scalar' => array(
				'local_id' => str_repeat('A', 40),
				'recovery_marker' => $claim,
				'recovery_ack' => '',
				'state' => $state,
				'is_active' => '0',
				'is_open' => '0',
				'hashing' => '0',
				'hashing_failed' => '1',
				'directory_base' => '/data/default',
				'tied_source' => $capability,
				'loaded_file' => $capability,
				'custom1' => '', 'custom2' => '', 'custom3' => '',
				'custom4' => '', 'custom5' => '',
				'priority' => '2', 'throttle_name' => '',
			),
			'generic_map' => array(
				array('name' => 'retrackers-recovery', 'value' => $claim),
			),
			'tracker_topology' => array(
				array('group' => '0', 'url' => 'http://127.0.0.1:9/a?x=1,2',
					'type' => '1', 'extra' => '0'),
				array('group' => '1', 'url' => 'udp://127.0.0.1:9/b',
					'type' => '2', 'extra' => '0'),
			),
			'tracker_enabled' => array(
				array('url' => 'http://127.0.0.1:9/a?x=1,2',
					'multiplicity' => 1, 'state' => '1'),
				array('url' => 'udp://127.0.0.1:9/b',
					'multiplicity' => 1, 'state' => '1'),
			),
			'dht_present' => false,
		));
	}

	private function task5LiteralCleanupModel(array $tuple, $tx)
	{
		$generic = array();
		foreach ($tuple['generic_map'] as $pair) {
			$generic["\0" . $pair['name']] = $pair['value'];
		}
		$states = array();
		foreach ($tuple['tracker_enabled'] as $entry) {
			$states["\0" . $entry['url']] = $entry['state'];
		}
		$trackers = array();
		foreach ($tuple['tracker_topology'] as $row) {
			$key = "\0" . $row['url'];
			$trackers[] = array('url' => $row['url'], 'group' => $row['group'],
				'type' => $row['type'], 'extra' => $row['extra'],
				'enabled' => $states[$key]);
		}
		if ($tuple['dht_present']) {
			$trackers[] = array('url' => 'dht://', 'group' => '0',
				'type' => '3', 'extra' => '0', 'enabled' => '1');
		}
		return(array(
			'exists' => true,
			'scalar' => $tuple['scalar'],
			'generic' => $generic,
			'trackers' => $trackers,
			'ledger' => array('wa:' . $tx => '1', 'ca:' . $tx => '1'),
			'before_inner' => array(),
			'before_inner_applied' => false,
		));
	}

	private function task5CleanupExpressionValue($expression, array &$model, $row = null)
	{
		if (strncmp($expression, 'cat=', 4) === 0) {
			$value = '';
			foreach ($this->task5SplitCommandArguments(substr($expression, 4)) as $part) {
				$value .= $this->task5UnquoteCommandArgument($part);
			}
			return($value);
		}
		if (strncmp($expression, 'value=', 6) === 0) {
			return(substr($expression, 6));
		}
		if (!$model['exists']) {
			return(null);
		}
		$getters = array(
			'd.local_id=' => 'local_id',
			'd.custom=retrackers-recovery' => 'recovery_marker',
			'd.custom=retrackers-recovery-ack' => 'recovery_ack',
			'd.directory_base=' => 'directory_base',
			'd.tied_to_file=' => 'tied_source',
			'd.loaded_file=' => 'loaded_file',
			'd.custom1=' => 'custom1', 'd.custom2=' => 'custom2',
			'd.custom3=' => 'custom3', 'd.custom4=' => 'custom4',
			'd.custom5=' => 'custom5', 'd.throttle_name=' => 'throttle_name',
			'd.state=' => 'state', 'd.is_active=' => 'is_active',
			'd.is_open=' => 'is_open', 'd.hashing=' => 'hashing',
			'd.hashing_failed=' => 'hashing_failed', 'd.priority=' => 'priority',
		);
		if (isset($getters[$expression])) {
			return($model['scalar'][$getters[$expression]]);
		}
		if ($expression === 'math.cnt=(d.custom.keys)') {
			return((string)count($model['generic']));
		}
		if (strncmp($expression, 'd.custom_throw=', 15) === 0) {
			$name = $this->task5UnquoteCommandArgument(substr($expression, 15));
			$key = "\0" . $name;
			return(array_key_exists($key, $model['generic']) ? $model['generic'][$key] : null);
		}
		return($this->task5TrackerExpressionValue(
			$expression, $model['trackers'], $row));
	}

	private function task5EvaluateCleanupPredicate($expression, array &$model, $row = null)
	{
		foreach (array('and=' => true, 'or=' => false) as $prefix => $isAnd) {
			if (strncmp($expression, $prefix, strlen($prefix)) !== 0) {
				continue;
			}
			$parts = $this->task5SplitCommandArguments(
				substr($expression, strlen($prefix)));
			if (count($parts) !== 2) {
				return(false);
			}
			$left = $this->task5EvaluateCleanupPredicate(
				$this->task5UnquoteCommandArgument($parts[0]), $model, $row);
			$right = $this->task5EvaluateCleanupPredicate(
				$this->task5UnquoteCommandArgument($parts[1]), $model, $row);
			return($isAnd ? $left && $right : $left || $right);
		}
		if (strncmp($expression, 'not=', 4) === 0) {
			$argument = substr($expression, 4);
			if (strncmp($argument, '(method.has_key,', 16) === 0 && substr($argument, -1) === ')') {
				return(!$this->task5EvaluateCleanupPredicate(
					'method.has_key=' . substr($argument, 16, -1), $model, $row));
			}
			return($this->task5EvaluateTrackerPredicate($expression, $model['trackers'], $row));
		}
		if (strncmp($expression, 'method.has_key=', 15) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 15));
			return(count($parts) === 2 && $parts[0] === 'rr.receipts.v1' &&
				isset($model['ledger'][$parts[1]]));
		}
		if (strncmp($expression, 'equal=', 6) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 6));
			return(count($parts) === 2 &&
				$this->task5CleanupExpressionValue(
					$this->task5UnquoteCommandArgument($parts[0]), $model, $row) ===
				$this->task5CleanupExpressionValue(
					$this->task5UnquoteCommandArgument($parts[1]), $model, $row));
		}
		$value = $this->task5CleanupExpressionValue($expression, $model, $row);
		return(is_string($value) && $value !== '' && $value !== '0');
	}

	private function task5ExecuteCleanupExpression($expression, array &$model,
		array &$trace)
	{
		if (strncmp($expression, 'cat=', 4) === 0) {
			$result = '';
			foreach ($this->task5SplitCommandArguments(substr($expression, 4)) as $part) {
				$result .= $this->task5ExecuteCleanupExpression(
					$this->task5UnquoteCommandArgument($part), $model, $trace);
			}
			return($result);
		}
		if (strncmp($expression, '$method.set_key=', 16) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 16));
			if (count($parts) < 2 || count($parts) > 3 ||
				$parts[0] !== 'rr.receipts.v1') {
				$trace[] = 'invalid-ledger-command';
				return('');
			}
			$key = $parts[1];
			if (count($parts) === 3) {
				$model['ledger'][$key] = $this->task5UnquoteCommandArgument($parts[2]);
			} else {
				unset($model['ledger'][$key]);
			}
			$trace[] = count($parts) === 2 ? $key . '-consume' : $key;
			return('');
		}
		if ($expression === '$d.stop=') {
			$trace[] = 'stop';
			$model['scalar']['state'] = '0';
			$model['scalar']['is_active'] = '0';
			return('');
		}
		if ($expression === '$d.close=') {
			$trace[] = 'close';
			$model['scalar']['is_open'] = '0';
			$model['scalar']['hashing'] = '0';
			return('');
		}
		if ($expression === '$d.erase=') {
			$trace[] = 'erase';
			$model['exists'] = false;
			return('');
		}
		if (strncmp($expression, '$branch=', 8) === 0) {
			$parts = $this->task5SplitCommandArguments(substr($expression, 8));
			if (count($parts) !== 3) {
				$trace[] = 'invalid-inner-branch';
				return('');
			}
			if (!$model['before_inner_applied']) {
				foreach ($model['before_inner'] as $name => $value) {
					$model['scalar'][$name] = $value;
				}
				$model['before_inner_applied'] = true;
			}
			$matched = $this->task5EvaluateCleanupPredicate(
				$this->task5UnquoteCommandArgument($parts[0]), $model);
			$trace[] = $matched ? 'inner-match' : 'inner-miss';
			return($this->task5ExecuteCleanupExpression(
				$this->task5UnquoteCommandArgument($parts[$matched ? 1 : 2]),
				$model, $trace));
		}
		return($expression);
	}

	private function task5DecodeCleanupWire($wire)
	{
		$prefix = '<?xml version="1.0" encoding="UTF-8"?><methodCall>' .
			'<methodName>branch</methodName><params>';
		$open = '<param><value><string>';
		$close = '</string></value></param>';
		$suffix = '</params></methodCall>';
		if (!is_string($wire) || strncmp($wire, $prefix, strlen($prefix)) !== 0 ||
			substr($wire, -strlen($suffix)) !== $suffix) {
			return(false);
		}
		$offset = strlen($prefix);
		$end = strlen($wire) - strlen($suffix);
		$params = array();
		while ($offset < $end) {
			if (substr($wire, $offset, strlen($open)) !== $open) {
				return(false);
			}
			$offset += strlen($open);
			$next = strpos($wire, $close, $offset);
			if ($next === false || $next > $end) {
				return(false);
			}
			$params[] = htmlspecialchars_decode(
				substr($wire, $offset, $next - $offset), ENT_NOQUOTES);
			$offset = $next + strlen($close);
		}
		return($offset === $end ? $params : false);
	}

	private function task5EvaluateCleanupCallback(
		RetrackersCandidateCleanupCallback $callback, array $model,
		array $beforeInner = array())
	{
		$params = $this->task5DecodeCleanupWire($callback->wire());
		$trace = array();
		if ($callback->method() !== 'branch' || !is_array($params) || count($params) !== 4) {
			return(array('result' => 'invalid-callback', 'trace' => $trace,
				'model' => $model));
		}
		$model['before_inner'] = $beforeInner;
		$model['before_inner_applied'] = false;
		$matched = $this->task5EvaluateCleanupPredicate($params[1], $model);
		$trace[] = $matched ? 'outer-match' : 'outer-miss';
		$result = $this->task5ExecuteCleanupExpression(
			$params[$matched ? 2 : 3], $model, $trace);
		return(array('result' => $result, 'trace' => $trace, 'model' => $model));
	}

	private function task5PresentObservation(array $snapshot)
	{
		return(array('ok' => true, 'presence' => 'present', 'snapshot' => $snapshot));
	}

	private function task5ReadyObservation(RetrackersLoadObligation $plan, $kind, $tx)
	{
		$prefixes = $plan->validPrefixes();
		$snapshot = $prefixes[count($prefixes) - 1];
		$ready = 'v1:' . $kind . '-ready:' . $tx;
		$snapshot['scalar']['recovery_marker'] = $ready;
		$snapshot['scalar']['recovery_ack'] = $ready;
		$snapshot['scalar']['hashing_failed'] = '0';
