			$snapshot['generic_map'], function ($pair) {
				return($pair['name'] !== 'retrackers-recovery' &&
					$pair['name'] !== 'retrackers-recovery-ack');
			}));
		$snapshot['generic_map'][] = array('name' => 'retrackers-recovery',
			'value' => $ready);
		$snapshot['generic_map'][] = array('name' => 'retrackers-recovery-ack',
			'value' => $ready);
