	public function testPostLoadIdentityUsesCapturedLocalIdAndBindsBothCleanupCasLayers()
	{
		$fixture = $this->task5ObligationFixture();
		$tx = str_repeat('2', 32);
		$hash = str_repeat('A', 40);
		// Measured new-generation IDs, not torrent info hashes, from both supported daemons.
		foreach (array('2D6C74304438302DD1DEB352A8C364798AD9775A',
			'2D6C74313031342DD2D7374057935D871D315E0A') as $localId) {
			$ready = $this->task5ReadyObservation($fixture['obligation']->candidate(), 'candidate', $tx);
			$ready['snapshot']['scalar']['local_id'] = $localId;
			$this->assertTrue(RetrackersRecoveryCoordinator::classifyCandidateObservation(
				$tx, $hash, $fixture['obligation']->candidate(), $ready) === 'candidate-confirmed',
				'a captured native local-id authenticates ready without being equal to the info hash');
			$rollback = $this->task5ReadyObservation($fixture['obligation']->rollback(), 'rollback', $tx);
			$rollback['snapshot']['scalar']['local_id'] = $localId;
			$this->assertTrue(RetrackersRecoveryCoordinator::classifyRollbackObservation(
				$tx, $hash, $rollback) === 'rollback-confirmed',
				'rollback likewise accepts its newly allocated native local-id');
			$tuple = $fixture['obligation']->candidate()->validPrefixes()[0];
			$tuple['scalar']['local_id'] = $localId;
			$this->assertTrue(RetrackersRecoveryCoordinator::classifyCandidateObservation(
				$tx, $hash, $fixture['obligation']->candidate(), $this->task5PresentObservation($tuple)) === 'candidate-partial',
				'an exact creation prefix binds the observed native identity after the scheduler fence');
			$plan = $fixture['obligation']->candidate()->cleanupPlanForTuple($tuple);
			$this->assertTrue($plan instanceof RetrackersCandidateCleanupPlan && $plan->matches($tx, $hash, $tuple),
				'presealed cleanup can bind the fixed-width observed identity without changing any other tuple field');
			if ($plan instanceof RetrackersCandidateCleanupPlan) {
				$params = $this->task5DecodeCleanupWire($plan->callback()->wire());
				$this->assertTrue($params[0] === $hash && substr_count(implode('', $params), $localId) === 2 &&
					strlen($plan->callback()->wire()) === $plan->estimatedWireBytes(),
					'only the two CAS identity slots are bound; target hash and exact wire length remain unchanged');
				$model = $this->task5LiteralCleanupModel($tuple, $tx);
				$clean = $this->task5EvaluateCleanupCallback($plan->callback(), $model);
				$foreign = $model;
				$foreign['scalar']['local_id'] = str_repeat('F', 40);
				$outer = $this->task5EvaluateCleanupCallback($plan->callback(), $foreign);
				$inner = $this->task5EvaluateCleanupCallback($plan->callback(), $model,
					array('local_id' => str_repeat('F', 40)));
				$this->assertTrue(!$clean['model']['exists'] && $outer['model']['exists'] &&
					$inner['model']['exists'] && in_array('outer-miss', $outer['trace'], true) &&
					!in_array('erase', $inner['trace'], true),
					'both CAS layers execute against the captured native ID and preserve a replacement before or after quiesce');
			}
			$release = RetrackersHandoffReleaseCallback::build($tx, $hash, 'v1:candidate-ready:' . $tx, $localId);
			$this->assertTrue($release instanceof RetrackersHandoffReleaseCallback &&
				strpos(implode('', $release->params()), $localId) !== false,
				'the release callback fences the observed local-id instead of an invented hash identity');
		}
		$this->closeTask5Fixture($fixture);
		$empty = array('tracker_topology' => array(), 'tracker_enabled' => array(), 'dht_present' => false);
		$assertion = RetrackersPostEraseObligation::trackerAssertionForTuple($empty);
		$this->assertTrue($this->task5EvaluateTrackerPredicate($assertion, array()) &&
			!$this->task5EvaluateTrackerPredicate($assertion, array(array('url' => 'unexpected'))),
			'the empty tracker assertion evaluates the multicall result, not a quoted command name');
		$tuple = $this->task5LiteralCleanupTuple('/proc/123/fd/4', '0');
		$tuple['scalar']['custom1'] = $hash;
		$callback = RetrackersCandidateCleanupCallback::build($tx, $hash, $tuple, 4 * 1024 * 1024);
		$bound = $callback->bindLocalId(str_repeat('B', 40));
		$this->assertTrue(substr_count($callback->wire(), $hash) > 3 &&
			substr_count($bound->wire(), $hash) === substr_count($callback->wire(), $hash) - 2 &&
			substr_count($bound->wire(), str_repeat('B', 40)) === 2,
			'binding cannot replace identical hash-shaped text in user metadata or the XML target');
		$tuple['tracker_topology'] = array();
		$tuple['tracker_enabled'] = array();
		$emptyCleanup = RetrackersCandidateCleanupCallback::build($tx, $hash, $tuple, 4 * 1024 * 1024);
		$clean = $this->task5EvaluateCleanupCallback($emptyCleanup, $this->task5LiteralCleanupModel($tuple, $tx));
		$this->assertTrue(!$clean['model']['exists'],
			'empty cleanup topology uses a boolean emptiness check without empty arithmetic arguments');
		foreach (array('0', '1') as $state) {
			$source = $this->task4Snapshot($state);
			$fixture = $this->task5ObligationFixture($source);
			$plan = $fixture['obligation']->candidate();
			$partial = $plan->validPrefixes()[0];
			// Captured real creation faults on 0.9.8 and 0.16.21: new objects
			// are closed/inactive even when the source was active and open.
			$partial['scalar']['is_active'] = '0';
			$partial['scalar']['is_open'] = '0';
			$this->assertTrue(RetrackersRecoveryCoordinator::classifyCandidateObservation(
				$tx, $hash, $plan, $this->task5PresentObservation($partial)) === 'candidate-partial',
				'a failed creation prefix never inherits source open/active state ' . $state);
			$this->closeTask5Fixture($fixture);
		}
	}

