	public function testTask5RollbackTerminalFailuresNeverCleanupOrThirdLoad()
	{
		$fixture = $this->task5ObligationFixture();
		if ($fixture === false || !($fixture['obligation'] instanceof RetrackersPostEraseObligation) ||
			!method_exists('RetrackersRecoveryCoordinator', 'rollbackOwnedGeneration') ||
			!method_exists('RetrackersRecoveryCoordinator', 'classifyRollbackObservation')) {
			$this->assertTrue(false,
				'rollback partial wrong ack hash failure absence and unknown never trigger a third load');
			$this->closeTask5Fixture($fixture);
			return;
		}
		$tx = str_repeat('2', 32);
		$hash = str_repeat('A', 40);
		$plan = $fixture['obligation']->rollback();
		$ready = $this->task5ReadyObservation($plan, 'rollback', $tx);
		$partial = $plan->validPrefixes()[0];
		$partial['scalar']['hashing_failed'] = '0';
		$failedClaim = $plan->validPrefixes()[0];
		$failedClaimNegative = $plan->validPrefixes()[0];
		$failedClaimNegative['scalar']['hashing_failed'] = '-1';
		$wrongAck = $ready;
		$wrongAck['snapshot']['scalar']['recovery_ack'] = 'wrong';
		foreach ($wrongAck['snapshot']['generic_map'] as &$pair) {
			if ($pair['name'] === 'retrackers-recovery-ack') { $pair['value'] = 'wrong'; }
		}
		unset($pair);
		$hashFailure = $ready;
		$hashFailure['snapshot']['scalar']['hashing_failed'] = '1';
		$hashFailureNegative = $ready;
		$hashFailureNegative['snapshot']['scalar']['hashing_failed'] = '-1';
		$hashFailureMinimum = $ready;
		$hashFailureMinimum['snapshot']['scalar']['hashing_failed'] =
			'-9223372036854775808';
		$hashFailureTwo = $ready;
		$hashFailureTwo['snapshot']['scalar']['hashing_failed'] = '2';
		$hashFailureSeventeen = $ready;
		$hashFailureSeventeen['snapshot']['scalar']['hashing_failed'] = '17';
		$cases = array(
			'partial' => array($this->task5PresentObservation($partial), 'rollback-partial'),
			'failed claim' => array($this->task5PresentObservation($failedClaim),
				'rollback-load-failed'),
			'negative failed claim' => array(
				$this->task5PresentObservation($failedClaimNegative),
				'rollback-load-failed'),
			'wrong ack' => array($wrongAck, 'rollback-unconfirmed'),
			'negative hash failure' => array($hashFailureNegative, 'rollback-load-failed'),
			'minimum i8 hash failure' => array($hashFailureMinimum, 'rollback-load-failed'),
			'hash failure' => array($hashFailure, 'rollback-load-failed'),
			'hash failure 2' => array($hashFailureTwo, 'rollback-load-failed'),
			'hash failure above enum' => array(
				$hashFailureSeventeen, 'rollback-load-failed'),
			'absence' => array(array('ok' => true, 'presence' => 'absent'),
				'rollback-unconfirmed'),
			'unknown' => array(array('ok' => false, 'failure' => 'initial-transport'),
				'rollback-unconfirmed'),
		);
		$foreign = $ready;
		$foreign['snapshot']['scalar']['recovery_marker'] = 'v1:rollback-ready:' . str_repeat('9', 32);
		foreach ($foreign['snapshot']['generic_map'] as &$pair) {
			if ($pair['name'] === 'retrackers-recovery') {
				$pair['value'] = $foreign['snapshot']['scalar']['recovery_marker'];
			}
		}
		unset($pair);
		$cases['foreign'] = array($foreign, 'foreign-generation');
		foreach ($cases as $name => $case) {
			$created = $this->task5ObligationFixture();
			$created['stage']->closeCandidateAfterFence();
			$adapter = $this->recoveryTestAdapter(array('wa:' . $tx));
			$adapter->loadPhaseReceiptSequence = array(
				array('begin' => '1', 'fence' => '1'));
			$observer = new class($case[0]) {
				private $observation;
				public function __construct($observation) { $this->observation = $observation; }
				public function observe($hash) { return($this->observation); }
			};
			$failure = null;
			$result = RetrackersRecoveryCoordinator::rollbackOwnedGeneration(
				$tx, $hash, $created['obligation'], $created['stage'],
				$adapter, $observer, $failure);
			$this->assertTrue($result === false && $failure === $case[1] &&
				count($adapter->loadCallbacks) === 1 &&
				$adapter->cleanupCallbacks === array(),
				$name . ' rollback terminal class cannot cleanup or dispatch a third load');
			$this->closeTask5Fixture($created);
		}
		$this->closeTask5Fixture($fixture);
	}

