	public function testTask5TerminalCleanupIsCapabilityFirstCanonicalAndWaFenced()
	{
		$this->installRtorrentQuoteDouble();
		global $retrackersUpdateTestCommands;
		$old = $retrackersUpdateTestCommands;
		$tx = str_repeat('2', 32);
		try {
			$retrackersUpdateTestCommands['schedule_remove'] = 'schedule_remove2';
			$legacy = RetrackersTerminalCleanupCallback::build($tx);
			$legacyGrammar = $legacy instanceof RetrackersTerminalCleanupCallback ?
				implode("\n", $legacy->params()) : '';
			$this->assertTrue($legacyGrammar !== '' &&
				strpos($legacyGrammar, '$schedule_remove=rr-lf-' . $tx) !== false &&
				strpos($legacyGrammar, 'schedule_remove2') === false,
				'legacy schedule_remove2 is canonicalized before terminal cleanup is sealed');
			$retrackersUpdateTestCommands['schedule_remove'] = 'schedule.remove';
			$callback = RetrackersTerminalCleanupCallback::build($tx);
			$grammar = $callback instanceof RetrackersTerminalCleanupCallback ?
				implode("\n", $callback->params()) : '';
			$order = array(
				'v1:candidate-ready:' . $tx,
				'v1:rollback-ready:' . $tx,
				'wa:' . $tx,
				'$schedule.remove=rr-lf-' . $tx,
				'$schedule.remove=rr-rf-' . $tx,
			);
			$ordered = true;
			$offset = -1;
			foreach ($order as $needle) {
				$position = strpos($grammar, $needle);
				$ordered = $ordered && $position !== false && $position > $offset;
				$offset = $position === false ? $offset : $position;
			}
			$allReceipts = true;
			foreach (array('ea', 'eb', 'ed', 'ex', 'la', 'lb', 'lf',
				'ca', 'cb', 'cd', 'cx', 'ra', 'rb', 'rf') as $prefix) {
				$allReceipts = $allReceipts &&
					substr_count($grammar, $prefix . ':' . $tx) === 1;
			}
			$this->assertTrue($callback instanceof RetrackersTerminalCleanupCallback &&
				$ordered && $allReceipts && strpos($grammar, 'schedule_remove2') === false &&
				RetrackersTerminalCleanupCallback::buildSuffix(
					$tx, array('wa:' . $tx, 'ea:' . $tx)) === false,
				'terminal cleanup drops both capabilities before wa uses canonical removal deletes fourteen receipts and refuses live-wa suffix');
		} finally {
			$retrackersUpdateTestCommands = $old;
		}
	}

