			$legacy->ledgerReadCount === 1 && $legacy->getFamily() === 1 &&
			$legacy->adoptCallbacks === array(),
			'a fresh legacy worker probes the daemon before deciding whether v1 adoption is safe');
		$native = $makeAdapter(2);
